/** 학기·과목 타입은 lib/degree가 SSOT(DegreeSemester/DegreeCourse). d.semesters가 이미 그 타입. */
const sems = (d: DegreeT): DegreeSemester[] => d.semesters;

type DegKey = 'targetTotal' | 'reqMajorReq' | 'reqMajorSel' | 'reqLiberal' | 'targetGpa';

function SemCard({
  sem,
  open,
  onToggle,
  itemOpts,
}: {
  sem: DegreeSemester;
  open: boolean;
  onToggle: (id: string) => void;
  /** T-1 연결 셀렉트의 선택지. ⚠ **부모가 한 번 구독해 내려준다** — 카드마다 `items` 를 구독하면
   *  무관한 항목 편집에 전 학기 카드가 재렌더된다(PL-15 가 피하려던 바로 그 형태). */
  itemOpts: { id: string; name: string }[];
}) {
  const mutate = useApp((s) => s.mutate);

  const findSem = (st: AppState, id: string) => sems(st.degree).find((x) => x.id === id);
  const updSem = (k: keyof DegreeSemester, v: string) =>
    mutate((st) => void (((findSem(st, sem.id) as DegreeSemester)[k] as string) = v));
  const addCourse = () =>
    mutate((st) => {
      findSem(st, sem.id)?.courses.push({
        id: rid(),
        name: '새 과목',
        credits: 3,
        category: '전공선택',
        status: '예정',
        grade: '',
      });
    });
  const delCourse = (cid: string, name: string) => {
    mutate((st) => {
      const s = findSem(st, sem.id);
      if (s) s.courses = s.courses.filter((c) => c.id !== cid);
    });
    toastUndoable(`"${name || '과목'}" 삭제됨`);
  };
  const updCourse = (cid: string, k: keyof DegreeCourse, v: string | number) =>
    mutate((st) => {
      const c = findSem(st, sem.id)?.courses.find((x) => x.id === cid);
      if (c) (c as unknown as Record<string, string | number>)[k] = v;
    });
  /* Q-13 ①단 — 확인창을 뗐다. `mutate` 는 ⌘Z 스택에 pre-image 를 남기므로 이미 되돌릴 수
     있었는데, 종전엔 **확인창을 띄우고 나서** "⌘Z 로 되돌리기"를 알렸다(같은 안전장치 이중 과금).
     사다리 SSOT 는 `shell/destructive.ts`. */
  const delSem = () =>
    commitUndoable('학기 삭제됨 (소속 과목도 함께)', () => {
      mutate((st) => {
        st.degree.semesters = sems(st.degree).filter((s) => s.id !== sem.id);
      });
    });
  /**
   * 수강 과목 → 학습 항목. ⚠⚠ **T-1 이전엔 이 버튼이 다리를 놓고 그 다리를 버렸다** — 항목을
   * 만들기만 하고 `itemId` 를 안 남겨서, 만들어진 순간부터 두 과목은 이름만 같은 남남이었다.
   * 같은 과목 상태가 6화면에 흩어진 근본 원인이 이 한 줄의 부재였다. 이제 **만들면서 잇는다.**
   */
  const courseToItem = (cid: string, name: string) => {
    // PL-15 — items를 구독하지 않고 핸들러 시점에 스냅샷 조회(무관한 items 편집에 카드 재렌더 방지).
    /* ⚠ 후보 목록과 **같은 렌즈**로 찾는다(P10 D6) — 여기만 전체 `items` 를 보면 이름이 같은
       소양 과목에 학기 과목이 붙어 버리고, 셀렉트에는 그 항목이 안 보여 되돌릴 수도 없다. */
    const existing = linkableItems(useApp.getState().state.items).find((s) => s.name === name);
    if (existing) {
      // 이미 있으면 만들지 말고 **잇기만** 한다 — 종전엔 그냥 경고만 하고 끝나서, 이름이 같은
      // 항목이 이미 있는 흔한 경우에 링크가 영영 안 생겼다.
      mutate((st) => {
        const c = findSem(st, sem.id)?.courses.find((x) => x.id === cid);
        if (c) c.itemId = existing.id;
      });
      toast(`"${name}" 이미 있는 학습 항목과 연결했어요.`, 'ok');
      return;
    }
    const created = makeItem({ source: '수강', name });
    mutate((st) => {
      st.items.push(created);
      const c = findSem(st, sem.id)?.courses.find((x) => x.id === cid);
      if (c) c.itemId = created.id;
    });
    toast(`"${name}" 학습 항목에 추가·연결됨 — 주당 시간·챕터·시험을 설정하세요.`, 'ok');
  };

  // PL-14 — 학기 집계는 lib/degree.semesterStat 단일 출처. cr=총학점·doneCr=완료학점·inprog=수강중 과목 수.
  const st = semesterStat(sem);
  const cr = st.tot;
  const doneCr = st.done;
  const inprog = st.inprogCount;
  // PL-8 — 학기 GPA(완료·점수 성적만). 성적 없는 학기는 null → pill 미표시(노이즈 방지).
  const g = semesterGpa(sem);

  const header = (
    <div
      className="ds-itemhead"
      role="button"
      tabIndex={0}
      aria-expanded={open}
      onClick={() => onToggle(sem.id)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onToggle(sem.id);
        }
      }}
    >
      <span className="ds-chev">{open ? '▾' : '▸'}</span>
      <span className="ds-itemname">{sem.name || <span className="text-mut">(이름 없음)</span>}</span>
      <span className="ds-itemmeta">
        <span className="ds-pill ds-tiny">
          {cr}학점 · {sem.courses.length}과목
        </span>
        {doneCr > 0 && <span className="ds-pill ds-tiny ds-good">완료 {doneCr}</span>}
        {inprog > 0 && <span className="ds-pill ds-tiny">수강중 {inprog}</span>}
        {g != null && <span className="ds-pill ds-tiny">GPA {g.toFixed(2)}</span>}
      </span>
    </div>
  );

  if (!open) return <div className="ds-rule ds-itemrow">{header}</div>;

  return (
    <div className="ds-rule ds-itemrow ds-open">
      {header}
      <div className="ds-itembody">
        <div className="ds-fieldgrid" style={{ marginBottom: 10 }}>
          <div className="ds-fld ds-wide">
            <label htmlFor={`sem-name-${sem.id}`}>학기 이름</label>
            <input
              id={`sem-name-${sem.id}`}
              type="text"
              value={sem.name}
              onChange={(e) => updSem('name', e.target.value)}
              style={{ fontWeight: 600 }}
              placeholder="예: 2026-1학기"
            />
          </div>
          {/* ── T-1 학기 계약 — 학기에 **날짜**가 생겼다 ─────────────────────────────────
              왜: 종전 `Semester` 는 `id·name·courses` 뿐이라 **날짜가 없었다.** 그래서 앱은
              "지금이 학기 중인가 방학인가"를 원리적으로 알 수 없었고, 모든 화면이 *지금 상태*만
              그렸다(시간축이 수개월인 시그니처 0). 이 두 칸이 국면(`semesterPhase`)·주차·개강
              D-day 의 **유일한 입력**이다 — 비워 두면 그 과목은 국면 판정에 참여하지 않는다. */}
          <div className="ds-fld">
            <label htmlFor={`sem-start-${sem.id}`}>개강일 (선택)</label>
            <input
              id={`sem-start-${sem.id}`}
              type="date"
              value={sem.startDs || ''}
              onChange={(e) => updSem('startDs', e.target.value)}
            />
          </div>
          <div className="ds-fld">
            <label htmlFor={`sem-end-${sem.id}`}>종강일 (선택)</label>
            <input
              id={`sem-end-${sem.id}`}
              type="date"
              value={sem.endDs || ''}
              onChange={(e) => updSem('endDs', e.target.value)}
            />
          </div>
        </div>
        <div className="ds-chaptbl">
          <table>
            <thead>
              <tr>
                <th style={{ width: '34%' }}>과목</th>
                <th>학점</th>
                <th>구분</th>
                <th>상태</th>
                <th>성적</th>
                <th>학습 항목</th>
                <th />
              </tr>
            </thead>
            <tbody>
              {sem.courses.length ? (
                sem.courses.map((c) => (
                  <tr key={c.id}>
                    <td>
                      <input
                        type="text"
                        value={c.name}
                        onChange={(e) => updCourse(c.id, 'name', e.target.value)}
                        aria-label="과목 이름"
                      />
                    </td>
                    <td>
                      <NumberField
                        min={0}
                        value={c.credits}
                        emptyValue={0} // 학점을 비우면 0학점(청강 등) — 의미 있는 값
                        onCommit={(v) => updCourse(c.id, 'credits', v)}
                        style={{ width: 60 }}
                        aria-label="학점"
                      />
                    </td>
                    <td>
                      <select
                        value={c.category}
                        onChange={(e) => updCourse(c.id, 'category', e.target.value)}
                        aria-label="구분"
                      >
                        {CATS.map((x) => (
                          <option key={x}>{x}</option>
                        ))}
                      </select>
                    </td>
                    <td>
                      <select
                        value={c.status}
                        onChange={(e) => updCourse(c.id, 'status', e.target.value)}
                        aria-label="상태"
                      >
                        {STATUSES.map((x) => (
                          <option key={x}>{x}</option>
                        ))}
                      </select>
                    </td>
                    <td>
                      {/* 자유입력은 오타(P/S 등)가 GPA에서 조용히 누락됐다 → GRADE_POINTS 키 선택으로 고정. */}
                      <select
                        value={c.grade && GRADE_KEYS.includes(c.grade) ? c.grade : ''}
                        onChange={(e) => updCourse(c.id, 'grade', e.target.value)}
                        style={{ width: 68 }}
                        aria-label="성적"
                      >
                        <option value="">—</option>
                        {GRADE_KEYS.map((g) => (
                          <option key={g} value={g}>
                            {g}
                          </option>
                        ))}
                      </select>
                    </td>
                    <td>
                      {/* T-1. **두 우주를 잇는 칸.** 회계 쪽 과목이 실행 쪽 어느 항목인지 명시한다 —
                          이름이 달라도(수강편람 이름 vs 내가 부르는 이름) 이어지게. 링크가 있어야
                          과목 화면이 학점·성적과 챕터·시험을 한 화면에서 말할 수 있다. */}
                      <select
                        value={c.itemId && itemOpts.some((i) => i.id === c.itemId) ? c.itemId : ''}
                        onChange={(e) => updCourse(c.id, 'itemId', e.target.value)}
                        aria-label="학습 항목 연결"
                        style={{ width: 110 }}
                      >
                        <option value="">연결 안 함</option>
                        {itemOpts.map((i) => (
                          <option key={i.id} value={i.id}>
                            {i.name}
                          </option>
                        ))}
                      </select>
                    </td>
                    <td style={{ whiteSpace: 'nowrap' }}>
                      {!c.itemId && (c.status === '수강중' || c.status === '예정') && (
                        <Button sm variant="ghost" title="학습 항목으로" onClick={() => courseToItem(c.id, c.name)}>
                          <Icon name="inbox" />
                        </Button>
                      )}
                      <Button sm variant="ghost" danger onClick={() => delCourse(c.id, c.name)} aria-label="과목 삭제">
                        ✕
                      </Button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="ds-empty ds-tiny" style={{ padding: 12 }}>
                    과목이 없어요. 아래에서 추가하세요.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="ds-row" style={{ marginTop: 8 }}>
          <Button sm variant="primary" onClick={addCourse}>
            + 과목 추가
          </Button>
        </div>
        <div className="ds-itemfoot">
          <span className="ds-tiny text-mut">
            {cr}학점 · {sem.courses.length}과목{doneCr > 0 ? ` · 완료 ${doneCr}학점` : ''}
          </span>
          <Button sm variant="ghost" danger onClick={delSem}>
            학기 삭제
          </Button>
        </div>
      </div>
    </div>
  );
}

function DegreePlan() {
  const d = useApp((s) => s.state.degree);
  const mutate = useApp((s) => s.mutate);
  const degreeCele = useApp((s) => s.state._degreeCele);
  const [openSems, setOpenSems] = useState<Set<string>>(() => new Set());
  const [celeFlash, setCeleFlash] = useState(false);
  const celebrated = useRef(false);

  const toggle = (id: string) =>
    setOpenSems((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  const setDeg = (k: DegKey, v: number) => mutate((st) => void (st.degree[k] = v));
  const addSemester = () => {
    const id = rid();
    // 이름 자동 증가 — 직전 학기가 'YYYY-N학기'면 같은 해 다음 학기(1→2) 또는 다음 해 1학기로 제안(수기 개명 감소).
    const suggestName = (): string => {
      const last = d.semesters[d.semesters.length - 1]?.name || '';
      const mm = last.match(/(\d{4})\s*-\s*([12])\s*학기/);
      if (!mm) return '새 학기';
      const yr = +mm[1]!;
      const term = +mm[2]!;
      return term === 1 ? `${yr}-2학기` : `${yr + 1}-1학기`;
    };
    const name = suggestName();
    mutate((st) => {
      st.degree.semesters.push({ id, name, courses: [] });
    });
    setOpenSems((prev) => new Set(prev).add(id));
  };

  const stats = degreeStats(d);
  const { earned, inprog, planned, byCat, gpa, gradedCr, semDone } = stats;
  const remain = Math.max(0, d.targetTotal - earned);
  const pct = progressPct(d); // 정의는 lib 하나 — 세 화면이 같은 답을 말한다
  const shownPct = useCountUp(Math.min(100, pct)); // 링 기하만 클램프(숫자는 진실을 그대로)
  const list = sems(d);
  // T-1. 연결 셀렉트의 선택지 — **여기서 한 번만** 구독한다(PL-15 · 카드마다 구독하면 무관한 항목
  // 편집에 전 학기 카드가 재렌더된다). immer 라 `items` 가 안 바뀐 변경에서는 참조가 유지된다.
  const items = useApp((s) => s.state.items);
  /* ⚠ P10 D6 — **소양 과목은 후보가 아니다.** 학점으로 안 세는 과목을 `Course` 에 이어 붙이면
     이 화면의 모든 집계(이수 학점·GPA·졸업 진척)가 그 과목을 세기 시작한다. 판정은 `lib/semester`
     하나가 소유한다(`linkableItems`) — 화면이 `kind` 를 직접 보면 후보 목록과 잇기 버튼이 갈린다. */
  const itemOpts = useMemo(
    () => linkableItems(items).map((i) => ({ id: i.id, name: i.name || '(이름 없음)' })),
    [items],
  );
  const avgPerSem = semDone ? earned / semDone : 0;
  const projSem = earned && avgPerSem > 0 ? Math.ceil(remain / avgPerSem) : null;
  // PL-17 — 목표 GPA 역산. 기본값은 현재 GPA를 0.5 단위 올림(없으면 4.0). 저장은 d.targetGpa(옵셔널).
  const defaultTargetGpa = gpa != null ? Math.min(4.5, Math.ceil(gpa * 2) / 2) : 4.0;
  const targetGpa = d.targetGpa ?? defaultTargetGpa;
  const fc = gpaForecast(d, targetGpa);

  // PL-10 — 졸업 요건 100% 최초 충족 축하(1회). 영속 마커 _degreeCele로 재로드 재발화 방지.
  // 재하락(pct<100)해도 마커는 리셋하지 않는다(1회성 모먼트). 링은 짧게 발광 플래시(≤1.4s, reduced-motion 백스톱).
  useEffect(() => {
    if (pct >= 100 && !degreeCele && !celebrated.current) {
      celebrated.current = true; // 마운트당 1회 가드(TodaySignature wasDone 패턴).
      toast('졸업 요건 충족 — 축하해요!', 'info');
      mutate((st) => {
        st._degreeCele = true;
      });
      // 플래시 on/off는 setTimeout으로 비동기 발화 — 이펙트 본문 동기 setState 캐스케이드를 회피.
      const on = setTimeout(() => setCeleFlash(true), 0);
      const off = setTimeout(() => setCeleFlash(false), 1400);
      return () => {
        clearTimeout(on);
        clearTimeout(off);
      };
    }
  }, [pct, degreeCele, mutate]);

  usePageChromeEffect(
    () => ({
      /* W22/H3 — `primary` 는 **필수 키**다(`store/usePageChrome.ts` 머리주석). 이 화면은 렌즈라
         44px 앵커를 세우지 않는다 — 잊은 것이 아니라 없다고 정한 것이다. */
      primary: null,
      readouts: [
        {
          label: '이수',
          value: (
            <>
              {earned}
              <small className="text-base14 font-bold text-mut"> / {d.targetTotal}</small>
            </>
          ),
          accent: true,
        },
        { label: '진행', value: `${pct}%` },
        { label: 'GPA', value: gpa != null ? gpa.toFixed(2) : '—' },
      ],
    }),
    [earned, d.targetTotal, pct, gpa],
  );

  return (
    <>
      {/* T-4·T-15·T-16 — **학기의 경계**. 로드맵(가로 트랙) 바로 아래가 자리다: 트랙이 "어디까지
          왔나"를 말하고, 이 판이 "지금 국면에서 뭘 하나"를 말한다. */}
      <PhaseBoard />
      {/* N-18(W8) — 목표는 국면 **바로 아래**다: 국면이 "지금 어디쯤"이고 목표가 "그래서 어디로".
          학기가 없으면 스스로 사라진다(담을 그릇이 없다). */}
      <SemesterGoals />
      <SeasonRoadmap list={list} targetTotal={d.targetTotal} earned={earned} openIds={openSems} onToggle={toggle} />

      {/* 졸업 현황 — 진행 링 + 게이지 히어로(이수·평점·남은·예상) + 카테고리 바. */}
      <div className="ds-rule">
        <div className="ds-caps mb-3.5">졸업 현황</div>
        <div className="flex flex-wrap items-center gap-7">
          <div
            className={`relative size-23 flex-none${celeFlash ? ' animate-[commit-cele_var(--dur-cele)_var(--ease)] motion-reduce:animate-none' : ''}`}
            role="img"
            aria-label={`졸업 진행 ${pct}%`}
          >
            {/* 카운트업은 다른 링(Stats·Mastery)과 일관 — reduced-motion이면 즉시 최종값. */}
            <ProgressRing
              size={80}
              r={34}
              pct={shownPct}
              className="size-full -rotate-90"
              trackClassName="fill-none stroke-line2 [stroke-width:7]"
              arcClassName="fill-none stroke-good [stroke-width:7] [stroke-linecap:round] [filter:var(--filter-good-glow)] transition-[stroke-dashoffset] duration-draw ease-[var(--ease)]"
            />
            <div className="absolute inset-0 flex items-center justify-center text-2xl font-extrabold tracking-tight text-txt tabular-nums">
              {Math.round(shownPct)}
              <small className="text-sm font-bold text-mut">%</small>
            </div>
          </div>
          <div className="grid min-w-0 flex-1 grid-cols-degree-gauges gap-x-5 gap-y-4">
            <div className="flex flex-col gap-0.75">
              <span className="text-2xl leading-none font-extrabold tracking-tight text-txt tabular-nums">
                {earned}
                <small className="text-sm font-bold text-mut"> / {d.targetTotal}</small>
              </span>
              <span className="text-xs font-semibold text-mut">이수 학점</span>
            </div>
            <div className="flex flex-col gap-0.75">
              <span className="text-2xl leading-none font-extrabold tracking-tight text-txt tabular-nums">
                {gpa != null ? gpa.toFixed(2) : '—'}
                <small className="text-sm font-bold text-mut"> / 4.5</small>
              </span>
              <span className="text-xs font-semibold text-mut">평점(GPA)</span>
            </div>
            <div className="flex flex-col gap-0.75">
              <span className="text-2xl leading-none font-extrabold tracking-tight text-txt tabular-nums">
                {remain}
              </span>
              <span className="text-xs font-semibold text-mut">남은 학점</span>
            </div>
            <div className="flex flex-col gap-0.75">
              <span className="text-2xl leading-none font-extrabold tracking-tight text-txt tabular-nums">
                {projSem != null ? `~${projSem}` : '—'}
              </span>
              <span className="text-xs font-semibold text-mut">예상 잔여 학기</span>
            </div>
          </div>
        </div>
        <div className="mt-3.5 border-t border-line2 pt-3 text-sm text-mut">
          수강중 {inprog} · 예정 {planned}
          {gradedCr > 0 && gradedCr < earned ? ` · 성적 입력 ${gradedCr}/${earned}학점` : ''}
          {earned > 0 && gradedCr === 0 ? (
            <span style={{ color: 'var(--warn)' }}> · 성적을 입력하면 GPA가 계산돼요</span>
          ) : null}
        </div>

        {/* PL-17 — 목표 GPA 역산 계산기: 남은 학점을 평균 몇 점으로 채워야 목표에 닿는지. */}
        <div className="mt-3.5 flex flex-wrap items-center gap-3.5 border-t border-line2 pt-3">
          <div className="flex items-center gap-2">
            <label htmlFor="deg-target-gpa" className="text-xs font-bold tracking-wider text-mut uppercase">
              목표 평점
            </label>
            {/* 클램프는 NumberField가 min/max로 수행 — 비운 채 떠나면 직전 목표가 살아남는다
                (예전엔 '3.5'를 고쳐 치는 도중 빈값이 목표 평점 0으로 확정됐다). */}
            <NumberField
              id="deg-target-gpa"
              min={0}
              max={4.5}
              step={0.1}
              value={targetGpa}
              onCommit={(v) => setDeg('targetGpa', v)}
              className="w-18! tabular-nums"
            />
            <span className="text-sm font-bold text-mut">/ 4.5</span>
          </div>
          <div className="text-md text-txt tabular-nums">
            {gpa == null ? (
              <span className="text-mut">성적을 입력하면 목표까지 필요한 평점을 계산해요.</span>
            ) : fc.alreadyMet ? (
              <span style={{ color: 'var(--good)' }}>이미 목표 달성 ✓</span>
            ) : fc.neededAvg == null ? (
              <span className="text-mut">남은 과목이 없어요.</span>
            ) : (
              <>
                남은 <b className="font-extrabold">{fc.futureCr}</b>학점을 평균{' '}
                <b className="font-extrabold" style={{ color: fc.feasible ? 'var(--good)' : 'var(--bad)' }}>
                  {fc.neededAvg.toFixed(2)}
                </b>
                점으로 이수하면 목표 달성
                {!fc.feasible && <span style={{ color: 'var(--bad)' }}> · 만점으로도 도달 어려움</span>}
              </>
            )}
          </div>
        </div>

        <div className="mt-4 mb-3.5 grid grid-cols-degree-cats gap-3.5">
          {CATS.map((cat) => {
            // ⚠ 삼항 사슬을 여기 다시 쓰지 말 것 — 라벨→요건 매핑의 정본은 `lib/degree.categoryReq`
            //   하나다(M-8). 종전엔 이 자리에 사본이 있었고 타입이 안 잡아 줬다.
            const req = categoryReq(d, cat);
            const have = byCat[cat] || 0;
            // PL-6 — 요건 없는 카테고리(req=0, '기타')는 진행바를 채우지 않는다: 학점이 있어도
            // 100%로 가득 차 '충족'처럼 오도되던 문제 제거 → 중립 트랙 + '요건 없음' 라벨.
            const met = req > 0 && have >= req;
            const cpct = req > 0 ? Math.min(100, Math.round((have / req) * 100)) : 0;
            return (
              <div key={cat} className="flex flex-col gap-1.5">
                <div className="flex items-baseline justify-between">
                  <span className="text-sm font-bold text-mut">{cat}</span>
                  <span className="text-lg font-extrabold tabular-nums">
                    {have}
                    {req > 0 ? (
                      <small className="text-xs font-bold text-mut"> / {req}</small>
                    ) : (
                      <small className="text-xs font-semibold text-mut"> · 요건 없음</small>
                    )}
                    {/* SD-2 requirementRows().met과 동일 의미 — 충족 시 ✓(var(--good)). */}
                    {met && (
                      <span className="font-extrabold text-good" aria-label="충족">
                        {' '}
                        ✓
                      </span>
                    )}
                  </span>
                </div>
                <div className="h-1.75 overflow-hidden rounded-full bg-track-cat">
                  {req > 0 && (
                    <i
                      style={{ width: `${cpct}%` }}
                      className={
                        met
                          ? 'block h-full rounded-full bg-acc shadow-node'
                          : 'block h-full rounded-full bg-track-fill-cat'
                      }
                    />
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <details className="mt-3.5 border-t border-line2 pt-3">
          <summary className="text-sm! font-bold text-mut! hover:text-acc!">졸업 요건 설정</summary>
          <div className="ds-row" style={{ marginTop: 10 }}>
            <div>
              <label htmlFor="deg-total">졸업 총 학점</label>
              <NumberField id="deg-total" min={0} value={d.targetTotal} onCommit={(v) => setDeg('targetTotal', v)} />
            </div>
            <div>
              <label htmlFor="deg-req">전공필수</label>
              <NumberField id="deg-req" min={0} value={d.reqMajorReq} onCommit={(v) => setDeg('reqMajorReq', v)} />
            </div>
            <div>
              <label htmlFor="deg-sel">전공선택</label>
              <NumberField id="deg-sel" min={0} value={d.reqMajorSel} onCommit={(v) => setDeg('reqMajorSel', v)} />
            </div>
            <div>
              <label htmlFor="deg-lib">교양</label>
              <NumberField id="deg-lib" min={0} value={d.reqLiberal} onCommit={(v) => setDeg('reqLiberal', v)} />
            </div>
          </div>
        </details>
      </div>

      <div className="ds-rule">
        <div className="ds-row" style={{ alignItems: 'center' }}>
          <h2 style={{ flex: 1, margin: 0 }}>
            학기별 수강{' '}
            <span className="ds-tiny text-mut" style={{ fontWeight: 400 }}>
              {list.length ? `(${list.length})` : ''}
            </span>
          </h2>
          {list.length > 1 && (
            <>
              <Button sm variant="ghost" onClick={() => setOpenSems(new Set(list.map((s) => s.id)))}>
                모두 펼치기
              </Button>
              <Button sm variant="ghost" onClick={() => setOpenSems(new Set())}>
                모두 접기
              </Button>
            </>
          )}
          <Button sm variant="primary" onClick={addSemester}>
            + 학기 추가
          </Button>
        </div>
      </div>

      {list.map((s) => (
        <SemCard key={s.id} sem={s} open={openSems.has(s.id)} onToggle={toggle} itemOpts={itemOpts} />
      ))}
    </>
  );
}

/* ⚠⚠ **`goals`(내 길 지도)가 이 탭의 세 번째 뷰가 됐다**(W9 · 2026-08-06 · IA 판정표).
   둘 다 답하는 질문이 **"졸업까지의 길"** 이다 — 여기가 그 길의 *회계*(학점·요건·GPA)이고
   내 길이 그 길의 *이유*(목표 트리·필요 역량)다. 계획 세그먼트 다섯 중 둘이 같은 질문의 두 면
   이었고, 그래서 "멀리 보는 화면"의 착지가 어느 이름을 기억하느냐로 갈렸다.
   ⚠ **lazy** — 목표 트리는 지식엔진 쿼리 셋을 문다(콜드면 안내문). 학점만 보러 온 방문에
     그 코드를 내려받을 이유가 없다(`graph`→`items` 이식과 같은 판단).

   ⚠⚠ **뷰가 URL 에 있다**(종전엔 `useState`). 은퇴한 `goals` 탭의 착지 경로가
   `/degree?view=path` 이므로, 상태가 메모리에만 있으면 그 리다이렉트가 **기본 뷰(졸업 계획)에
   착지**한다 — 화면은 떴는데 찾던 것이 없는, 가장 알아채기 어려운 형태의 도달성 손실이다. */
const Goals = lazy(() => import('./PathView'));

/* ⚠⚠ **W8(2026-08-07) — 학기의 입구와 출구가 여기 붙는다**(N-2 인입구 · N-3 결산).
   왜 새 탭이 아닌가: 둘 다 **학기라는 명사**의 두 끝이고, 그 명사의 회계를 쥔 화면이 여기다.
   이 저장소는 "학습 상태 소비 0"인 화면을 새 탭으로 세웠다가 다섯 번 강등한 이력이 있다 —
   뷰로 내리면 도달성(⌘K·딥링크·`?view=`)은 그대로이고 레일 한 칸을 안 쓴다.
   ⚠ 둘 다 **lazy** 다: 인입구는 파서를, 결산은 완료 기록 전수 스캔을 문다. 학점만 보러 온
   방문에 그 코드를 내려받을 이유가 없다(`PathView` 와 같은 판단). */
const Intake = lazy(() => import('./SyllabusIntake'));
/** I008 — `.ics` 인입구. 같은 뷰에 사는 이유는 그 파일 머리주석(«학교에서 받은 것을 어디에 넣나»). */
const CalIntake = lazy(() => import('./CalendarIntake'));
const Close = lazy(() => import('./SemesterClose'));

type DegView = 'plan' | 'req' | 'intake' | 'close' | typeof DEGREE_PATH_VIEW;
/* ⚠⚠ **여기 `const VIEWS` 5칸이 손으로 적혀 있었다 — 로스터에서 파생한다**(I025 · 2026-08-22).
   D-4 가 «갈 수 있는 곳의 열거 다섯 벌»을 하나로 만들었는데, W9 이 탭 셋을 뷰로 접자 같은 바가
   이 파일 안에서 **다시 자랐다.** 그리고 실제로 갈려 있었다: 이 배열의 넷(`intake`·`close`·
   `req`·`path`)이 `shell/tabs.ts` 로스터에는 **아예 없어서**, 그 화면들은 아나운서 이름도 ⌘K 도
   자기 방문 집계도 갖지 못했다(H-12·I034 가 각각 이름 축·관측 축에서 고친 그 결함이 여기 남아
   있었다). 이제 로스터 한 곳이 넷 다 준다.
   ⚠ 기본 뷰(`plan`)만 여기 남는다 — 그건 뷰가 아니라 **탭 자신**이라 로스터의 `degree` 가 진다. */
const HOST_VIEWS = viewsOfHost('degree');
const VIEWS: { key: DegView; label: string }[] = [
  { key: 'plan', label: tabByKey('degree')?.label ?? '졸업 계획' },
  ...HOST_VIEWS.map((t) => ({ key: viewValueOf(t) as DegView, label: t.segLabel ?? t.label })),
];

/** 졸업 탭 — 계획(편집)·요건 정리(읽기전용)·내 길(목표 트리)을 세그먼트로 전환. 기본은 '졸업 계획'. */
/**
 * **학기 지문**(N-22 · W6) — 그리지 않고 **자란다**.
 *
 * 학기가 끝나면 남는 시각 자산이 0이었다. 여기 도형은 전부 그 학기의 실제 값에서 나온다:
 * 가지 수 = 과목 수 · 길이 = 실제 투입 시간 · 각도 = id 해시(색과 **같은 파생 키**).
 * 즉 균등하게 한 학기와 한 과목에 몰린 학기는 **다르게 생긴다** — 그 명제가 이 안의 유일한
 * 검증이고 `test/semesterFingerprint.test.ts` 가 잠근다.
 *
 * ⚠ 자리를 **크게 안 준다**(28px). 이건 조망이 아니라 *표식*이고, 크게 그리면 그 순간
 *   "숫자를 읽는 화면"과 겨룬다(원칙 ⑤ 단일 포커스).
 * ⚠ 색은 `colorForId` — 여기서 정하지 않는다(절대규칙 #3).
 * ⚠ 과목이 없으면 **아무것도 안 그린다**: 빈 지문은 장식이고, 장식은 이 항목이 거부한 것이다.
 */
function SemesterFingerprint() {
  const state = useApp((s) => s.state);
  const branches = useMemo(() => semesterFingerprint(investedBySubject(state)), [state]);
  if (!branches.length) return null;
  return (
    <svg viewBox="0 0 100 100" className="size-7 shrink-0 opacity-70" role="img" aria-label="이번 학기 지문">
      {branches.map((b) => (
        <path key={b.id} d={b.d} fill="none" stroke={colorForId(b.id)} strokeWidth={5} strokeLinecap="round" />
      ))}
    </svg>
  );
}

export default function Degree() {
  const [params, setParams] = useSearchParams();
  const raw = params.get('view');
  const view: DegView = VIEWS.some((v) => v.key === raw) ? (raw as DegView) : 'plan';
  return (
    <div className="min-w-0">
      <div className="mb-4 flex items-center gap-3.5">
        <h2 className="ds-caps mb-0! flex items-center gap-1.5">
          <Icon name="cap" /> 졸업
        </h2>
        <SemesterFingerprint />
        <div className="ds-seg ml-auto">
          {VIEWS.map((v) => (
            <button
              key={v.key}
              type="button"
              aria-pressed={view === v.key}
              className={view === v.key ? 'ds-on' : ''}
              onClick={() => {
                const p = new URLSearchParams(params);
                if (v.key === 'plan') p.delete('view');
                else p.set('view', v.key);
                setParams(p, { replace: true });
              }}
            >
              {v.label}
            </button>
          ))}
        </div>
      </div>
      {view === DEGREE_PATH_VIEW ? (
        <Suspense fallback={<State kind="loading" title="내 길 여는 중…" shape="frame" />}>
          <Goals />
        </Suspense>
      ) : view === 'intake' ? (
        <Suspense fallback={<State kind="loading" title="인입구 여는 중…" shape="frame" />}>
          <CalIntake />
          <Intake />
        </Suspense>
      ) : view === 'close' ? (
        <Suspense fallback={<State kind="loading" title="결산 여는 중…" shape="frame" />}>
          <Close />
        </Suspense>
      ) : view === 'req' ? (
        <DegreeReq />
      ) : (
        <DegreePlan />
      )}
    </div>
  );
}

/* ============================================================
   TelemetryConsole — 연동 텔레메트리(연동 시그니처). 백엔드·볼트·Anki 연결을
   라이브 채널 리드아웃으로(● ONLINE/IDLE/OFFLINE). 시스템 폴더 /api 연동의 "조종석".
   상태는 Query 캐시 구독(enabled:false로 fetch 없이 읽기) + usePing. 순수 표현에 가깝되 상태는 store/query에서.
============================================================ */
import { useEffect, useState } from 'react';
import { useQuery, skipToken } from '@tanstack/react-query';
import { bootWave } from '@/lib/perf';
import { quietSummary } from '@/lib/daySignals';
import { usePing } from '@/store/queries';
import { totalDue, totalCards, type AnkiLive, type AnkiFile } from '@/lib/anki';
import type { VaultScan } from '@/lib/vault';
import { Button } from '@/components/ui';
import { shellHotkeyRetry, shellVaultWatchRetry } from '@/lib/tauri';
import { toast } from '@/shell/toast';
import type { ReactNode } from 'react';

type Status = 'online' | 'idle' | 'offline' | 'probing';
const STATUS_LABEL: Record<Status, string> = {
  online: 'ONLINE',
  idle: 'IDLE',
  offline: 'OFFLINE',
  probing: '…',
};

// 상태별 정적 클래스 맵(동적 조립 금지 · §15 부칙) — 옛 `.online .dot`/`.online .chVal` 등 관계형 규칙을
// 자식에 직접 준다(규약 4). 채널 테두리/배경은 online 만 특별(acc), 값 색은 online→acc, 상태 색은 online→good·offline→bad.
const CH_WRAP: Record<Status, string> = {
  online: 'border-line-acc-hover bg-acc-soft',
  idle: 'border-line bg-ch-tint',
  offline: 'border-line bg-ch-tint',
  probing: 'border-line bg-ch-tint',
};
const DOT: Record<Status, string> = {
  online: 'bg-good shadow-dot-good pulse-online animate-[live-pulse_var(--tempo)_infinite] motion-reduce:animate-none',
  idle: 'bg-dot-idle',
  offline: 'bg-bad shadow-dot-bad',
  probing: 'bg-mut',
};
const VAL_COLOR: Record<Status, string> = {
  online: 'text-acc',
  idle: 'text-txt',
  offline: 'text-txt',
  probing: 'text-txt',
};
const STAT_COLOR: Record<Status, string> = {
  online: 'text-good',
  idle: 'text-mut',
  offline: 'text-bad',
  probing: 'text-mut',
};

function Channel({
  label,
  status,
  value,
  sub,
  vertical,
  action,
}: {
  label: string;
  status: Status;
  value: ReactNode;
  sub: string;
  vertical?: boolean;
  /** 실패했을 때 사용자가 **할 수 있는 일**(M-9). 없으면 안 그린다 — 관측만 있는 칸이 기본이다. */
  action?: { label: string; onClick: () => void };
}) {
  return (
    <div
      className={`flex flex-col gap-1.25 rounded-md border px-3.5 py-3 ${CH_WRAP[status]} ${vertical ? 'flex-1 justify-center' : ''}`}
    >
      <span className="flex items-center gap-1.75">
        <span className={`size-2.25 flex-none rounded-full ${DOT[status]}`} />
        <span className="text-xs font-extrabold tracking-caps-sm text-txt">{label}</span>
        <span className={`ml-auto text-2xs font-extrabold tracking-caps-sm ${STAT_COLOR[status]}`}>
          {STATUS_LABEL[status]}
        </span>
      </span>
      <span className={`text-3xl leading-none font-extrabold tracking-tight tabular-nums ${VAL_COLOR[status]}`}>
        {value}
      </span>
      <span className="truncate text-2xs text-mut">{sub}</span>
      {/* ⚠ **관측에는 짝이 있어야 한다**(M-9) — 사유만 적고 처방이 "앱 재시작"이면 그건 관측이
          아니라 통보다. 두 채널 다 원인이 일시적인 경우가 흔해 *다시 걸기*가 맞는 행동이다. */}
      {action && (
        <Button sm className="mt-1 self-start" onClick={action.onClick}>
          {action.label}
        </Button>
      )}
    </div>
  );
}

/** 채널 리드아웃 파생 — **표현만 있고 상태는 없다**(이 파일 머리주석의 "순수 표현에 가깝게").
 *  컴포넌트 본문에 두면 훅과 삼항 열댓 개가 한 함수에 섞여, 무엇이 구독이고 무엇이 계산인지가
 *  읽는 순서로만 구분된다. 값 계산을 통째로 여기 모으면 컴포넌트에는 *구독 + JSX* 만 남는다.
 *  ⚠ 반환값의 **이름과 값이 종전과 한 글자도 다르지 않다** — 렌더 트리가 안 변한다는 뜻이다.
 *
 *  · 전역 캡처 단축키(E20)는 셸에서만 존재하는 채널이다. 브라우저·dev 에선 필드가 아예 안 오므로
 *    칸을 세우지 않는다(없는 기능을 'IDLE' 로 그리면 "고장난 것"으로 읽힌다).
 *    ⚠ 실패 판정은 **사유의 존재**다(`hotkey === false` 가 아니다 — Rust 쪽과 같은 계약).
 *  · 볼트 **감시** 실패(H7 · 2026-08-01)도 값이 있을 때만 실패다(hotkey 와 같은 계약). 감시가
 *    죽으면 볼트를 고쳐도 화면이 안 바뀌는데 종전엔 그 사실이 Rust 로그에만 있었다.
 *  · `quietLine` 의 분모는 14 가 아니라 **관측된 날**이다 — 앱을 안 연 날은 조용했는지 알 수 없고,
 *    그걸 조용한 날로 세면 "안 썼다"가 "평온했다"로 둔갑한다. 관측이 0이면 아예 말하지 않는다.
 *  · `waveLine`(W16)은 **부팅 웨이브를 읽는 유일한 자리**다. 계량만 하고 소비처가 없으면 그게 곧
 *    `visits.ts` 가 물린 _"쌓이고 있다는 믿음만 쌓인다"_ 라, 마크를 넣은 커밋이 읽는 곳도 함께 낸다.
 *    ⚠ 값이 없으면 **줄 자체가 없다**(0 으로 그리지 않는다 — 값 부재와 값 0 은 다른 사실이다). */
function readouts(
  ping: ReturnType<typeof usePing>,
  vault: VaultScan | undefined,
  live: AnkiLive | undefined,
  file: AnkiFile | undefined,
  quiet: { observed: number; quiet: number } | null,
) {
  const hotkeyErr = ping.data?.hotkeyError ?? null;
  const wave = bootWave();
  return {
    serve: (ping.isLoading ? 'probing' : ping.isSuccess && ping.data?.ok ? 'online' : 'offline') as Status,
    hotkeyErr,
    hotkeyShown: ping.data?.hotkey !== undefined || !!hotkeyErr,
    vaultWatchErr: ping.data?.vaultWatchError ?? null,
    vaultNotes: vault ? vault.subjects.reduce((t, x) => t + x.notes, 0) : 0,
    due: live ? totalDue(live.decks) : 0,
    cards: file ? totalCards(file.decks) : 0,
    quietLine: quiet && quiet.observed > 0 ? `최근 ${quiet.observed}일 관측 중 조용한 날 ${quiet.quiet}일` : null,
    waveLine:
      wave.total != null
        ? `부팅 ${wave.total}ms(엔트리→App ${wave.entryToApp ?? '?'} · App→첫 화면 ${wave.appToData ?? '?'})`
        : null,
  };
}

export default function TelemetryConsole({ vertical }: { vertical?: boolean }) {
  const ping = usePing();
  /* ── E23 소비처 — **쓰기만 하는 계측은 계측이 아니다** ──────────────────
     `visits.ts` 가 도입 나흘 뒤 감사에서 "읽는 곳이 0"으로 잡혔다(H23). 그동안 로드맵 다섯
     항목이 그 데이터를 기다렸고, 사람이 값을 볼 수 없으니 "쌓이고 있다"는 믿음만 쌓였다.
     그래서 원장을 만든 커밋이 소비처도 함께 낸다 — 이 한 줄이 '정적(quiet)의 설계'의 착수
     게이트다(조용한 날이 드물면 금도금, 잦으면 매일 0의 벽을 치우는 것). */
  const [quiet, setQuiet] = useState<{ observed: number; quiet: number } | null>(null);
  useEffect(() => {
    void quietSummary().then(setQuiet);
  }, []);
  // skipToken → fetch 없이(쿼리 비활성) 같은 캐시 키만 구독(패널이 setQueryData하면 콘솔도 갱신).
  //  enabled:false와 달리 queryFn 누락 경고를 내지 않음(읽기전용 캐시 구독의 정석).
  const vault = useQuery<VaultScan>({ queryKey: ['vault'], queryFn: skipToken }).data;
  const live = useQuery<AnkiLive>({ queryKey: ['ankiLive'], queryFn: skipToken }).data;
  const file = useQuery<AnkiFile>({ queryKey: ['ankiFile'], queryFn: skipToken }).data;

  const { serve, hotkeyErr, hotkeyShown, vaultWatchErr, vaultNotes, due, cards, quietLine, waveLine } = readouts(
    ping,
    vault,
    live,
    file,
    quiet,
  );

  return (
    <div className={`ds-board${vertical ? ' mb-0! flex h-full flex-col' : ''}`}>
      <div className="mb-3.5 flex items-baseline justify-between">
        <span className="ds-caps">연동 텔레메트리 — TELEMETRY</span>
        {!vertical && <span className="text-2xs text-mut">시스템 폴더 /api · 볼트 · Anki 조종석</span>}
      </div>
      {quietLine && <p className="mt-0 mb-3 text-2xs text-mut">{quietLine}</p>}
      {waveLine && <p className="mt-0 mb-3 text-2xs text-mut tabular-nums">{waveLine}</p>}
      <div
        className={vertical ? 'flex min-h-0 flex-1 flex-col gap-3' : 'grid grid-cols-3 gap-2.5 max-mobile:grid-cols-1'}
      >
        <Channel
          label="SERVE.JS"
          status={serve}
          vertical={vertical}
          value={serve === 'online' ? <>{ping.data?.tools.length ?? 0}</> : '—'}
          sub={
            serve === 'online'
              ? `도구 · ${ping.data?.work || '/api'}`
              : serve === 'probing'
                ? '연결 확인 중'
                : '워크스페이스 설정 필요(설정 탭)'
          }
        />
        <Channel
          label="VAULT"
          status={vault ? 'online' : 'idle'}
          vertical={vertical}
          value={vault ? vault.subjects.length : '—'}
          sub={vault ? `과목 · 노트 ${vaultNotes} · ${vault.at}` : '볼트 폴더 스캔 대기'}
        />
        <Channel
          label="ANKI"
          status={live ? 'online' : 'idle'}
          vertical={vertical}
          value={live ? due : file ? cards : '—'}
          sub={
            live
              ? `오늘 due · 덱 ${live.decks.length}`
              : file
                ? `카드(파일) · 덱 ${file.decks.length}`
                : 'AnkiConnect 대기'
          }
        />
        {/* ⚠ 전역 캡처 단축키(E20) — **등록 실패가 조용히 죽지 않게 하는 표면**이다. 전역 조합은
            OS 전체에서 한 앱만 가질 수 있어 다른 앱이 선점하면 등록이 실패하는데, 그걸 삼키면
            사용자는 키가 안 먹는 이유를 알 방법이 0 이다(2026-07-25 감사가 잡은 '죽은 분기'와
            같은 형태). 채널로 세워 두면 새 표면 없이 상시 관측이 붙는다.
            ⚠ **사유가 있을 때만 실패**로 그린다 — `hotkey === false` 만 보고 경고하면 브라우저·dev
            에서 상시 경고가 되고, 상시 경고는 곧 무시된다(Rust `hotkey.rs` 와 같은 계약). */}
        {hotkeyShown && (
          <Channel
            label="HOTKEY"
            status={hotkeyErr ? 'offline' : ping.data?.hotkey ? 'online' : 'idle'}
            vertical={vertical}
            value={ping.data?.hotkey ? '⌘⇧␣' : '—'}
            sub={hotkeyErr ? `등록 실패 — 다른 앱이 선점했을 수 있어요: ${hotkeyErr}` : '전역 캡처 · 앱 밖에서도 열림'}
            action={
              hotkeyErr
                ? {
                    label: '다시 등록',
                    onClick: () => {
                      void shellHotkeyRetry().then(
                        () => {
                          toast('전역 단축키를 다시 등록했어요.', 'ok');
                          void ping.refetch();
                        },
                        (e: unknown) =>
                          toast(`아직 선점돼 있어요 — ${e instanceof Error ? e.message : String(e)}`, 'bad'),
                      );
                    },
                  }
                : undefined
            }
          />
        )}
        {/* ⚠ 볼트 감시(H7) — 위 HOTKEY 와 **같은 형태**다: 사유가 있을 때만 칸을 세우고 실패로 그린다.
            감시가 죽었을 때의 증상("볼트를 고쳐도 화면이 안 바뀐다")은 "볼트가 비었다"와 화면상
            구분되지 않아서, 관측 채널이 없으면 사용자가 원인에 도달할 방법이 0 이다. */}
        {vaultWatchErr && (
          <Channel
            label="VAULT-WATCH"
            status="offline"
            vertical={vertical}
            value="—"
            sub={`자동 갱신이 멈췄어요: ${vaultWatchErr}`}
            action={{
              label: '감시 다시 걸기',
              onClick: () => {
                /* ⚠ 성공을 단언하지 않는다 — 감시는 스레드에서 서고 사유가 나중에 앉는다.
                   다음 `ping` 에서 이 칸이 사라지는 것이 성공의 증거다(`lib/tauri` 주석). */
                void shellVaultWatchRetry().then(
                  () => {
                    toast('볼트 감시를 다시 걸었어요 — 잠시 후 상태가 갱신됩니다.', 'info');
                    void ping.refetch();
                  },
                  (e: unknown) =>
                    toast(`감시를 다시 걸지 못했어요 — ${e instanceof Error ? e.message : String(e)}`, 'bad'),
                );
              },
            }}
          />
        )}
      </div>
    </div>
  );
}

/* ============================================================
   mastery/NextActions.tsx — "그래서 다음에 뭘 하나" 열: 프런티어 · 시퀀싱 · 약점/갭 ·
   근본원인 · 엔진 건강 · 캘리브레이션. 전부 ConceptList 한 골격을 공유한다.
============================================================ */
import { useState, type ReactNode } from 'react';
import { useCurriculum } from '@/store/queries';
import {
  topSequencing,
  seqReasonCounts,
  SEQ_REASON_META,
  depthMeta,
  roleMeta,
  engineHealthTiers,
  isHealthCold,
  isRelevanceMonotone,
  type SeqReason,
} from '@/lib/curriculum';
import { rootCauseRollup, type Knowledge } from '@/lib/knowledge';
import { masteryColor, pctLabel } from '@/lib/utils';
import { VaultLink } from './KnowledgeMap';
import { M } from './classes';
import { Icon } from '@/components/Icon';

interface ConceptRow {
  title?: string;
  basename?: string;
  subject?: string;
}
/** 프런티어/약점 등 '개념 리스트' 공통 카드 — 점·이름·과목은 동일, 우측 메타만 renderMeta로 주입. */
function ConceptList<T extends ConceptRow>({
  heading,
  subtitle,
  empty,
  items,
  dot,
  dotColor,
  renderMeta,
  cap = 18,
}: {
  /** ⚠ `ReactNode` 다 — 제목 앞 아이콘이 요소이기 때문(옛 이모지 문자열 자리 · 2026-08-01). */
  heading: ReactNode;
  subtitle: string;
  empty: ReactNode;
  items: T[];
  dot: string;
  dotColor: string;
  renderMeta: (it: T) => ReactNode;
  cap?: number;
}) {
  const [expanded, setExpanded] = useState(false);
  const shown = expanded ? items : items.slice(0, cap);
  const hidden = items.length - shown.length;
  if (!items.length)
    return (
      <div className="ds-rule">
        <h3>{heading}</h3>
        {empty}
      </div>
    );
  return (
    <div className="ds-rule">
      <h3>
        {heading} <span className="ds-tiny text-mut">{subtitle}</span>
      </h3>
      <div className={M.mslist}>
        {shown.map((it, i) => (
          <div key={it.basename ?? i} className={M.msrow}>
            <span className={M.msdot} style={{ background: dotColor }}>
              {dot}
            </span>
            <span className={M.nm}>{it.title || it.basename}</span>
            <span className="ds-tiny text-mut">{it.subject || ''}</span>
            {renderMeta(it)}
            {/* AN-12 — 개념명으로 볼트 딥링크(행 자체는 비대화형이라 명시 아이콘 버튼). */}
            <VaultLink query={it.title || it.basename || ''} />
          </div>
        ))}
      </div>
      {/* 조용한 절단 금지 — 숨은 개념 수를 밝히고 펼칠 수 있게. */}
      {(hidden > 0 || expanded) && (
        <button type="button" className={M.msMore} onClick={() => setExpanded((v) => !v)}>
          {expanded ? '접기' : `+${hidden}개 더 보기`}
        </button>
      )}
    </div>
  );
}

export function Frontier({ k }: { k: Knowledge }) {
  return (
    <ConceptList
      heading={
        <>
          <Icon name="target" /> 다음 배울 개념
        </>
      }
      subtitle="(ZPD · 선수 충족·고레버리지순 — 이걸 배우면 가장 많은 게 풀린다)"
      empty={<div className="ds-tiny text-mut">프런티어 없음(선수 미충족 또는 충분 숙달).</div>}
      items={k.frontier || []}
      dot="⬡"
      dotColor="var(--acc2)"
      renderMeta={(f) => (
        <span
          className="ds-chip"
          data-tip="이 개념을 선수로 삼는 개념 수"
          role="img"
          aria-label={`의존 ${f.prereq_in} — 이 개념을 선수로 삼는 개념 수`}
        >
          의존 {f.prereq_in}
        </span>
      )}
    />
  );
}

/** reason 버킷 점 색(디자인시스템 변수 · 프런티어 셀/약점 점과 같은 언어). */
const SEQ_DOT: Record<SeqReason, string> = {
  remediate: 'var(--bad)',
  zpd: 'var(--acc2)',
  frontier: 'var(--line)',
};

/** 🧭 다음 학습 순서 — 커리큘럼(단계③ 적응형 시퀀싱) arc 랭크. 개념-레벨 프런티어(Frontier)의 arc-레벨 짝:
   선수 게이트 위에서 약점(보강)·ZPD·커버리지를 결합해 커리큘럼.py 가 이미 정렬한 순서를 그대로 보여준다.
   서버 없음/산출물 미생성이면 데이터가 없어 조용히 생략(패널 자체를 접음 · Frontier·Gaps와 동형). */
export function Sequencing() {
  const { data: cur } = useCurriculum();
  const seq = topSequencing(cur, 8);
  if (!cur || !seq.length) return null;
  const counts = seqReasonCounts(cur.sequencing);
  const total = cur.overall?.sequencing ?? cur.sequencing?.length ?? seq.length;
  const o = cur.overall || {};
  // 단계④ 연관성 배분이 켜졌나(노트 goals: 링크 존재). 콜드면 역할=파생기본·relevance 0 이라 배분항 무영향.
  const relActive = !!o.relevance_active;
  return (
    <div className="ds-rule">
      <h3>
        <Icon name="compass" /> 다음 학습 순서{' '}
        <span className="ds-tiny text-mut">
          (커리큘럼 arc 단위 — 개념 단위는 위 '다음 배울 개념' · 선수게이트+약점+ZPD+삶연관성 결합 랭크)
        </span>
      </h3>
      <div className="ds-row" style={{ gap: 6, flexWrap: 'wrap', marginBottom: 8 }}>
        {/* data-tip은 눈으로 보는 사용자용 — 스크린리더는 같은 정보를 aria-label로 받는다
            (TooltipHost가 네이티브 title을 대체하므로 설명이 aria로도 안 실리면 통째로 유실된다).
            여기 담긴 게 "왜 이 순서인가"라는 랭킹 근거라 더더욱 빠뜨릴 수 없다. */}
        <span
          className="ds-chip"
          data-tip={SEQ_REASON_META.remediate.hint}
          role="img"
          aria-label={`보강 ${counts.remediate} — ${SEQ_REASON_META.remediate.hint}`}
        >
          보강 {counts.remediate}
        </span>
        <span
          className="ds-chip"
          data-tip={SEQ_REASON_META.zpd.hint}
          role="img"
          aria-label={`ZPD ${counts.zpd} — ${SEQ_REASON_META.zpd.hint}`}
        >
          ZPD {counts.zpd}
        </span>
        <span
          className="ds-chip"
          data-tip={SEQ_REASON_META.frontier.hint}
          role="img"
          aria-label={`프론티어 ${counts.frontier} — ${SEQ_REASON_META.frontier.hint}`}
        >
          프론티어 {counts.frontier}
        </span>
        {/* 단계④ 유한 예산(#2) 배분 요약 — 주당 시간 상한 안에서 몇 arc 배분/미룸. */}
        {typeof o.allocated_arcs === 'number' ? (
          <span
            className="ds-chip"
            data-tip={`주당 ${o.time_budget_hours ?? '?'}h 예산 내 배분 ${o.allocated_arcs}개 · 초과 미룸 ${o.deferred_arcs ?? 0}개 (약 ${o.allocated_hours ?? '?'}h)`}
            role="img"
            aria-label={`주당 ${o.time_budget_hours ?? '?'}h 예산 내 배분 ${o.allocated_arcs}개 · 초과 미룸 ${o.deferred_arcs ?? 0}개 (약 ${o.allocated_hours ?? '?'}h)`}
          >
            배분 {o.allocated_arcs}
            {o.deferred_arcs ? ` · 미룸 ${o.deferred_arcs}` : ''}
          </span>
        ) : null}
      </div>
      {counts.remediate === 0 && (
        /* 콜드스타트 정직성 — '보강 0'을 '약점 없음'으로 오해하지 않게(KnowledgeMap의 미관측 배너와 대칭). */
        <div className="ds-foot ds-tiny text-mut" style={{ marginBottom: 8 }}>
          보강 0 — 약점이 없다기보다 인출 관측(Anki·CBMS)이 아직 없어서일 수 있어요. 관측이 쌓이면 약점 arc가 보강으로
          올라옵니다.
        </div>
      )}
      {!relActive && (
        /* 연관성 콜드 정직성 — 역할/깊이는 파생 기본값(중심·숙련)이고 삶연관성 가중은 아직 0. */
        <div className="ds-foot ds-tiny text-mut" style={{ marginBottom: 8 }}>
          역할·깊이 배지는 지금 <b>파생 기본값</b>(핵심=중심·숙련)이에요. 핵심 노트에 <code>goals:</code> 링크를 달면
          삶-연관성이 켜지고(relevance) 순서가 목표 그래디언트로 갈립니다.
        </div>
      )}
      <div className={M.mslist}>
        {seq.map((it) => {
          const meta = SEQ_REASON_META[it.reason];
          const role = roleMeta(it.역할);
          const depth = depthMeta(it.target_depth);
          const deferred = it.allocated === false;
          const rel = relActive && typeof it.relevance === 'number' && it.relevance > 0 ? it.relevance : null;
          return (
            <div key={it.arc_id} className={`${M.msrow}${deferred ? ' ' + M.deferred : ''}`}>
              <span
                className={M.msdot}
                style={{ background: SEQ_DOT[it.reason] }}
                title={meta.hint}
                role="img"
                aria-label={meta.label}
              >
                {meta.icon}
              </span>
              <span className={M.nm}>{it.arc || it.arc_id}</span>
              <span className="ds-tiny text-mut">{it.slug || ''}</span>
              {/* 역할 배지(삶-연관 축 · 액센트 틴트) — 콜드면 파생기본 중심. */}
              {role ? (
                <span
                  className={`${M.seqbadge} ${M.role}`}
                  data-tip={role.hint}
                  role="img"
                  aria-label={`${role.label} — ${role.hint}`}
                >
                  {role.label}
                </span>
              ) : null}
              {/* 깊이 배지(복습 강도 축 · 중립) — target_depth 롤업. */}
              {depth ? (
                <span
                  className={M.seqbadge}
                  data-tip={depth.hint}
                  role="img"
                  aria-label={`${depth.label} — ${depth.hint}`}
                >
                  {depth.label}
                </span>
              ) : null}
              {/* 삶-연관성 — 활성 & >0 일 때만(콜드=0 은 숨겨 노이즈 방지). goal 은 tip 에. */}
              {rel != null ? (
                <span
                  className="ds-chip"
                  data-tip={`삶-연관성 ${pctLabel(rel)}${it.goal ? ` · 목표 ${it.goal}` : ''} — 배분 우선순위 근거(연관성×gap)`}
                  role="img"
                  aria-label={`삶-연관성 ${pctLabel(rel)}${it.goal ? ` · 목표 ${it.goal}` : ''} — 배분 우선순위 근거(연관성×gap)`}
                >
                  연관 {pctLabel(rel)}
                </span>
              ) : null}
              {typeof it.mastery === 'number' ? (
                <span
                  className="ds-chip"
                  data-tip="arc 노트 평균 유효숙달"
                  role="img"
                  aria-label={`arc 노트 평균 유효숙달 ${pctLabel(it.mastery)}`}
                >
                  {pctLabel(it.mastery)}
                </span>
              ) : null}
              {it.unlocks ? (
                <span
                  className="ds-chip"
                  data-tip="이 arc를 선수로 삼는 arc 수 — 먼저 익히면 이만큼 풀린다"
                  role="img"
                  aria-label={`푼다 ${it.unlocks} — 이 arc를 선수로 삼는 arc 수. 먼저 익히면 이만큼 풀린다`}
                >
                  푼다 {it.unlocks}
                </span>
              ) : null}
              {/* 미룸(예산·quota) — 이번 주기 배분 아님을 명시(트레이드오프). */}
              {deferred ? (
                <span
                  className="ds-chip"
                  data-tip={
                    it.defer_reason === 'quota'
                      ? '소양·지평 quota 초과 — 과점 방지로 이번 주기 미룸'
                      : '주당 시간 예산 초과 — "이걸 파려면 상위 arc를 미룸" 트레이드오프'
                  }
                  role="img"
                  aria-label={
                    it.defer_reason === 'quota'
                      ? '미룸 — 소양·지평 quota 초과. 과점 방지로 이번 주기 미룸'
                      : '미룸 — 주당 시간 예산 초과. 이걸 파려면 상위 arc를 미루는 트레이드오프'
                  }
                >
                  미룸{it.defer_reason ? `·${it.defer_reason === 'quota' ? 'quota' : '예산'}` : ''}
                </span>
              ) : null}
              <VaultLink query={it.arc || it.arc_id} />
            </div>
          );
        })}
      </div>
      {total > seq.length ? (
        <div className="ds-foot ds-tiny text-mut">
          +{total - seq.length}개 더 (커리큘럼 시퀀싱 전체 {total})
        </div>
      ) : null}
    </div>
  );
}

/** 📈 엔진 건강 — 연관성 3분위(상/중/하)별 평균 숙달 회고(D11 · 준-필수 R4). Sequencing(전방 배분)의
   후방 짝: "연관성↑ 노트가 실제 더 숙달됐나"를 되돌아본다. 라이브 인출 신호 0(P8 콜드)이면 평균숙달 null →
   판정 유예를 정직하게 배너로(Wave F 패턴 · Sequencing 콜드 배너와 대칭). 데이터 없으면 패널 접음. */
export function EngineHealth() {
  const { data: cur } = useCurriculum();
  const health = cur?.engine_health;
  const tiers = engineHealthTiers(health);
  if (!cur || !tiers) return null;
  const cold = isHealthCold(health);
  const monotone = isRelevanceMonotone(health);
  return (
    <div className="ds-rule">
      <h3>
        <Icon name="trend" /> 엔진 건강{' '}
        <span className="ds-tiny text-mut">(연관성↑ 노트가 실제 더 숙달됐나 — 배분 논지 회고 · D11)</span>
      </h3>
      {cold ? (
        /* 콜드 정직성 — 라이브 인출 신호 0(P8 콜드)이라 평균숙달이 없음. 스캐폴드만 켜고 판정은 신호 축적 후. */
        <div className="ds-foot ds-tiny text-mut" style={{ marginBottom: 8 }}>
          라이브 인출 신호가 아직 없어요(P8 콜드) — 연관성↑ 노트가 더 숙달됐는지는 <b>판정 유예</b>. 인출 관측이 쌓이는
          순간 아래 분위별 평균 숙달로 배분 논지가 검증됩니다.
        </div>
      ) : monotone != null ? (
