/** AN-2 — 약점 '근본원인 롤업' 카드. 개별 행의 '← 선수약점: X'는 약점마다 뿔뿔이 흩어져 있어
   어떤 선수개념이 *몇 개* 약점의 공통 뿌리인지 안 보인다 → 여기서 root_cause를 집계·랭크한다.
   프런티어의 prereq_in('이걸 배우면 N개가 풀린다')의 약점판 미러: 가장 많은 약점의 뿌리를 먼저 메우면
   상류가 함께 풀린다. 이미 페치된 k.gaps만 소비(신규 IO 0) · 롤업이 비면 카드 자체를 접는다. */
export function RootCauses({ k }: { k: Knowledge }) {
  const roll = rootCauseRollup(k); // 상위 5개(self·무근원 제외, count 내림차순).
  if (!roll.length) return null;
  return (
    <div className="ds-rule">
      <h3>
        <Icon name="sprout" /> 약점의 뿌리{' '}
        <span className="ds-tiny text-mut">
          (한 선수개념이 여러 약점의 공통 근본원인 — 먼저 메우면 상류가 같이 풀린다)
        </span>
      </h3>
      <div className={M.mslist}>
        {roll.map(({ cause, count }) => (
          <div key={cause} className={M.msrow}>
            <span className={M.msdot} style={{ background: 'var(--bad)' }}>
              <Icon name="sprout" />
            </span>
            <span className={M.nm}>{cause}</span>
            <span
              className="ds-chip"
              data-tip="이 뿌리를 메우면 함께 풀릴 약점 수"
              role="img"
              aria-label={`${count}개 약점의 뿌리`}
            >
              {count}개 약점의 뿌리
            </span>
            {/* AN-12 정합 — 원인 개념도 볼트에서 바로 열 수 있게. */}
            <VaultLink query={cause} />
          </div>
        ))}
      </div>
    </div>
  );
}

export function Calibration({ k }: { k: Knowledge }) {
  const c = k.calibration || {};
  if (!c.n_errors && !c.blank_total)
    return (
      <div className="ds-rule">
        <h3>
          <Icon name="sliders" /> 메타인지 캘리브레이션
        </h3>
        <div className="ds-foot text-mut">
          CBMS 오답·백지 기록이 없습니다 — 러닝허브에서 기록 후 <b>볼트 백업</b>→<code>지식엔진.py build --export</code>
          로 인제스트하면 '확신했는데 틀린' 과신율이 잡힙니다(투입 아닌 출력 지표 · 설계 E).
        </div>
      </div>
    );
  const over = c.overconfidence_rate || 0;
  const overCol = over > 0.5 ? 'var(--bad)' : over > 0.3 ? 'var(--learning)' : 'var(--good)';
  return (
    <div className="ds-rule">
      <h3>
        <Icon name="sliders" /> 메타인지 캘리브레이션{' '}
        <span className="ds-tiny text-mut">(확신도 vs 정확도 — 낮을수록 자기 앎을 정확히 안다)</span>
      </h3>
      <div className="ds-row" style={{ gap: 24, flexWrap: 'wrap' }}>
        <div>
          <div className="ds-kpi" style={{ color: overCol }}>
            {pctLabel(over)}
          </div>
          <div className="ds-foot">
            과신율 — 확신했는데 틀림 {c.confident_wrong || 0} / 전체 오답 {c.n_errors || 0}
          </div>
        </div>
        {c.blank_total ? (
          <div>
            <div className="ds-kpi">{pctLabel(c.blank_pass_rate)}</div>
            <div className="ds-foot">
              백지복습 통과율 {c.blank_pass || 0}/{c.blank_total || 0}
            </div>
          </div>
        ) : null}
      </div>
      {/* 실제 오답 개수로 분할 — 추상 비율(1-over) 대신 과신/적정 개수를 직접 보여줘 데이터가 있는 척하지 않게. */}
      {(() => {
        const nErr = c.n_errors || 0;
        const cw = c.confident_wrong || 0;
        const appropriate = Math.max(0, nErr - cw);
        return (
          <div className={M.msbar} style={{ marginTop: 10 }}>
            <div
              className={M.msbarSeg}
              data-tip={`확신했는데 틀림(과신) ${cw}/${nErr}`}
              role="img"
              aria-label={`확신했는데 틀림(과신) ${cw}/${nErr}`}
              style={{ width: `${nErr ? Math.round((cw / nErr) * 100) : 0}%`, background: 'var(--bad)' }}
            />
            <div
              className={M.msbarSeg}
              data-tip={`확신없이 틀림(적정) ${appropriate}/${nErr}`}
              role="img"
              aria-label={`확신없이 틀림(적정) ${appropriate}/${nErr}`}
              style={{
                width: `${nErr ? Math.round((appropriate / nErr) * 100) : 0}%`,
                background: 'var(--learning)',
              }}
            />
          </div>
        );
      })()}
      <div className="ds-foot ds-tiny text-mut" style={{ marginTop: 6 }}>
        과신 오답 = 다음 복습에서 우선 표적. 백지 통과율 = '꺼낼 수 있는가'의 직접 증거.
      </div>
    </div>
  );
}

/* ============================================================
   ReviewRun — 탭: ↻ 복습 실행 (I-9 · doing surface)
   식별(review/stats/mastery)은 풍부하나 '실제로 복습을 굴리는 화면'이 빔 — 그 빈칸을 메운다.
   오늘 인출할 것을 한 카드씩 흐름으로: ① 회상(내 요약 다시 설명) ② 착각 재확인(과신 오답 재인출)
   ③ 밀린 챕터(간격반복 due/overdue). 진행은 이 세션의 로컬 상태(가짜 위험 감소 주장 없음) —
   실제 학습은 '집중 시작'(전역 타이머)·볼트 딥링크로 다리 놓고, 완료 세션이 정직하게 루프를 먹인다.

   ## 조작은 키보드가 정본이다(D-3)
   `Space` 펼치기 · `1` 건너뛰기 · `2` 판정/집중 시작 · `3` 떠올렸어요(챕터 · 볼트를 연 뒤) ·
   `V` 볼트 · `U` 되돌리기 · `Esc` 중단.
   카드 안에는 버튼이 없다 — 전부 화면 발치의 키캡 한 줄(`KeyBar`)로 모였고, 그 키캡이 곧
   누를 수 있는 버튼이다. 목록(`keys`)이 리스너와 화면의 **단일 원천**이라 둘이 갈릴 수 없다.

   ## 인출이 앵커를 옮긴다(E1 · 2026-07-29)
   이 화면은 챕터 카드에 _"지금 인출해 망각곡선을 리셋하세요"_ · _"한 번 인출하면 그때부터 유지
   주기가 잡힙니다"_ 라고 **약속해 놓고 그 경로를 주지 않았다.** `touchReview` 의 쓰기 호출부가
   `app/FocusChip.tsx` 하나였기 때문 — 즉 앵커를 얻으려면 25분 집중 세션을 완주하고 토스트가
   살아 있는 동안 '블록 완료로 표시'까지 눌러야 했다. 그래서 유지 큐(끝낸 챕터)는 앵커를 못 얻어
   영구히 `due` 였고, `reviewQueue.ts` 의 `MAINTENANCE_CAP` 주석이 그 기능의 존립 근거로 든
   _"볼 때마다 진짜 앵커가 하나씩 생겨 큐가 스스로 수렴한다"_ 가 한 번도 참이 아니었다.

   ⚠ **`2`(집중 시작)에서 앵커를 옮기지 않는 것이 이 설계의 핵심이다.** 그건 인출 사건이 아니라
     세션 *시작*이라, 거기에 매달면 25분 공부 없이 `2` 를 14번 눌러 14개 챕터의 망각곡선을
     리셋하게 된다 — 사용자가 승인한 "인출 사건이 사다리의 단위"라는 근거로도 정당화되지 않는다
     (그 경우 인출 사건 자체가 없다). 그래서 **`3` 을 따로 판다.**
   ⚠ **`3` 에는 대조 게이트가 없다** — 챕터 카드엔 펼칠 본문이 없어서(`revealable` 이 이 종류를
     애초에 제외한다) 요구할 대조가 없고, 볼트 열람을 조건으로 걸면 그건 계약이 아니라 새 마찰이다.
     자기보고의 위험은 알려진 채로 수용된 것이고, 최악이 "덜 급한 챕터를 좀 늦게 본다"라 방향이
     안전한 쪽이다(`spacedReview.ts:47-50` 의 비대칭 논거와 부호가 같다).
   ⚠ **회상 카드는 앵커가 원리적으로 없다** — `Summary` 에 `chapter` 필드 자체가 없다(요약은 과목
     단위다). sid 만으로 아무 챕터나 리셋하는 것은 인출 기록이 아니라 오염이라 하지 않는다.
============================================================ */
