source:
/* ============================================================
   useListCursor — **커서 = DOM 포커스 + j/k + 동사키**(W13 · 2026-07-31).

   ## 왜 훅인가
   `FlowRail`(E5)이 이 상태기계를 이미 검증했는데 **23화면 중 2곳**에만 있었다. 나머지는 Tab
   순회다 — 실측: 배치 트레이 3번째 행의 ⤵ 까지 **Tab 14회**(행당 최대 5스톱), 4번째면 19회.
   마우스는 1클릭이다. 그리고 `useKeymap`(리스너 포함) 실사용은 **1곳**뿐이라, N-16 이 목표한
   "선언 하나에서 리스너와 치트시트가 함께 파생"은 사실상 미도달이었다.

   ## ⚠⚠ 어휘를 **여덟 개로 닫는다** — 이 훅의 본체
   `x` 완료 · `e` 편집 · `d` 삭제 · `p` 배치 · `f` 집중 · `v` 볼트 · `u` 되돌리기 · **`m` 표시**.
   닫지 않으면 화면마다 자기 키를 만들고, 그러면 "이 화면에서 d 가 뭐였지"가 매번 생긴다 —
   E24(모션 어휘 5마디)가 같은 이유로 같은 처방을 썼다. 새 동작은 **어휘를 늘리는 게 아니라
   기존 동사에 매핑**하거나, 축이 정말 다르면 그때 여기 한 줄을 더한다(그리고 전 화면이 안다).

   ⚠ 어휘를 닫으면 화면마다 "여기 없는 동사"가 생기고, 없는 키를 눌렀을 때의 **침묵**이 Tab
   14회보다 나쁘게 느껴질 수 있다 → 탈출구는 ⌘K 팔레트다(그쪽이 객체에 동사를 붙인다).

   ⚠ `Enter`/`Space` 는 **다루지 않는다.** 포커스한 행이 버튼이면 네이티브 활성이 곧 기본 동작이고,
   가로채면 한 키가 두 뜻을 갖는다(E5 이전의 결함이 정확히 그 형태였다).
   ⚠ 입력 중(INPUT·TEXTAREA·contentEditable)과 수정자 조합에서는 전부 무시한다.

   ## ⚠⚠ 소유권 — 한 화면에 목록이 둘이면 누가 키를 갖나 (H12 · 2026-08-01)

   리스너가 `window` 라 **마운트된 모든 목록이 같은 키를 동시에 받았다.** `/journal` 은 목록이
   둘(`BacklogCard`·`JournalStream`)이라 `j` 한 번에 **하이라이트가 두 줄**에 뜨고, 이어서 `d` 를
   누르면 **보이는 포커스와 다른 목록**의 행이 지워졌다 — 파괴적 동사가 오조준된다.
   같은 뿌리에서 더 나쁜 것: 확인창·치트시트가 떠 있어도(포커스는 그 안에 갇혀 있는데) 뒤의
   목록이 `d` 를 받았다.

   규칙은 **포커스가 정한다** — 세 줄로 닫힌다:
     ① 등록된 내 행 중 하나가 `document.activeElement` 를 품고 있으면 **내 것이다.**
     ② 아니고 포커스가 *어딘가에는* 있으면(다이얼로그·다른 목록·버튼) **내 것이 아니다.**
     ③ 포커스가 아무 데도 없고(`body`) **화면에 목록이 나 하나뿐이면** 내 것이다.
        (여기서 "첫 마운트 우선" 같은 임의 규칙을 두지 않는 이유: 둘 중 누구를 골라도 사용자가
         보는 근거가 없다. 모르면 아무도 안 받고, Tab·클릭 한 번이 소유자를 정한다.)
   ③ 이 필요한 이유는 단일 목록 화면의 **들어오는 문**이다 — 포커스 없이 `j` 를 눌러 시작하는
   동작을 잃으면 이 훅의 값 대부분이 사라진다(E5 가 세운 계약).

   ⚠ 포커스가 내 행을 떠나면 **커서를 지운다.** 안 그러면 다른 목록으로 옮겨간 뒤에도 옛
   하이라이트가 남아 "지금 무엇이 선택돼 있나"를 화면이 두 군데로 답한다.
============================================================ */
import { useEffect, useRef, useState } from 'react';
import { reveal } from '@/lib/motion';
import { useKeymapDoc } from './useKeymap';

/** 닫힌 동사 어휘 — **여기가 SSOT**. 키를 늘리려면 이 표를 고치고, 그러면 치트시트가 따라온다. */
export const CURSOR_VERBS = {
  x: '완료',
  e: '편집',
  d: '삭제',
  p: '배치',
  f: '집중',
  v: '볼트',
  u: '되돌리기',
} as const;
export type CursorVerb = keyof typeof CURSOR_VERBS;

/* ── A-12 **여덟째 키 `m`(표시) — 동사가 전체에 걸린다**(W9 · 2026-08-07) ────────────
   이 저장소에 **다중 선택 코드가 0건**이었다. 그래서 챕터 일곱 개를 끝내려면 `j x` 를 일곱 번
   (25 키스트로크) 치고, 그 대가로 **토스트 일곱 장과 ⌘Z 일곱 번**이 남는다 — 한 번의 결정이
   일곱 개의 되돌림으로 쪼개지는 것이 이 결함의 실제 형태다(사용자는 "그 일곱 개"를 한 덩어리로
   기억하는데 앱은 그렇게 저장하지 않는다).

   ⚠ **`m` 은 동사가 아니라 범위다.** 위 일곱은 *무엇을 하나*이고 이건 *무엇에게 하나*다. 그래서
   `CURSOR_VERBS` 에 안 넣는다 — 넣으면 화면마다 "`m` 을 구현했나"를 정해야 하는데, 표시는 어느
   목록에서나 같은 뜻이라 화면의 선택지가 아니다(치트시트에는 `bulk` 를 준 화면에만 뜬다).
   ⚠ **표시가 있으면 동사는 표시 전체에**, 없으면 커서 하나에. 두 모드를 화면이 고르지 않는다.
   ⚠ 실행 뒤 표시는 **지운다** — 남겨 두면 다음 동사가 방금 처리한 것들에 또 걸린다. */
export const MARK_KEY = 'm';

export interface ListCursorOptions<T> {
  /** 커서가 도는 항목들 — `key` 가 곧 DOM id 이자 커서 값이다. */
  items: readonly { key: string; item: T }[];
  /** 이 화면이 실제로 구현한 동사만. 없는 키는 조용히 무시된다(있는 척하지 않는다). */
  verbs: Partial<Record<CursorVerb, (item: T) => void>>;
  /**
   * **A-12** — 표시된 여럿에 한 번에 거는 판. 준 동사만 일괄이 된다.
   *
   * ⚠ 개별 동사를 반복 호출하지 **않는다**: 그러면 토스트 N장·⌘Z N번이라는 이 항목의 결함이
   * 그대로 남는다. 일괄은 **한 번의 `mutate`** 여야 하고, 그건 호출부만 할 수 있다.
   * ⚠ 안 준 동사는 표시가 있어도 **커서 하나**에만 걸린다(있는 척하지 않는다 · 위 규율).
   */
  bulk?: Partial<Record<CursorVerb, (items: T[]) => void>>;
  /** 치트시트 섹션 제목(`?`). 없으면 등재하지 않는다. */
  docTitle?: string;
  /** 훅을 끈다(다른 오버레이가 떠 있을 때 등). */
  enabled?: boolean;
}

export interface ListCursor {
  /** 지금 커서가 선 key(없으면 null). */
  cursor: string | null;
  /** **A-12** — 표시된 key 들. 화면이 행에 표식을 그린다(빈 집합이면 단일 모드). */
  marked: ReadonlySet<string>;
  /** roving tabindex 의 탭 스톱 — 목록 전체가 탭 스톱 **하나**다. */
  tabStop: string | null;
  /** 각 행 요소를 등록하는 ref 콜백 팩토리. */
  register: (key: string) => (el: HTMLElement | null) => void;
  /** 행이 포커스를 받으면 커서를 그리로(포커스가 곧 커서 — 두 벌이 아니다). */
  onItemFocus: (key: string) => void;
}

/** 지금 화면에 살아 있는(그리고 켜져 있는) 커서 목록 — 위 규칙 ③의 "나 하나뿐인가"를 센다. */
const MOUNTED = new Set<object>();

export function useListCursor<T>({ items, verbs, bulk, docTitle, enabled = true }: ListCursorOptions<T>): ListCursor {
  const [cursor, setCursor] = useState<string | null>(null);
  const [marked, setMarked] = useState<ReadonlySet<string>>(() => new Set());
  const refs = useRef(new Map<string, HTMLElement>());
  const id = useRef({});

  /* 등록/해제는 `enabled` 를 따른다 — 꺼진 목록이 정원을 차지하면 켜진 단일 목록이 규칙 ③을
     못 쓰게 된다(= 화면에 목록이 하나뿐인데 키가 안 먹는다). */
  useEffect(() => {
    if (!enabled) return;
    const key = id.current;
    MOUNTED.add(key);
    return () => {
      MOUNTED.delete(key);
    };
  }, [enabled]);

  /* 치트시트 — 이 화면이 **실제로 구현한** 동사만 등재한다. 어휘가 닫혀 있어도 화면마다
     구현 여부가 다르므로, 표를 그대로 베끼면 `?` 가 거짓말을 한다(N-16 이 `,`/`.` 로 물린 부류). */
  useKeymapDoc(
    docTitle || '',
    [
      { display: 'J / K', label: '다음 / 이전' },
      // A-12 — 일괄을 실제로 받는 화면에서만 `m` 을 광고한다(치트시트가 거짓말하지 않게).
      ...(bulk && Object.keys(bulk).length ? [{ display: 'M', label: '표시 — 동사가 표시 전체에' }] : []),
      ...(Object.keys(verbs) as CursorVerb[])
        .filter((k) => verbs[k])
        .map((k) => ({ display: k.toUpperCase(), label: CURSOR_VERBS[k] })),
    ],
    !!docTitle && enabled,
  );

  // 핸들러가 읽는 최신 값 — 리스너를 재등록하지 않고 최신 상태·콜백을 보게 하는 통로
  // (`items` 는 매 렌더 새 배열이라 deps 에 넣으면 window keydown 이 매 렌더 제거→재등록된다).
  const ctx = useRef({ items, verbs, bulk, cursor, enabled, marked });
  useEffect(() => {
    ctx.current = { items, verbs, bulk, cursor, enabled, marked };
  });

  useEffect(() => {
    const move = (key: string): void => {
      setCursor(key);
      const el = refs.current.get(key);
      reveal(el, 'nearest'); // 모션 자제 판정은 `lib/motion` 이 소유한다(H16)
      el?.focus({ preventScroll: true });
    };
    /** 등록된 행 중 하나가 지금 포커스를 품고 있나(= 규칙 ①). */
    const ownsFocus = (): boolean => {
      const ae = document.activeElement;
      if (!ae) return false;
      for (const el of refs.current.values()) if (el.contains(ae)) return true;
      return false;
    };
    /** 이 목록이 지금 키를 받아야 하나 — 머리주석의 규칙 ①②③. */
    const mine = (): boolean => {
      if (ownsFocus()) return true; // ①
      const ae = document.activeElement;
      if (ae && ae !== document.body) return false; // ② 포커스가 다른 곳(다이얼로그·다른 목록)에 있다
      return MOUNTED.size <= 1; // ③ 포커스가 없고 목록이 나 하나뿐일 때만
    };
    const onKey = (e: KeyboardEvent): void => {
      const { items, verbs, bulk, cursor, enabled, marked } = ctx.current;
      if (!enabled || !items.length) return;
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      if (!mine()) return;
      const keys = items.map((n) => n.key);
      const idx = cursor ? keys.indexOf(cursor) : -1;
      if (e.key === 'j') {
        e.preventDefault();
        move(keys[Math.min(keys.length - 1, idx + 1)] ?? keys[0]!);
        return;
      }
      if (e.key === 'k') {
        e.preventDefault();
        move(idx <= 0 ? keys[0]! : keys[idx - 1]!);
        return;
      }
      const low = e.key.toLowerCase();
      /* A-12 — 표시 토글. 커서가 없으면 표시할 대상도 없다(그때는 조용히 무시 — `j` 가 문이다). */
      if (low === MARK_KEY) {
        if (!bulk || !cursor) return;
        e.preventDefault();
        setMarked((prev) => {
          const next = new Set(prev);
          if (next.has(cursor)) next.delete(cursor);
          else next.add(cursor);
          return next;
        });
        return;
      }
      if (!(low in CURSOR_VERBS)) return;
      const verb = low as CursorVerb;
      /* 표시가 있으면 **표시 전체**에 건다 — 단, 그 동사의 일괄 판을 준 화면에서만.
         (안 준 동사는 커서 하나에 걸린다 · 위 ⚠) */
      const many = marked.size ? items.filter((n) => marked.has(n.key)) : [];
      const runMany = many.length ? bulk?.[verb] : undefined;
      if (runMany) {
        e.preventDefault();
        runMany(many.map((n) => n.item));
        setMarked(new Set()); // 실행하면 표시는 비운다(다음 동사가 또 걸리지 않게)
        return;
      }
      const run = verbs[verb];
      if (!run) return; // 이 화면에 없는 동사 — 조용히 무시(어휘는 닫혀 있고 구현은 화면별이다)
      const hit = items.find((n) => n.key === cursor);
      if (!hit) return;
      e.preventDefault();
      run(hit.item);
    };
    /* 포커스가 내 행을 떠나면 커서를 지운다 — 두 목록이 동시에 하이라이트되던 것의 절반이 이것이다.
       ⚠ `document.body` 로 빠지는 경우(행이 사라져 포커스가 풀림)는 **안 지운다**: 그건 사용자가
       다른 곳으로 간 것이 아니라 DOM 이 바뀐 것이고, 지우면 목록이 갱신될 때마다 커서를 잃는다. */
    const onFocusIn = (): void => {
      const ae = document.activeElement;
      if (!ae || ae === document.body) return;
      if (!ownsFocus()) setCursor(null);
    };
    window.addEventListener('keydown', onKey);
    document.addEventListener('focusin', onFocusIn);
    return () => {
      window.removeEventListener('keydown', onKey);
      document.removeEventListener('focusin', onFocusIn);
    };
    // deps 빈 배열이 정직하다 — 핸들러가 참조하는 값은 전부 ctx.current 에서 읽는다(마운트당 1회 등록).
  }, []);

  return {
    cursor,
    marked,
    /* 커서가 없으면 첫 항목이 탭 스톱을 맡는다 — 들어올 문이 없으면 키 계약이 죽는다(E5). */
    tabStop: cursor ?? items[0]?.key ?? null,
    register: (key: string) => (el: HTMLElement | null) => {
      if (el) refs.current.set(key, el);
      else refs.current.delete(key);
    },
    onItemFocus: setCursor,
  };
}

/* ============================================================
   lib/absence.ts — **부재 델타**(P-1 · 2026-08-01). "며칠 비었고, 그 사이 무엇이 무너졌나."

   ## 무엇이 없었나

   이 앱의 복귀 지원은 `resume` 커서 하나였는데 그건 **TTL 6시간**이라(`resume.ts`) 정의상
   *며칠 만의 복귀에는 존재하지 않는다*. 그리고 폰 홈·데스크톱 today 는 언제나 **"오늘"만**
   말한다. 그래서 4일 만에 열었을 때 "그 사이 뭐가 밀렸나"를 알려면 복습 탭(밀린 수) →
   계획 탭(미완 블록) → 통계 = **3화면·4클릭**이었다.

   ## 왜 새 저장값이 0인가

   부재 길이는 `route_visits`(N-11)의 **마지막 방문일**에서 나오고, 그때의 값은
   `day_signals`(E23)가 **이미 90일치 적고 있다**. 둘 다 이 항목보다 먼저 존재했고 둘 다
   "쓰기만 하고 읽는 곳이 없다"로 감사에 잡힌 이력이 있다(H23) — 이 모듈이 그 소비처다.
   새 테이블 0 · 서버 DDL 0.

   ⚠⚠ **관측이 없으면 델타를 지어내지 않는다.** `day_signals` 에 그날 행이 없으면 `then` 은
   `null` 이고 문장은 화살표 없이 **현재값만** 말한다. 과거값을 지금 state 로 역산하는 길이
   있긴 한데(`riskSummary(state, days, 그날)`) 그러면 **그 뒤에 지워진 챕터·바뀐 마감이 과거를
   소급해 바꾼다** — 관측된 적 없는 숫자를 관측된 것처럼 그리는 형태라 하지 않는다.
   (`daySignals.ts` 머리주석이 같은 이유로 "지나가면 재구성이 불가능하다"고 적어 뒀다.)

   ⚠ 브라우저(dev·트랙 A)에선 두 원장이 통째로 무동작이라(`isSqlitePrimary()` 가 false)
   `lastDs` 가 null 이고, 그러면 브리핑은 **그리지 않는다**. 시각 베이스라인은 안 흔들린다.
============================================================ */
import { selectDb } from './db/sqlite';
import { addDays, dayDiff, iso, parseISO, todayISO } from './utils';

/** 브리핑을 그리는 최소 부재 일수. 어제 열었으면(1) 부재가 아니다 — 그 화면은 '오늘'이 소유한다. */
export const ABSENCE_MIN_DAYS = 2;

/** 두 원장에서 읽어 온 "마지막으로 본 하루". 관측이 없으면 각 필드가 null 이다. */
export interface AbsenceSnapshot {
  /** 오늘 이전에 앱을 연 마지막 날(ds). 없으면 null. */
  lastDs: string | null;
  /** 그날 관측된 밀린+대기 복습 수. 관측 없으면 null.
   *  ⚠ 원장 열 이름은 `overdue` 지만 담기는 값은 **`overdue + due`** 다(`TodaySignature` 가
   *  `riskN` 을 넣는다). 아래 `AbsenceNow.review` 와 같은 양이어야 화살표가 거짓말을 안 하므로
   *  열 이름이 아니라 **채워지는 값**에 맞춘다 — 이름을 믿고 `overdue` 만 비교하면 델타가
   *  조용히 틀린다. */
  thenReview: number | null;
}

/** 브리핑에 필요한 지금 값 — 전부 호출부가 이미 들고 있는 것들이다(신규 IO 0). */
export interface AbsenceNow {
  /** 지금 밀린+대기 복습 수. */
  review: number;
  /** 부재 기간에 배치됐지만 완료되지 않은 학습 블록 수. `missedSince` 산출값. */
  missed: number;
  /** 가장 가까운 마감(있으면). */
  deadline: { name: string; dday: number } | null;
}

/**
 * **밖에서 일어난 일**(T-11). 앱이 꺼져 있던 동안의 볼트 편집·Anki 복습.
 *
 * ⚠ 위 `AbsenceNow` 와 시제가 같고 **부호가 반대**다. 저기 셋(밀린 복습·미완·마감)은 전부
 * *무너진 것*이라, 그것만 그리면 며칠 만에 연 화면이 **한 일을 없던 것처럼** 말한다 — 볼트에
 * 노트를 다섯 개 쓰고 Anki 를 120장 돌고 온 사람에게 "3개 밀렸어요"만 보여주는 형태다.
 * ⚠⚠ **모르는 것은 `null` 이고 0 이 아니다.** 볼트를 못 읽었거나 Anki 가 안 떠 있는 것과
 * "그 기간에 아무것도 안 했다"는 다른 사실인데, 0 으로 접으면 화면에서 구분이 사라진다.
 */
export interface AbsenceOutside {
  /** 부재 기간에 수정된 볼트 노트 수. 모르면 null. */
  notes: number | null;
  /** 그 노트들의 과목(빈도 순 · 최대 [`OUTSIDE_SUBJECTS`]개). 칩이 아니라 **풀어 쓴 문장**에만 쓴다. */
  subjects: string[];
  /** 부재 기간에 복습한 Anki 카드 수. 모르면 null. */
  ankiCards: number | null;
}

/** 문장에 이름을 대는 과목 수 상한. 셋을 넘기면 그건 문장이 아니라 목록이다. */
export const OUTSIDE_SUBJECTS = 3;

export interface ReturnBriefing {
  /** 비어 있던 일수(마지막 방문일 → 오늘). */
  days: number;
  /** 사람이 읽는 한 줄. */
  line: string;
  /** SR·title 용 — 같은 사실의 풀어 쓴 형태. */
  aria: string;
  /**
   * **Q-29 처방** — 숫자 다음에 오는 *하라는 말* 한 마디.
   *
   * ⚠ 종전엔 이 칩이 13px 안에 숫자를 최대 6개 담고 **행동 정보가 0**이었다. 복귀한 사람에게
   * 필요한 것은 "얼마나 밀렸나"가 아니라 "그래서 지금 뭘 하나"다 — 숫자만 주면 그건 정보가
   * 아니라 부재에 대한 지적이 된다(방향 §2 (d)의 정반대).
   * ⚠⚠ 처방의 원칙은 하나다: **재건된 첫 계획은 깨진 계획보다 작아야 한다.** 그래서 어떤
   * 처방도 "전부 따라잡아라"라고 말하지 않는다 — 그 말이 복귀 첫날을 다시 실패로 만든다.
   */
  advice: string;
}

/** 복귀 첫날에 권하는 복습 상한(개). 밀린 전부가 아니라 **한 줌**이다(위 원칙). */
export const RETURN_REVIEW_CAP = 3;

/** 부재 기간 판정에 쓰는 블록 한 개. `ds` 는 배치된 날, `done` 은 완료 여부. */
export interface PlannedBlock {
  ds: string;
  done: boolean;
}

/**
 * 부재 기간(`lastDs` 다음날 ~ 어제)에 배치됐는데 **완료되지 않은** 블록 수.
 *
 * ⚠ 경계가 양쪽 다 열려 있는 것이 의도다. `lastDs` 당일은 사용자가 **봤고**(그날 안 한 것은
 * 부재의 결과가 아니라 그날의 선택이다), 오늘은 아직 안 지나갔다(미완이 아니라 할 일이다).
 * 이 경계를 닫으면 브리핑이 "네가 오늘 아직 안 한 것"까지 부재 탓으로 세어 죄책감만 키운다.
 */
export function missedSince(blocks: readonly PlannedBlock[], lastDs: string, todayDs: string): number {
  let n = 0;
  for (const b of blocks) {
    if (b.done) continue;
    if (b.ds <= lastDs || b.ds >= todayDs) continue;
    n++;
  }
  return n;
}

/**
 * 복귀 브리핑 한 줄. 부재가 {@link ABSENCE_MIN_DAYS} 미만이거나 말할 것이 없으면 **null**
 * (0·평온은 아무것도 안 그린다 — 이 앱의 빈 상태 규율).
 *
 * ⚠ 말할 것이 없다 = 복습도 그대로고 미완도 0이고 마감도 없다. 그때 `4일 비었어요` 만 남기면
 * 그건 정보가 아니라 **부재 자체에 대한 지적**이다(방향 §2 (d)의 정반대). 부재 길이는 델타의
 * *맥락*이지 델타가 아니다.
 */
/* ⚠ **델타 문장 조립을 갈라 둔다**(2026-08-20 리뷰 M-14 원장 축소). 세 축(복습·미완·마감)이
   각자 `parts`/`aria` 두 배열에 밀어 넣는 형태라 분기가 여섯이었고, 그게 `returnBriefing` 의
   인지복잡도 대부분이었다. 이 함수는 **말을 만들 뿐** 무엇을 처방할지는 안 정한다 — 그 판단은
   호출부의 Q-29 순서 규칙이 소유한다(둘을 섞으면 "무엇을 말하나"와 "무엇을 시키나"가 한 덩어리가 된다). */
function delta(snap: AbsenceSnapshot, now: AbsenceNow): { parts: string[]; aria: string[] } {
  const parts: string[] = [];
  const aria: string[] = [];
  /* 복습은 **늘어난 경우에만** 화살표로 말한다 — 줄었거나 같으면 그건 부재의 결과가 아니다
     (관측이 없으면 `then` 이 null 이라 자연히 현재값만 남는다). */
  if (snap.thenReview != null && now.review > snap.thenReview) {
    parts.push(`복습 ${snap.thenReview}→${now.review}`);
    aria.push(`밀린 복습이 ${snap.thenReview}개에서 ${now.review}개로 늘었습니다`);
  } else if (now.review > 0) {
    parts.push(`복습 ${now.review}`);
    aria.push(`밀린 복습 ${now.review}개`);
  }
  if (now.missed > 0) {
    parts.push(`미완 ${now.missed}`);
    aria.push(`그 사이 미완 블록 ${now.missed}개`);
  }
  if (now.deadline) {
    parts.push(`${now.deadline.name} D-${now.deadline.dday}`);
    aria.push(`가장 가까운 마감은 ${now.deadline.name} D-${now.deadline.dday}`);
  }
  return { parts, aria };
}

/** T-11 — **밖에서 한 일**은 위 목록에 섞지 않는다. 같은 ` · ` 목록에 넣으면
 *  "복습 18 · 미완 3 · 노트 5" 가 되어 *한 일*이 *밀린 일*과 같은 픽셀로 읽힌다(부호가 반대인데). */
function outsideDid(outside?: AbsenceOutside | null): string[] {
  const did: string[] = [];
  if (outside?.notes) did.push(`노트 ${outside.notes}`);
  if (outside?.ankiCards) did.push(`카드 ${outside.ankiCards}`);
  return did;
}

export function returnBriefing(
  snap: AbsenceSnapshot,
  now: AbsenceNow,
  todayDs: string,
  /** T-11 — 밖에서 일어난 일. 안 주면 종전 동작 그대로(브라우저·폰이 그 경로다). */
  outside?: AbsenceOutside | null,
): ReturnBriefing | null {
  if (!snap.lastDs) return null;
  const days = dayDiff(snap.lastDs, todayDs);
  if (days < ABSENCE_MIN_DAYS) return null;

  const { parts, aria } = delta(snap, now);
  const did = outsideDid(outside);
  if (did.length) {
    const where = outside?.subjects.length ? `${outside.subjects.join('·')} 쪽으로 ` : '';
    aria.push(`그동안 앱 밖에서 ${where}${did.join(', ')}만큼 했습니다`);
  }

  // ⚠ 밖에서 한 일**만** 있어도 브리핑은 그린다 — 그게 이 항목의 요지다(할 말이 생겼다).
  if (!parts.length && !did.length) return null;

  /* Q-29 처방 — **순서가 규칙이다**(하나만 말한다 · 셋을 늘어놓으면 다시 목록이 된다):
       ① 마감이 있으면 그것이 이긴다 — 날짜는 협상 대상이 아니다.
       ② 아니면 밀린 복습을 **상한만큼만**. "전부"라고 말하지 않는 것이 이 항목의 전부다.
       ③ 아니면 미완 — 밀린 것을 따라잡는 대신 **오늘 것부터** 시작하라고 말한다.
       ④ (T-11) 앱 안이 평온하고 밖에서만 일이 있었으면 **진도 반영**이 유일하게 남는 행동이다.
     ⚠ 어느 가지도 "따라잡아라"를 말하지 않는다.
     ⚠ 밖에서 한 일이 ①~③ 을 이기지 않는 이유: 그건 *이미 한 일*이라 마감보다 급할 수 없다. */
  const advice = now.deadline
    ? `${now.deadline.name}부터 — 마감이 가장 가깝습니다.`
    : now.review > 0
      ? `오늘은 밀린 복습 중 ${Math.min(RETURN_REVIEW_CAP, now.review)}개만 하세요.`
      : now.missed > 0
        ? `밀린 것은 두고 오늘 블록부터 시작하세요.`
        : outside?.notes
          ? `밖에서 쓴 노트 ${outside.notes}개를 진도에 반영하세요.`
          : `밀린 것은 두고 오늘 블록부터 시작하세요.`;

  const tail = did.length ? ` (밖에서 ${did.join(' · ')})` : '';
  return {
    days,
    line: `${days}일 비었어요${parts.length ? ` — ${parts.join(' · ')}` : ''}${tail}`,
    aria: `${days}일 만의 복귀입니다. ${aria.join(', ')}. ${advice}`,
    advice,
  };
}

/**
 * 두 원장에서 스냅샷을 읽는다. **실패하면 빈 스냅샷** — 관측이 화면을 막으면 안 된다
 * (`visits.ts`·`daySignals.ts` 와 같은 계약).
 */
/**
 * T-11 — 부재 기간에 **밖에서** 일어난 일을 모은다. 실패하면 그 축만 `null`(화면은 그대로 뜬다).
 *
 * ⚠ **창의 시작은 `lastDs` 의 *다음날* 자정**이다. `lastDs` 당일에 한 볼트 편집은 사용자가 앱을
 * 열어 놓고 한 것일 수 있어 "밖에서"라고 부를 수 없다.
 * ⚠ **끝은 지금이다 — `missedSince` 와 경계가 다르고, 그게 의도다.** 저기가 오늘을 빼는 것은
 * *미완을 부재 탓으로 세지 않기 위해서*고(오늘은 아직 안 지나갔다), 여기는 반대다: 오늘 아침
 * 앱을 열기 전에 돈 Anki 도 **앱이 모르는 사이에 일어난 일**이라 브리핑의 대상이다.
 *
 * ⚠ import 를 동적으로 하는 이유: 이 모듈은 **폰 홈**(`phone/TodayView`)도 쓰는데 폰은 이 조각을
 * 부르지 않는다(셸 전용 커맨드 + Anki 는 PC 에 있다). 정적으로 끌면 폰 번들이 볼트·Anki 계열을
 * 통째로 데려간다 — 예산 축 ③(플랫폼별 산출물)이 정확히 그런 새는 것을 잡으라고 있는 축이다.
 */
export async function loadOutside(lastDs: string, todayDs: string): Promise<AbsenceOutside> {
  const fromDs = iso(addDays(parseISO(lastDs), 1));
  const [{ vaultTouched }, { ankiReviewedBetween }] = await Promise.all([import('./tauri'), import('./anki')]);
  const [touched, ankiCards] = await Promise.all([
    vaultTouched(parseISO(fromDs).getTime()),
    ankiReviewedBetween(fromDs, todayDs),
  ]);

  /* 과목은 **빈도 순**이다 — 알파벳 순이면 한 과목에 몰아 쓴 날에도 엉뚱한 이름이 앞에 온다. */
  const freq = new Map<string, number>();
  for (const n of touched?.notes ?? []) {
    const s = n.subject;
    if (s) freq.set(s, (freq.get(s) ?? 0) + 1);
  }
  const subjects = [...freq.entries()]
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1))
    .slice(0, OUTSIDE_SUBJECTS)
    .map(([s]) => s);

  return { notes: touched ? touched.count : null, subjects, ankiCards };
}

export async function loadAbsence(todayDs: string = todayISO()): Promise<AbsenceSnapshot> {
  const empty: AbsenceSnapshot = { lastDs: null, thenReview: null };
  try {
    const visit = await selectDb<{ last: string | null }>(`SELECT MAX(day) AS last FROM route_visits WHERE day < ?`, [
      todayDs,
    ]);
    const lastDs = visit?.[0]?.last ?? null;
    if (!lastDs) return empty;
    const sig = await selectDb<{ overdue: number }>(`SELECT overdue FROM day_signals WHERE ds = ?`, [lastDs]);
    const overdue = sig?.[0]?.overdue;
    return { lastDs, thenReview: typeof overdue === 'number' ? overdue : null };
  } catch {
    return empty;
  }
}

/* ============================================================
   anki.ts — Anki 현황(볼트 _anki 파일 + AnkiConnect) — 서버/외부 데이터.
   ① 볼트 카드 스캔: 정본 _index.json.anki 매니페스트 우선, 없으면 anki/ 폴더 .txt 폴백.
   ② 실시간 due: AnkiConnect(localhost:8765, deckNames+getDeckStats).
   순수 fetch만 — 앱 상태에 복제 X. TanStack Query가 캐시/로딩/에러 소유(설계도 §1-B).
============================================================ */
import { iso } from './utils';
import { loadVaultIndex } from './vault';
import { dirEntries, pickDirectory } from './fsAccess';
import { isTauri, shellAnkiConnect, shellAnkiScan } from './tauri';

import { matchSubjectIndex } from './subjectMatch';

/** AnkiConnect 주소 — **브라우저 폴백 전용**이다(셸에서는 `src-tauri/src/anki.rs` 가 중계한다:
 *  AnkiConnect 가 `Origin` 을 검사하는데 `tauri://` 오리진이 그 화이트리스트에 없다).
 *  ⚠ 그쪽 `ANKI_CONNECT_URL` 과 **같은 값이어야 한다** — 포트는 애드온 설정으로 바뀔 수 있는
 *  값인데 지금은 주입 경로가 없다(2026-08-20 리뷰 m-23). 이름을 준 것은 그 사실을 grep 가능하게
 *  만드는 것까지다: 사용자가 포트를 바꾸는 경로가 필요해지면 두 상수를 함께 설정에서 읽게 한다
 *  (`src-tauri/src/ollama.rs` 가 `OLLAMA_BASE_URL` 로 이미 그 형태다). */
const ANKI_CONNECT_URL = 'http://localhost:8765';

export interface AnkiDeck {
  name: string;
  new: number;
  learn: number;
  review: number;
  total: number;
}
export interface AnkiLive {
  at: string;
  decks: AnkiDeck[];
  /** 조회한 **날짜**(로컬 ISO). `at` 은 `toLocaleString` 이라 사람은 읽어도 코드는 못 판정한다.
   *  ⚠ optional 인 이유는 옛 저장본 때문이다 — 이 필드 이전에 `runtime` 테이블에 남은 값은
   *  날짜를 모르고, 그때는 **모른다고 말한다**(아래 `ankiFreshness`). */
  ds?: string;
}
export interface AnkiFileDeck {
  file: string;
  subj: string;
  cards: number;
}
export interface AnkiFile {
  at: string;
  src: string;
  decks: AnkiFileDeck[];
}

interface IndexAnki {
  file: string;
  cards: number;
}

/** AnkiConnect 단일 호출 — Anki 미실행/방화벽 시 3초 타임아웃(무한대기 방지). */
export async function ankiConnect<T = unknown>(action: string, params: Record<string, unknown> = {}): Promise<T> {
  /* 셸(4단계-F)에선 Rust 가 중계한다 — AnkiConnect 가 `Origin` 을 검사하는데 셸 오리진
     `http://tauri.localhost` 는 기본 화이트리스트(`http://localhost`)에 없다. Rust 요청엔
     Origin 이 안 붙고, AnkiConnect 는 오리진 없는 요청(비-브라우저)을 허용한다.
     ⚠ 이 근거는 AnkiConnect 의 문서화된 동작이지 이 기계에서의 관측이 아니다 — 프로브를 돌린
        시점에 Anki 가 꺼져 있었고, 브라우저는 CORS 거부와 연결 거부를 같은 오류로 준다. */
  if (isTauri()) {
    const j = await shellAnkiConnect<{ error?: string; result?: T }>(action, params);
    if (j.error) throw new Error(j.error);
    return j.result as T;
  }
  const ac = new AbortController();
  const to = setTimeout(() => ac.abort(), 3000);
  try {
    const res = await fetch(ANKI_CONNECT_URL, {
      method: 'POST',
      body: JSON.stringify({ action, version: 6, params }),
      signal: ac.signal,
    });
    const j = (await res.json()) as { error?: string; result?: T };
    if (j.error) throw new Error(j.error);
    return j.result as T;
  } finally {
    clearTimeout(to);
  }
}

interface DeckStat {
  name: string;
  new_count: number;
  learn_count: number;
  review_count: number;
  total_in_deck: number;
}

/** 실시간 due — deckNames → getDeckStats. 연결 실패 시 throw(Query isError로 폴백 안내). */
export async function fetchAnkiLive(): Promise<AnkiLive> {
  const names = await ankiConnect<string[]>('deckNames');
  const stats = await ankiConnect<Record<string, DeckStat>>('getDeckStats', { decks: names });
  const decks: AnkiDeck[] = Object.values(stats).map((d) => ({
    name: d.name,
    new: d.new_count,
    learn: d.learn_count,
    review: d.review_count,
    total: d.total_in_deck,
  }));
  const now = new Date();
  return { at: now.toLocaleString('ko'), ds: iso(now), decks };
}

/**
 * 이 due 숫자가 **오늘 것인가**.
 *
 * ⚠ 이게 없던 동안 오늘 탭은 `runtime` 테이블에 남은 옛 값을 **오늘 값과 똑같이** 그렸다.
 * Anki due 는 날이 바뀌면 통째로 갈리므로 어제 숫자는 틀린 숫자인데, 화면엔 그 사실이
 * 어디에도 없었다 — "한눈에" 대시보드에서 가장 나쁜 오류 형태(조용하고 그럴듯하다).
 * ⚠ 모르면 모른다고 말한다(`ds` 없는 옛 저장본) — 신선하다고 우기지 않는다.
 */
export function ankiFreshness(
  live: AnkiLive | null | undefined,
  todayDs: string,
): { stale: boolean; label: string } | null {
  if (!live) return null;
  if (!live.ds) return { stale: true, label: '마지막 확인 시각을 몰라요' };
  if (live.ds === todayDs) return { stale: false, label: '오늘 확인함' };
  return { stale: true, label: `${live.ds}에 확인한 값이에요` };
}

/** 볼트 카드 스캔 — `_index.json` 의 anki 매니페스트 우선, 없으면 `anki/` 폴더 `.txt` 폴백.
 *  취소 시 null.
 *
 *  ⚠ **셸에선 폴더를 묻지 않는다**(4단계-I) — 워크스페이스를 이미 알기 때문이다. 3단계가 볼트
 *  노트 읽기에서 없앤 마찰을 여기서도 없앤 것이고, FSA 가 깨져서가 아니다(WebView2 에서
 *  `showDirectoryPicker` 는 실제로 동작한다 — 트랙 B 프로브로 확인). 그래서 셸 경로는
 *  `handle` 이 **null** 이다: 되물을 핸들이라는 개념 자체가 없다. */
export async function pickAndScanAnki(
  existing?: FileSystemDirectoryHandle,
): Promise<{ scan: AnkiFile; handle: FileSystemDirectoryHandle | null } | null> {
  if (isTauri()) {
    const r = await shellAnkiScan<{ src: string; decks: AnkiFileDeck[] }>();
    return { scan: { at: new Date().toLocaleString('ko'), src: r.src, decks: r.decks }, handle: null };
  }
  let handle = existing;
  if (!handle) {
    const picked = await pickDirectory(); // 미지원이면 FsUnsupportedError, 취소면 null
    if (!picked) return null;
    handle = picked;
  }
  let decks: AnkiFileDeck[] = [];
  let src = '';
  const idx = await loadVaultIndex(handle);
  if (idx && Array.isArray(idx.anki) && idx.anki.length) {
    decks = (idx.anki as IndexAnki[]).map((a) => ({
      file: a.file.replace(/\.txt$/, ''),
      subj: a.file.split('_')[0] ?? '',
      cards: a.cards,
    }));
    src = '_index.json';
  } else {
    let ank: FileSystemDirectoryHandle | null = null;
    for await (const [n, e] of dirEntries(handle))
      if ((n === 'anki' || n === '_anki') && e.kind === 'directory') ank = e as FileSystemDirectoryHandle;
    if (!ank) throw new Error('정본 _index.json도 anki 폴더도 못 찾았어요. 전공(볼트) 폴더를 선택하세요.');
    for await (const [fn, fh] of dirEntries(ank)) {
      if (fh.kind !== 'file' || !fn.endsWith('.txt')) continue;
      const t = await (await (fh as FileSystemFileHandle).getFile()).text();
      const cards = t.split('\n').filter((l) => l.trim() && !l.startsWith('#')).length;
      decks.push({ file: fn.replace('.txt', ''), subj: fn.split('_')[0] ?? '', cards });
    }
    src = 'anki/ 폴더';
  }
  return { scan: { at: new Date().toLocaleString('ko'), src, decks }, handle };
}

/** 덱들의 오늘 풀 due 합(new+learn+review). */
export function totalDue(decks: AnkiDeck[]): number {
  return decks.reduce((t, d) => t + deckDue(d), 0);
}

/** 덱 하나의 오늘 due(new+learn+review). */
function deckDue(d: AnkiDeck): number {
  return (+d.new || 0) + (+d.learn || 0) + (+d.review || 0);
}

/** 과목별 due 분해 결과. `unmatchedDecks`/`unmatchedDue` 는 **숨기지 않고 남긴다**(아래 ⚠). */
export interface DueBySubject {
  /** due 내림차순. `sid` 는 앱의 과목 id. */
  rows: { sid: string; name: string; due: number }[];
  /** 어느 과목에도 안 붙은 덱 수. */
  unmatchedDecks: number;
  /** 그 덱들의 due 합. */
  unmatchedDue: number;
}

/**
 * Anki 덱 due 를 **앱의 과목에 붙여** 분해한다(E18 · 2026-07-29).
 *
 * ⚠ 종전엔 `totalDue()` 가 전 덱을 **하나의 숫자**로 합쳤다. 덱 이름이 `AnkiLive.decks[].name`
 * 으로 살아 있는데 어디서도 `items[].name` 과 맞춰보지 않아, "Anki 340장"을 보고 **어느 과목이
 * 밀렸는지 알려면 Anki 를 직접 열어야** 했다(앱 밖 왕복). 그리고 복습 큐는 볼트 챕터만 보므로
 * Anki 가 200장 밀린 과목의 챕터를 태연히 또 올린다 — 두 시스템이 서로를 모른다.
 *
 * ⚠ **미연결 덱을 조용히 흡수하지 않는다.** 합계가 안 맞으면 눈에 띄어야 조인이 틀렸다는 것을
 * 알 수 있다("전자기학 120 · 회로 80 · 미연결 3덱 140장"). 숨기면 계측(E3)이 하려던 일을
 * 이 함수가 되돌린다.
 * ⚠ 매칭 규칙은 `subjectMatch` 가 소유한다 — 배분을 구동하는 그 규칙과 같아야 한다.
 */
export function dueBySubject(decks: AnkiDeck[], items: readonly { id: string; name: string }[]): DueBySubject {
  const names = items.map((i) => i.name);
  const bySid = new Map<string, { sid: string; name: string; due: number }>();
  let unmatchedDecks = 0;
  let unmatchedDue = 0;
  for (const d of decks) {
    const due = deckDue(d);
    if (due <= 0) continue; // 0장인 덱은 분해에 기여하지 않는다(있는 것만 말한다)
    const i = matchSubjectIndex(d.name, names);
    const it = i >= 0 ? items[i] : undefined;
    if (!it) {
      unmatchedDecks++;
      unmatchedDue += due;
      continue;
    }
    const cur = bySid.get(it.id);
    if (cur) cur.due += due;
    else bySid.set(it.id, { sid: it.id, name: it.name, due });
  }
  const rows = [...bySid.values()].sort((a, b) => b.due - a.due || (a.name < b.name ? -1 : 1));
  return { rows, unmatchedDecks, unmatchedDue };
}

/**
 * T-11 — `fromDs`~`toDs`(**양끝 포함**) 사이에 Anki 에서 실제로 복습한 카드 수.
 *
 * 부재 브리핑이 답해야 하는 질문은 "앱이 꺼져 있던 동안 밖에서 학습이 있었나"이고, Anki 는
 * 그 답을 날짜별로 이미 갖고 있다(`getNumCardsReviewedByDay` → `[["2026-08-01", 40], …]`).
 *
 * ⚠ **Rust 변경 0** — `ankiConnect` 가 액션 이름을 인자로 받는 범용 통로다(T-19 와 같은 근거).
 * ⚠ **못 물어보면 `null`이고 0 이 아니다.** Anki 가 안 떠 있는 것과 "그 기간에 한 장도 안 했다"는
 *   완전히 다른 사실인데 0 으로 접으면 화면에서 구분이 사라진다(`ankiLapses` 의 `unavailable` 규율).
 */
export async function ankiReviewedBetween(fromDs: string, toDs: string): Promise<number | null> {
  try {
    const rows = await ankiConnect<[string, number][]>('getNumCardsReviewedByDay');
    if (!Array.isArray(rows)) return null;
    let n = 0;
    for (const row of rows) {
      const [ds, cnt] = row ?? [];
      // 날짜 문자열은 사전순=시간순이라 그대로 비교한다(`iso` 와 같은 형식).
      if (typeof ds === 'string' && typeof cnt === 'number' && ds >= fromDs && ds <= toDs) n += cnt;
    }
    return n;
  } catch {
    return null;
  }
}

/** 볼트 카드 파일덱들의 총 카드 수 합 — totalDue와 대칭. 인라인 reduce 3중복 수렴(SR-11). */
export function totalCards(decks: AnkiFileDeck[]): number {
  return decks.reduce((t, d) => t + (+d.cards || 0), 0);
}

/* ── I002 **밖에서 이미 일어난 학습을 받는다** (2026-08-22 발상 축) ─────────────────────────

   ## 이 앱은 Anki 를 「몇 장 남았나」로만 읽었다

   `totalDue`·`dueBySubject` 는 전부 **due**(앞으로 할 것)를 센다. 그런데 이 회차가 실 DB 를
   열어 본 결과 학습 표가 전부 0행이었다 — 사람은 공부를 했는데 **앱에 도달하는 경로가 없다.**
   Anki 는 «오늘 몇 장 했나»를 이미 안다. 즉 없던 것은 데이터가 아니라 **입구**다.

   ⚠ `ankiReviewedBetween`(T-11)이 이미 날짜별 총량을 부른다 — **없는 것은 귀속**이다.
   그 함수는 «밖에서 학습이 있었나» 한 비트만 답하고, 어느 과목이었는지는 못 말한다.

   ## ⚠⚠ 파생하되 **쓰지 않는다** — 승인 줄을 둔다

   여기서 돌려주는 것은 «오늘 이 과목으로 N장 했다» 라는 **관측**이고, 그것을 완료로 반영할지는
   화면의 한 줄이 묻는다. 조용히 쓰면 두 가지가 나쁘다: ① 사용자가 안 누른 체크가 스스로
   켜지는 것을 되돌릴 방법이 화면에 없고 ② 매칭이 틀린 날(덱 이름이 바뀐 날) **틀린 완료가
   조용히 기록된다**. 이 저장소의 매칭은 이름 부분문자열이라 그 가능성이 실재한다(I035).

   ⚠ **Rust 변경 0** — `ankiConnect` 가 액션 이름을 받는 범용 통로다(T-11·T-19 와 같은 근거).
   ⚠ 못 물어보면 `null` 이고 0 이 아니다(`ankiReviewedBetween` 과 같은 규율).
   ⚠ 매칭 규칙은 `subjectMatch` 가 소유한다 — `dueBySubject` 와 **같은 규칙**이어야 한다.
     갈리면 같은 덱이 due 는 회로이론에 붙고 완료는 안 붙는 상태가 생기고, 그건 조용하다. */

/** 오늘 실제로 복습한 카드의 과목별 분해. `null` = 물어볼 수 없었다(Anki 꺼짐 등). */
export interface AnkiReviewedToday {
  rows: { sid: string; name: string; n: number }[];
  /** 어느 과목에도 안 붙은 카드 수 — **숨기지 않는다**(`dueBySubject` 와 같은 규율). */
  unmatched: number;
  /** 오늘 복습한 카드 총수(귀속 여부 무관). */
  total: number;
}

export async function ankiReviewedTodayBySubject(
  items: readonly { id: string; name: string }[],
): Promise<AnkiReviewedToday | null> {
  try {
    /* `rated:1` = **오늘** 답한 카드(Anki 의 하루 경계를 그대로 쓴다 — 우리가 자정을 다시
       정의하면 사용자가 보는 Anki 통계와 어긋난다). */
    const ids = await ankiConnect<number[]>('findCards', { query: 'rated:1' });
    if (!Array.isArray(ids)) return null;
    if (!ids.length) return { rows: [], unmatched: 0, total: 0 };
    const info = await ankiConnect<{ deckName?: string }[]>('cardsInfo', { cards: ids });
    if (!Array.isArray(info)) return null;
    const names = items.map((i) => i.name);
    const bySid = new Map<string, { sid: string; name: string; n: number }>();
    let unmatched = 0;
    for (const c of info) {
      const deck = typeof c?.deckName === 'string' ? c.deckName : '';
      const i = deck ? matchSubjectIndex(deck, names) : -1;
      const it = i >= 0 ? items[i] : undefined;
      if (!it) {
        unmatched += 1;
        continue;
      }
      const cur = bySid.get(it.id);
      if (cur) cur.n += 1;
      else bySid.set(it.id, { sid: it.id, name: it.name, n: 1 });
    }
    const rows = [...bySid.values()].sort((a, b) => b.n - a.n || (a.name < b.name ? -1 : 1));
    return { rows, unmatched, total: info.length };
  } catch {
    return null;
  }
}

/** 그 과목이 오늘 Anki 를 했는가 — 화면이 「반영」 줄을 그릴지 가르는 유일한 술어. */
export function ankiDidToday(r: AnkiReviewedToday | null, sid: string): number {
  return r?.rows.find((x) => x.sid === sid)?.n ?? 0;
}

/* ============================================================
   api.ts — 백엔드 호출 래퍼(프레임워크 무관). **셸의 Rust 커맨드가 백엔드다**(4단계).
   서버/외부 상태라 TanStack Query가 캐시/무효화를 소유한다(Phase 5에서 훅 추가).
   여기선 순수 호출만 — 앱 상태에 복제하지 않는다(설계도 §1-B).

   4단계에서 serve.js(Node HTTP · 라우트 12종)를 Rust 커맨드로 옮기고 삭제했다. **소비처 무변경**이
   판정 기준이었고 충족했다 — 전송 분기는 전부 이 파일 안에 있다(`isTauri()` · 에러 분류 번역).
   ⚠ `isTauri()` 가 거짓인 경로(브라우저 `npm run dev`·트랙 A)엔 **백엔드가 없다.** 남아 있는
   `/api` fetch 는 트랙 A 가 invoke 스텁으로 대체하며, 실사용에서 이 가지는 도달하지 않는다.
============================================================ */
import { recordAiCall } from './aiUsage';
import {
  ARTIFACT_NOT_FOUND,
  artifactRead,
  isTauri,
  shellCapabilities,
  shellOllamaEmbed,
  shellOllamaRun,
  shellRunTool,
} from './tauri';
import type { ArtifactName } from './artifacts.gen';

/** `getArtifact` 가 받을 수 있는 이름 — **파일로 존재하는 산출물만**.
 *  정본은 `src-tauri/src/artifact.rs` 의 `ARTIFACTS` 이고, `index` 는 스키마 축에만 있어 뺀다
 *  (근거는 아래 `getArtifact` 머리주석). 두 목록이 갈리는 것을 타입이 잡는다. */
export type FetchableArtifact = Exclude<ArtifactName, 'index'>;

export interface PingResponse {
  ok: boolean;
  server: string;
  tools: string[];
  work: string;
  /** 전역 캡처 단축키 등록 여부(E20 · 셸 전용). 브라우저에선 undefined. */
  hotkey?: boolean;
  /** 등록 실패 사유 — **이 값이 있을 때만 실패다.** `hotkey === false` 만 보고 경고를 띄우면
   *  브라우저·dev 에서 상시 경고가 되고, 상시 경고는 곧 무시된다(Rust `hotkey.rs` 와 같은 계약). */
  hotkeyError?: string | null;
  /** 볼트 **감시** 실패 사유(H7 · 셸 전용). `hotkeyError` 와 같은 계약 — **값이 있을 때만 실패**다.
   *  감시가 죽으면 볼트를 고쳐도 화면이 안 바뀌는데, 종전엔 그 사실이 Rust 로그에만 있었다. */
  vaultWatchError?: string | null;
}

export interface RunResult {
  ok: boolean;
  out: string;
  code: number;
  label?: string;
}
/* ⚠ **`stats` 를 뺐다(4단계-C).** serve.js 는 도구 stdout 을 정규식 6종으로 파싱해 `stats` 를
   실어 보냈는데, **프런트에서 이 필드를 읽는 곳이 하나도 없다** — 소비처 3곳(`useCollectTool`
   `Discovery`·`Ledger`)이 전부 `ok`·`code`·`out` 만 쓴다. 실제 도구 출력에 대보니 파서 2개가
   이미 틀린 값을 내고 있었고(볼트 건강검진의 `deadlinks` 는 문구가 "죽은 위키링크"로 바뀌어 늘
   null · `healthy` 는 개별 항목의 ✅ 하나만 걸려도 true 라 점검 439건인 볼트를 '양호'로 본다),
   **아무도 안 읽었기 때문에 그 오류가 드러난 적이 없다.** 읽히지 않는 값을 언어를 바꿔 옮기면
   같은 결함을 새 코드에 심는 것이라 이식하지 않는다. 필요해지면 `out` 에서 언제든 다시 뽑을 수
   있고, 그때는 실제 출력을 보고 쓰게 된다. */

async function getJSON<T>(url: string): Promise<T> {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return (await r.json()) as T;
}

/** 능력 탐지 — 백엔드를 쓸 수 있는지와 도구 목록.
 *  셸(4단계-F)에선 `capabilities` 커맨드가 답한다. **이름을 `getPing` 으로 둔 것은 의도적이다** —
 *  소비 8곳이 이 값을 "백엔드를 지금 쓸 수 있는가"로 읽고 있고 그 의미는 안 바뀌었다. 바뀐 건
 *  *무엇이 그 답을 결정하는가*(서버 프로세스 → 워크스페이스 유효성)이고, 그건 `tauri.ts` 에 적었다. */
export function getPing(): Promise<PingResponse> {
  if (isTauri()) return shellCapabilities<PingResponse>();
  return getJSON<PingResponse>('/api/ping');
}

/** 산출물(읽기 전용) — **셸이 워크스페이스에서 파일로 읽어 오는 것만**.
 *
 *  ⚠⚠ **`index` 는 여기 없다**(2026-08-20 리뷰 m-1). 종전 이 줄은 그것을 유효 인자로 광고했는데
 *  `src-tauri/src/artifact.rs` 의 `ARTIFACTS` 에 그런 항목이 **없다**(그 파일의 테스트 이름 자체가
 *  `다섯_종이_모두_등록돼_있다` 다). `index` 는 **다른 네임스페이스**에 산다 —
 *  `artifacts.gen.EXPECTED_SCHEMA_VERSION`(스키마 버전 축)이고, 실제로는 볼트 스캔이 읽은
 *  `_index.json` 을 `lib/vault.ts` 가 `parseArtifact('index', …)` 로 검증할 때만 쓰인다.
 *  그 두 목록을 한 문장에 합쳐 놓은 것이 이 주석의 결함이었다.
 *
 *  잘못 부르면 증상이 조용하다: Rust 가 `NOT_FOUND` → 아래에서 `HTTP 404` 로 번역 →
 *  `artifactState.classifyArtifact` 가 **'미생성(empty)'** 으로 분류 → 화면은 "아직 파이프라인이
 *  안 돌았습니다"를 띄운다. **오류가 정상 빈 상태로 보인다** — 그래서 인자 타입을 좁힌다.
 *
 *  ⚠ 종전 이 줄은 `discovery`·`reads`·`markets` 도 세었다 — 셋 다 P10 W4 에서 `survey/` 로 갔다
 *  (불변식 I-4 가 "교양 도메인이 늘어도 이 수는 안 는다"를 잠근다).
 *
 *  4단계-B 부터 **셸에선 Rust 커맨드**(`artifact_read`)가 읽고, 브라우저에선 기존 `/api` 를 탄다.
 *  전송이 갈렸어도 **반환 계약과 에러 분류는 하나로 유지**한다 — 미생성·알 수 없는 이름은
 *  양쪽 모두 `HTTP 404` 로 수렴시켜 `artifactState.ts:31` `isNotYetError` 가 그대로 '미생성'으로
 *  분류하게 한다. 이 번역을 여기서 하는 이유: 소비처 7개 lib 래퍼와 10개 탭이 분류 규칙을
 *  각자 알면 전송을 바꿀 때마다 그 수만큼 갈라진다. */
export async function getArtifact<T = unknown>(
  name: FetchableArtifact,
): Promise<{ ok: boolean; data?: T; raw?: string; error?: string }> {
  if (isTauri()) {
    try {
      const r = await artifactRead<T>(name);
      if (r) return r;
    } catch (e) {
      // invoke 는 문자열로 reject 한다(Error 가 아니다) → 접두 검사 전에 문자열로 정규화.
      const msg = e instanceof Error ? e.message : String(e ?? '');
      throw new Error(msg.startsWith(ARTIFACT_NOT_FOUND) ? 'HTTP 404' : msg);
    }
  }
  return getJSON(`/api/artifact/${encodeURIComponent(name)}`);
}

/** 화이트리스트 도구 실행(지식상태 재빌드·볼트 건강검진 등).
 *
 *  **타임아웃은 백엔드가 소유한다** — Rust `tools.rs` 의 **도구별 상한**(정본 = 그 파일 `TOOLS`
 *  의 `timeout_ms`)이 프로세스를
 *  트리째 죽이므로 "영원히 도는 스피너"가 원리적으로 없다. 클라이언트 쪽 벽시계는 두지 않는다:
 *  그건 *기다리기를 그만두는* 것일 뿐 프로세스를 멈추지 못해, 실제로는 "화면만 포기하고 CPU 는
 *  계속 도는" 상태를 만든다(옛 185s `AbortSignal` 이 그랬다 — 서버 캡 180s 를 뒤따르는 값이라
 *  백엔드가 사라진 지금은 근거 자체가 없어졌다).
 *
 *  ⚠ 종전 이 문단 첫 줄은 상한을 "60~180s" 라 적었는데 **실제 `TOOLS` 에 180s 는 없다** — 그건
 *  방금 말한 삭제된 서버 캡이고, 이력이어야 할 수가 현재형 문장에 남아 있었다(2026-08-20 리뷰
 *  m-21). 이 줄이 "얼마나 기다려야 하는가"의 유일한 프런트 문서라 3분 스피너를 정상으로
 *  오판하게 만든다. 수를 다시 적으면 또 표류하므로 **상수를 가리킨다.**
 *
 *  ⚠ **`opts.signal` 은 도구 실행을 중단시키지 않는다.** `invoke` 가 `AbortSignal` 을 안 받는다.
 *  받아 두는 이유는 호출부(`useCollectTool`)가 이미 넘기고 있어서이고, 진짜 중단이 필요해지면
 *  `ollama_cancel`(4단계-E) 과 같은 관용구로 취소 커맨드를 붙인다. */
export async function runTool(
  tool: string,
  body?: Record<string, unknown>,
  opts?: { signal?: AbortSignal },
): Promise<RunResult> {
  if (isTauri()) {
    const subject = typeof body?.subject === 'string' ? body.subject : undefined;
    return shellRunTool(tool, subject);
  }

  // 브라우저 폴백 — 4단계 이후 이 경로엔 백엔드가 없다(트랙 A 는 invoke 스텁을 쓴다).
  const r = await fetch(`/api/run/${encodeURIComponent(tool)}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body || {}),
    signal: opts?.signal,
  });
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return (await r.json()) as RunResult;
}

async function postJSON<T>(url: string, body: Record<string, unknown>): Promise<T> {
  const r = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return (await r.json()) as T;
}

/* ── Ollama 스트리밍 ────────────────────────────────────────────
   셸에선 Rust 가 Channel 로 토큰 델타를 밀어 넣고 최종 결과는 커맨드 반환값으로 온다(4단계-E).
   첫 토큰이 2~3초면 도착하므로 "수십 초 침묵"이 사라지고, AbortSignal로 생성 자체를 중단할 수 있다. */
export interface StreamOpts {
  /** 누적 원문이 갱신될 때마다 호출(미리보기용). */
  onDelta?: (accumulated: string) => void;
  signal?: AbortSignal;
}

async function postStream<T>(url: string, body: Record<string, unknown>, opts?: StreamOpts): Promise<T> {
  const r = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...body, stream: true }),
    signal: opts?.signal,
  });
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  const ct = r.headers?.get?.('content-type') ?? ''; // 테스트 스텁 Response(headers 없음)도 수용
  // 스트림이 아닌 단발 JSON(가드 403/429 폴백 등)도 같은 자리로 수렴.
  if (!r.body || !ct.includes('ndjson')) return (await r.json()) as T;
  const reader = r.body.getReader();
  const dec = new TextDecoder();
  let buf = '';
  let acc = '';
  let final: T | null = null;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });
    let i;
    while ((i = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, i);
      buf = buf.slice(i + 1);
      if (!line.trim()) continue;
      try {
        const j = JSON.parse(line) as { done?: boolean; d?: string };
        if (j.done) final = j as T;
        else if (typeof j.d === 'string') {
          acc += j.d;
          opts?.onDelta?.(acc);
        }
      } catch {
        /* 불완전한 줄은 무시(다음 청크에서 완성) */
      }
    }
  }
  if (!final) throw new Error('스트림이 결과 없이 끝났어요');
  return final;
}

/** 스트리밍 원문(format:json 생성 중간체)에서 사람이 읽을 미리보기를 뽑는다 —
    완성된 문자열 *값*만(키 이름 제외) 이어붙여 "타이핑되는" 느낌을 준다. 순수 함수. */
export function previewFromJsonStream(text: string): string {
  const out: string[] = [];
  const re = /"(?:[^"\\]|\\.)*"/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text))) {
    if (/^\s*:/.test(text.slice(re.lastIndex))) continue; // 뒤에 콜론이 오면 키
    try {
      const v = JSON.parse(m[0]) as string;
      if (v.trim()) out.push(v.trim());
    } catch {
      /* 미완성 리터럴 */
    }
  }
  return out.join(' · ');
}

/* ── Ollama 라우트 5종의 전송 분기(4단계-E) ────────────────────────
   셸이면 Rust 커맨드, 브라우저면 기존 /api. **분기를 이 한 함수에 가둔다** — 아래 네 개의
   공개 함수와 소비처(`Review` 의 회고 코치)는 전송을 모른다.
   ⚠ 종전 소비는 셋이었다(읽을거리 코치·어휘 · 증시 브리핑) — P10 W4 에서 그 화면들이 갔다.
   `kind` 가 곧 경로 조각이라 브라우저 경로는 `/api/${kind}` 로 그대로 재구성된다. */
async function aiCall<T>(kind: string, body: Record<string, unknown>, opts?: StreamOpts, streaming = true): Promise<T> {
  /* I023 — **이 축이 살아 있는가**의 유일한 계기(근거는 `lib/aiUsage` 머리주석). 전송 분기와
     같은 자리에 두는 이유는 `visits` 와 같다: 화면마다 세게 하면 새 소비처에서 빠뜨리고,
     빠진 것은 0 으로 보인다 — 그리고 이 축에서 0 의 결론은 «Rust 473줄을 지운다» 이다. */
  recordAiCall();
  if (isTauri()) return shellOllamaRun<T>(kind, body, opts);
  return streaming ? postStream<T>(`/api/${kind}`, body, opts) : postJSON<T>(`/api/${kind}`, body);
}

/* ── 주간 회고 코치 (로컬 Ollama · 셸 커맨드) ─────────────────
   앱이 계산한 결정적 인사이트를 받아 '다음 주에 뭘 바꿀지'로 구체화한다. 숫자를 새로 짓지 않는다. */
export interface ReviewCoachResult {
  headline?: string;
  actions?: string[];
  focus?: string;
  encourage?: string;
}

/** 온디맨드 회고 코칭(Ollama 스트리밍). facts=이번 주 관찰 문장들, weakSpots=반복 약점 문장들. 꺼져 있으면 에러. */
export function reviewCoach(
  facts: string[],
  weakSpots: string[],
  opts?: StreamOpts,
): Promise<{ ok: boolean; error?: string; coach?: ReviewCoachResult }> {
  return aiCall('review/coach', { facts, weakSpots }, opts);
}

/* ── 임베딩 (로컬 Ollama · 셸 커맨드) ─────────────────────
   의미 검색·지식맵 자동 연결용. 모델·대상은 서버가 고정한다(`ollama pull bge-m3` 필요). */
export function embedTexts(
  texts: string[],
): Promise<{ ok: boolean; error?: string; model?: string; vectors?: number[][] }> {
  recordAiCall(); // I023 — 임베딩도 같은 축이다(`aiCall` 을 안 타므로 여기 따로 있다)
  if (isTauri()) return shellOllamaEmbed(texts);
  return postJSON('/api/embed', { texts });
}

/* ============================================================
   cloud/push.ts — 아웃박스를 밀어올리는 **재시도·백오프 엔진**(C-1).

   ## 전송이 주입되는 이유

   서버는 아직 없다(C-4). 그런데 재시도·백오프·워터마크 전진은 **서버와 무관하게 지금
   설계하고 지금 테스트할 수 있는** 부분이고, C-4 이후에 얹으면 훨씬 비싸진다(설계서 §7 이
   C-1~C-3 을 앞에 둔 이유 그대로). 그래서 `CloudTransport` 인터페이스만 두고 구현은 C-5 가
   끼운다 — 테스트는 가짜 전송으로 전 경로를 돈다.

   ## ⚠ 이 함수는 `whenSettled()` 에 절대 엮이면 안 된다

   설계서 §5-2: `whenSettled()` 는 **로컬만** 기다려야 한다. 창 닫기 가드가 원격 전송까지
   기다리면 **네트워크가 죽었을 때 앱이 안 닫힌다**(1단계에서 다른 원인으로 이미 겪은 실패
   모드). 그래서 여기서 만드는 프라미스는 `db/write.ts` 의 `_inflight` 체인에 **넣지 않는다**.
   밀어올리기는 유실 시 다음 시도가 재개하지만(워터마크가 안 전진했으므로), 로컬 쓰기는
   유실이 곧 소실이라 성질이 다르다.

   ## 실패 시 워터마크를 전진시키지 않는 것이 안전 계약 전부다

   전송이 실패하면 워터마크는 그대로다 → 같은 행이 다음 배치에 다시 걸린다. 서버가 받았는데
   응답만 유실된 경우 **같은 행을 두 번 보내지만**, 행 단위 LWW 라 재적용이 무해하다(멱등).
   반대 방향(성공 확신 없이 전진)은 조용한 유실이라 복구가 없다.
============================================================ */
import { batchSize, collectOutboxScan, commitWatermark, type OutboxBatch } from './outbox';
/* ⚠ **동적 import 로 바꾸지 말 것 — 2026-07-29 에 재 봤고 이득이 0.3KB 였다.**
   "이 줄이 zod 18KB 를 초기 청크로 끈다"는 진단이 있었는데 실측은 달랐다: zod 는 이미
   `db/boot`·`db/rows`·`db/write`·폰 엔트리가 **영속 계층의 부팅 검증**(C-2 경계 파싱)으로
   물고 있다 — 첫 페인트에 정의상 필요하다. 그래서 여기를 지연시켜도 zod 는 그대로 남고
   `cloud/schema` 자기 정의분(≈0.3KB)만 옮겨간다. 지연을 얻으려면 부팅 검증을 손봐야 하고
   그건 번들 항목이 아니라 설계 결정이다. */
import { MAX_BATCH_ITEMS, type OutboxRow, type OutboxTomb } from './contract';
import { parseOutboxBatch } from './schema';

/* 한 요청의 바이트 상한. 서버 `MAX_BODY_BYTES` 가 1MB 라 여유를 두고 자른다 — 건수만 세면
   `settings` 처럼 **한 행 = 슬라이스 전체**인 표(실측 `settings.items` 17KB)에서 500건이 1MB 를
   넘겨 본문 거부로 떨어진다. 두 축 중 먼저 걸리는 쪽에서 자른다. */
const MAX_BATCH_BYTES = 700_000;

/**
 * 배치를 전송 가능한 조각으로 자른다(H2 · 2026-07-31 `/감사 근본`).
 *
 * ## ⚠ 왜 필요한가 — 계약 두 개가 정면으로 어긋나 있었다
 *
 * `capBatch`(`contract.ts`)는 **정확성 우선**이라 한 스탬프 그룹이 혼자 상한을 넘어도 통째로
 * 담고 `oversized:true` 로 알린다(안 그러면 `cut` 이 0 이 되어 빈 배치 + 워터마크 정지 = 영구
 * 교착). 그런데 `collectOutbox` 가 그 플래그를 버리고, `parseOutboxBatch` 는 `total > 상한` 을
 * **거부**한다 → `blocked`. 워터마크가 안 움직이므로 그 기기의 **모든 편집이 영원히 안 올라가고**
 * 다음 시도도 같은 배치를 만들어 자가복구 경로가 없다.
 *
 * 유일한 생산자는 `006_backfill_stamps.sql` 이다 — 7개 표의 레거시 행 전부에 `updated_at = 1`
 * **상수 하나**를 찍는다(= 단일 그룹). 실 DB 에 그 그룹이 실재한다(18행 — 상한 미만이라 이
 * 기기에선 아직 안 터졌다).
 *
 * ## 왜 마이그레이션이 아니라 청크인가
 *
 * 대안은 v10 으로 레거시 행을 재스탬프하는 것이었는데, 그건 **되돌리기 힘든 코어 변경**을 이미
 * 적용된 DB 에 하나 더 얹는다. 청크는 그럴 필요가 없다: fence 계약은 "모든 항목이 (since, upto]
 * 안에 있을 것"이라 **부분집합도 그대로 만족**하고, 워터마크는 마지막 조각이 성공한 뒤 **한 번만**
 * 전진한다. 중간에 실패하면 다음 시도가 그룹 전체를 다시 보내지만 **행 단위 LWW 라 재적용이
 * 무해하다**(이 파일 머리주석의 멱등 논거 그대로).
 */
export function chunkBatch(batch: OutboxBatch): OutboxBatch[] {
  const items: ({ kind: 'row'; v: OutboxRow } | { kind: 'tomb'; v: OutboxTomb })[] = [
    ...batch.rows.map((v) => ({ kind: 'row' as const, v })),
    ...batch.tombstones.map((v) => ({ kind: 'tomb' as const, v })),
  ];
  if (items.length <= MAX_BATCH_ITEMS) {
    const bytes = JSON.stringify(batch).length;
    if (bytes <= MAX_BATCH_BYTES) return [batch];
  }
  const out: OutboxBatch[] = [];
  let rows: OutboxRow[] = [];
  let tombs: OutboxTomb[] = [];
  let bytes = 0;
  const flush = (): void => {
    if (!rows.length && !tombs.length) return;
    out.push({ since: batch.since, upto: batch.upto, rows, tombstones: tombs });
    rows = [];
    tombs = [];
    bytes = 0;
  };
  for (const it of items) {
    const b = JSON.stringify(it.v).length;
    // 한 항목이 혼자 상한을 넘으면 자를 방법이 없다 — 그 항목만 담은 조각으로 보낸다(서버 판정에 맡긴다).
    if (rows.length + tombs.length >= MAX_BATCH_ITEMS || (bytes > 0 && bytes + b > MAX_BATCH_BYTES)) flush();
    if (it.kind === 'row') rows.push(it.v);
    else tombs.push(it.v);
    bytes += b;
  }
  flush();
  return out;
}

/** 배치 하나를 서버로 보낸다. 실패는 **throw** 로 알린다(반환값으로 삼키지 않는다). */
export interface CloudTransport {
  push(batch: OutboxBatch): Promise<void>;
}

/**
 * 전송이 **"재시도해도 소용없다"**고 알리는 방법.
 *
 * ⚠ 이 구분이 없으면 재시도가 **해로워진다**. 호스트를 Cloudflare 로 정하면서 VM 에는 없던
 * 축이 생겼다 — **일일 한도**(D1 행 쓰기·Worker 요청). 한도를 소진하면 서버가 계속 거부하는데,
 * 백오프 상한이 60초라 그 상태로 **하루 종일 1분마다 헛친다.** 나쁜 건 낭비가 아니라 침묵이다:
 * 앱은 "동기화 시도 중"으로 보이고 사용자는 멈춘 걸 모른다.
 *
 * 이 부류에 해당하는 것: 일일 한도 소진 · 인증 만료/폐기 · 페이로드 거부(스키마 불일치).
 * **네트워크 오류·5xx·타임아웃은 여기 해당하지 않는다** — 그건 재시도가 정확히 맞는 처방이다.
 */
export class PermanentPushError extends Error {
  readonly permanent = true;
  constructor(message: string) {
    super(message);
    this.name = 'PermanentPushError';
  }
}

/** 전송이 낸 오류가 재시도 불가인가. 클래스 상속에 기대지 않는다(번들 경계를 넘으면 깨진다). */
export function isPermanent(e: unknown): boolean {
  return typeof e === 'object' && e !== null && (e as { permanent?: unknown }).permanent === true;
}

export type PushStatus =
  /** 보냈고 워터마크가 전진했다. */
  | 'pushed'
  /** 보낼 게 없었다(워터마크는 상한선까지 전진한다 — 아래 참조). */
  | 'idle'
  /** DB 를 못 읽었다(브라우저·미가용). 재시도 대상이 아니다. */
  | 'unavailable'
  /** 전 시도 실패. 워터마크는 그대로 — 다음 호출이 같은 배치를 다시 시도한다. */
  | 'failed'
  /** 재시도가 무의미하다고 서버가 알렸다(한도·인증·페이로드). **호출부가 사용자에게 알려야 한다.** */
  | 'blocked';

export interface PushResult {
  status: PushStatus;
  /** 보낸 변경 건수. */
  sent: number;
  /** 실제로 시도한 횟수(1 = 첫 시도에 성공). */
  attempts: number;
  /** `failed`·`blocked` 일 때 마지막 오류 메시지. */
  error?: string;
  /**
   * **이 배치 뒤에 아웃박스가 더 남았는가**(H4 · 2026-08-01).
   *
   * 종전 드레인 조건은 `sent >= MAX_BATCH_ITEMS` 였는데 `capBatch` 는 **스탬프 그룹 경계**에서
   * 자르므로 그 수가 상한과 같아지는 일이 거의 없다 → 드레인이 사실상 안 돌았다. 판정은
   * 스캔한 쪽만 할 수 있어서(`upto < fence`) 여기까지 실어 온다 — 근거는 `outbox.OutboxScan`.
   */
  more: boolean;
}

export interface PushOptions {
  /** 최대 시도 횟수(첫 시도 포함). 기본 5. */
  maxAttempts?: number;
  /** 첫 재시도 대기(ms). 기본 1000. 이후 2배씩. */
  baseDelayMs?: number;
  /** 대기 상한(ms). 기본 60초 — 오래 끊긴 뒤 복귀했을 때 1분마다 재시도한다. */
  maxDelayMs?: number;
  /** 테스트 주입점. 기본은 실제 타이머. */
  sleep?: (ms: number) => Promise<void>;
  /** 테스트 주입점(지터). 기본 `Math.random`. */
  random?: () => number;
}

const defaultSleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

/**
 * 지수 백오프 + 지터. 지터가 있는 이유는 무리 동기화(thundering herd)가 아니라 —
 * 기기가 몇 대 없다 — **서버가 잠깐 죽었을 때 모든 재시도가 같은 순간에 몰리는 것**을 피하기
 * 위해서다. 전량 지터(0~delay)가 아니라 절반 고정 + 절반 무작위로 최소 대기를 보장한다.
 */
export function backoffDelay(attempt: number, opts: PushOptions = {}): number {
  const base = opts.baseDelayMs ?? 1000;
  const max = opts.maxDelayMs ?? 60_000;
  const random = opts.random ?? Math.random;
  const raw = Math.min(base * 2 ** (attempt - 1), max);
  return Math.round(raw / 2 + (raw / 2) * random());
}

/**
 * 아웃박스를 한 번 밀어올린다(내부적으로 재시도까지 포함).
 *
 * 호출부는 이 함수를 주기적으로/온라인 복귀 시 부르면 된다 — **상태를 들고 있지 않으므로**
 * 언제 불러도 안전하고, 보낼 게 없으면 싸게 끝난다.
 */
export async function pushOutbox(transport: CloudTransport, opts: PushOptions = {}): Promise<PushResult> {
  const scan = await collectOutboxScan();
  if (!scan) return { status: 'unavailable', sent: 0, attempts: 0, more: false };
  const { batch, more } = scan;

  const size = batchSize(batch);
  if (size === 0) {
    /* 보낼 게 없어도 워터마크는 상한선까지 전진시킨다. 안 하면 매번 같은 구간을 다시 스캔하고,
       무엇보다 `updated_at <= fence` 의 fence 가 계속 커지는데 하한이 안 움직여 **질의 범위가
       무한히 넓어진다**(인덱스가 있어도 범위 스캔이 커진다). 빈 배치의 전진은 유실 위험이 없다 —
       그 구간에 보낼 것이 실제로 없었기 때문이다. */
    await commitWatermark(batch.upto);
    return { status: 'idle', sent: 0, attempts: 0, more };
  }

  /* ⚠ 한 스탬프 그룹이 혼자 상한을 넘을 수 있다(H2) — `chunkBatch` 주석이 그 계약을 소유한다.
     대개 조각은 하나이고, 그때는 아래 루프가 종전과 글자 그대로 같은 일을 한다. */
  const chunks = chunkBatch(batch);

  /* ⚠ **보내기 전에 자기 페이로드를 검증한다**(C-2). 서버가 어차피 검증하는데 왜 여기서도
     하냐면 — 깨진 배치는 재시도해도 계속 깨져 있다. 서버까지 갔다 오면 그 왕복이 5번 반복되고
     원인은 "서버가 400 을 준다"로만 보인다. 여기서 걸면 **어느 행의 무엇이 틀렸는지**가 나온다.
     그리고 서버와 클라이언트가 같은 스키마를 본다는 것을 테스트가 보장하게 된다.
     ⚠ 검증 단위는 **조각**이다 — 상한 검사가 그 단위로만 의미를 갖기 때문이다(위 주석). */
  for (const c of chunks) {
    const checked = parseOutboxBatch(c);
    if (!checked.ok) {
      return { status: 'blocked', sent: 0, attempts: 0, more, error: `배치가 계약을 위반한다 — ${checked.error}` };
    }
  }

  const maxAttempts = opts.maxAttempts ?? 5;
  const sleep = opts.sleep ?? defaultSleep;
  let lastError = '';
  let attempts = 0;

  for (const c of chunks) {
    let ok = false;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      attempts += 1;
      try {
        await transport.push(c);
        ok = true;
        break;
      } catch (e) {
        lastError = e instanceof Error ? e.message : String(e);
        /* 재시도가 무의미한 실패는 **즉시** 끊는다 — 여기서 계속 돌면 하루 종일 헛치면서
           사용자에겐 정상으로 보인다(`PermanentPushError` 주석 참조). 워터마크는 실패한
           배치이므로 당연히 전진시키지 않는다. */
        if (isPermanent(e)) return { status: 'blocked', sent: 0, attempts, more, error: lastError };
        if (attempt < maxAttempts) await sleep(backoffDelay(attempt, opts));
      }
    }
    /* 조각 하나라도 못 보냈으면 워터마크를 건드리지 않고 끝낸다 — 다음 호출이 **그룹 전체**를
       다시 만든다. 앞 조각을 두 번 보내지만 행 단위 LWW 라 재적용이 무해하다(머리주석의 멱등). */
    if (!ok) return { status: 'failed', sent: 0, attempts, more, error: lastError };
  }

  /* ⚠ **전 조각 성공 뒤에만** 워터마크가 전진한다. 이 순서가 이 파일의 안전 계약 전부다. */
  await commitWatermark(batch.upto);
  return { status: 'pushed', sent: size, attempts, more };
}

/* ============================================================
   cloud/run.ts — 동기화 1회를 조립한다(C-5). **밀어올리고 → 받아오고 → 병합한다.**

   ## ⚠ 워터마크가 **둘**이다

   C-1 의 `watermark` 는 "**내가 어디까지 보냈나**"이고, 여기서 쓰는 `cloud:pullMark` 는
   "**내가 어디까지 받았나**"다. 같은 값으로 겸하게 하면 안 된다 — 두 방향의 진행이 서로
   다르고(내가 밀어올린 뒤에도 상대는 그 앞에 있을 수 있다), 겸직시키면 한쪽 진행이 다른 쪽
   기록을 덮어 **받지 않은 변경을 받았다고 표시**하거나 그 반대가 된다.

   이건 C-1 이 "LWW 비교용 타임스탬프와 '보냈나' 표시를 같은 값으로 겸하게 하면 안 된다"고
   적은 것과 같은 종류의 실수다. 값이 싸다고 겸직시키면 나중에 조용히 틀린다.

   ## 순서: push 를 먼저

   내 편집을 먼저 올리고 나서 받는다. 반대로 하면 방금 받은 것이 내 아웃박스에 섞여
   되돌아갈 여지가 생긴다(LWW 라 결과는 같지만 유선 낭비이고 추적이 어려워진다).

   ## 호출부 계약

   이 함수는 **메모리 상태를 건드리지 않는다.** 병합된 상태를 돌려주기만 하고, `applyMerged()` 를
   부르는 것은 호출부다(⚠ `loadState` 아님 · C1) — `lib/` 는 zustand 를 모른다(I2 레이어 단방향).
============================================================ */
import { execDb, selectDb, setDiffBaseline } from '../db/sqlite';
import { pushOutbox, isPermanent, type PushResult, type CloudTransport } from './push';
import { makeTransport, pullChanges, readCloudConfig, unknownDroppedTotal } from './client';
import { applyPull } from './merge';
import { rowsToState, type DbRows } from '../db/rows';
import { scanConflicts } from './conflictScan';
import { batchSize } from './contract';
import { PULL_MARK_KEY as PULL_MARK } from './outbox';
import type { ConflictShadow } from './conflicts';
import type { AppState } from '../types';

async function readPullMark(): Promise<number> {
  const r = await selectDb<{ value: string }>('SELECT value FROM sync_state WHERE key = ?', [PULL_MARK]);
  return Number(r?.[0]?.value ?? 0) || 0;
}

/** ⚠ 뒤로 가지 않는다 — C-1 의 push 워터마크와 같은 이유(전진 기록을 잃으면 안 된다). */
async function commitPullMark(upto: number): Promise<boolean> {
  return execDb(
    `INSERT INTO sync_state (key, value) VALUES (?1, ?2)
       ON CONFLICT(key) DO UPDATE SET value = MAX(CAST(value AS INTEGER), CAST(?2 AS INTEGER))`,
    [PULL_MARK, String(upto)],
  );
}

export interface SyncResult {
  /**
   * ⚠ `blocked` 는 **스스로 낫지 않는 실패**다(H5 · 2026-07-31). push 축은 `push.status` 가
   * 이미 그 구분을 갖고 있었는데 pull 축엔 없어서, 아웃박스가 빈 상태에서 한도가 소진되면
   * `failed`(= "다음 시도에 다시 올려요")로 보고됐다. 원장은 `blocked` 를 오프라인보다 위로
   * 올려 말한다(`lib/syncLedger.ts`).
   */
  status: 'ok' | 'disconnected' | 'failed' | 'blocked';
  push?: PushResult;
  /** 받아서 적용한 변경 수. */
  pulled: number;
  /** 병합 결과 상태. **null 이 아니면 호출부가 `applyMerged()` 를 불러야 한다**(⚠ `loadState` 아님 · C1). */
  state: AppState | null;
  /** 이번 pull 이 LWW 로 덮은 **동시 로컬 편집**(있으면). 병합에는 영향 없는 관측 결과다(§150 보완). */
  conflicts?: ConflictShadow[];
  /**
   * 이번 동기화가 **이 버전이 모르는 테이블이라 버린** 항목 수(M-10 · 있으면).
   *
   * ⚠ 실패가 아니다 — 관용 파서의 정상 동작이다(`schema.ts` H16 절). 다만 "서버가 이 빌드보다
   * 새 스키마를 안다"는 뜻이라 **사용자가 알아야** 하고(앱 업데이트), 그 말을 거는 자리는
   * `lib` 이 아니라 store 층이다(`lib` 은 토스트를 모른다).
   */
  unknownDropped?: number;
  error?: string;
}

/* ⚠⚠ **재진입 가드는 여기, 공유층에 있다**(C-1 후속 · 2026-07-24).

   종전엔 겹침 방지가 `phone/sync.ts` 에만 있었다 — 그런데 `syncOnce` 를 부르는 곳은 폰만이
   아니다: 데스크톱은 `StorageGuard`(5분 틱)·`CloudCard`("지금 동기화"·연결 직후)에서 부르고,
   그 셋은 서로 겹칠 수 있었다(설정에서 버튼을 누르는 순간 틱이 겹치는 등). 겹치면 두 동기화가
   모듈 전역 가변 상태(`sqlite.ts` 의 diff 기준선 `_last`·스탬프 발급기·워터마크)를 **경합**하고,
   그건 `merge.ts` 머리주석이 경고한 "낡은 기준선이 받아온 변경을 되돌리는 문장을 만든다"의
   재현 경로다. 가드가 소비자 레이어(폰)에 있으면 다른 소비자가 상속받지 못한다 —
   그래서 겹침 방지를 **`syncOnce` 자체의 불변식**으로 끌어올린다. 이제 어느 경로로 불러도
   동시에 둘이 돌지 않는다. */
let _inflight: Promise<SyncResult> | null = null;

/**
 * 동기화 1회. 클라우드에 연결돼 있지 않으면 아무것도 하지 않는다(`disconnected`).
 *
 * ⚠ **겹쳐 돌지 않는다** — 이미 도는 중이면 그 약속을 돌려준다(위 주석 참조).
 *
 * 실패를 삼키지 않는다 — 호출부가 사용자에게 알릴 수 있어야 한다. 다만 **던지지도 않는다**:
 * 동기화 실패가 앱을 멈추면 안 되고(로컬은 멀쩡히 동작한다), 다음 시도가 재개한다.
 */
export function syncOnce(): Promise<SyncResult> {
  _inflight ??= runSyncOnce().finally(() => {
    _inflight = null;
  });
  return _inflight;
}

/* ⚠ **가득 찬 push 배치를 이어서 비운다(H2 · 2026-07-24 감사).** `capBatch` 로 `MAX_BATCH_ITEMS`
   에서 잘린 배치는 워터마크만 전진시키고 끝나는데, push 는 pull 과 달리 **메모리 상태를 안 바꿔**
   편집 구독(`syncController`)을 못 깨운다 — 즉 남은 아웃박스를 이어받을 에코가 없다. 폴링 없는 폰에서
   사용자가 편집·전환을 안 하면 초기 대량 push 가 다음 앱 열기까지 정체한다(유실 아님, 수렴 지연).
   가득 찬 배치가 나오는 동안 이어 돌려 한 번에 비운다. 각 회가 워터마크를 전진시켜 아웃박스는 단조
   감소하므로 종료가 보장되고, 폭주 방지로 상한도 둔다. `sent` 는 합계로 돌려준다. */
const MAX_PUSH_DRAIN = 50; // 50 × MAX_BATCH_ITEMS(500) = 25,000 행 — 현실적 초기 동기화를 전부 덮는다
async function drainPush(transport: CloudTransport): Promise<PushResult> {
  let res = await pushOutbox(transport);
  let sent = res.sent;
  /* ⚠⚠ **판정은 `more` 다 — `sent >= MAX_BATCH_ITEMS` 가 아니다**(H4 · 2026-08-01).
     `capBatch` 는 **스탬프 그룹 경계**에서 자르므로 보낸 건수가 상한과 정확히 같아지는 일은
     사실상 없다(상한 500에 400건 그룹이면 `sent=400`). 즉 위 주석이 약속한 드레인은 **한 번도
     안 돌았고**, 실측 5,348행을 비우는 데 사용자 트리거가 **14회** 필요했다("한 번에 비운다"가
     문서에만 있었다). 잘렸는지는 스캔한 쪽만 안다 → `outbox.OutboxScan.more` 가 그걸 실어 온다. */
  for (let i = 0; res.status === 'pushed' && res.more && i < MAX_PUSH_DRAIN; i++) {
    res = await pushOutbox(transport);
    sent += res.sent;
  }
  return { ...res, sent };
}

/* ⚠⚠ **`drainPull` 은 존재하지 않았다 — push 만 드레인했다**(H4 · 2026-08-01).

   비대칭의 대가가 컸다: 서버 pull 은 `limit`(200) + 다중 소스 천장으로 한 회에 일부만 준다.
   그런데 다음 회차를 부르는 것이 **`applyMerged` 의 부수효과**뿐이었다 — 상태가 바뀌니 편집
   구독이 깨어나 `syncSoon()` 이 걸리고, 그건 `AFTER_EDIT_MS`(1200ms) 뒤다. 두 번째 기기
   온보딩(≈5,300행)이면 **27라운드 × 1.2초 ≈ 30초 동안 UI 가 갈린 상태**로 돈다(중간 상태가
   화면에 계속 보인다). push 는 "한 번에 비운다"고 적어 놓고 pull 은 우연에 맡긴 셈이다.

   ⚠ 종료 조건이 **`n === 0`** 인 이유(그리고 `n < limit` 이 왜 틀렸는가): 서버는 소스마다
   `LIMIT` 을 걸고 **가장 보수적인 천장**으로 자른다(`index.ts` 의 `ceilingOf`). 그래서 어떤
   소스가 잘렸는데도 다른 소스의 낮은 천장 때문에 **총 건수가 limit 미만**으로 나올 수 있다 —
   그 조건으로 끊으면 남은 것을 두고 조용히 멈춘다. 대가는 데이터가 있던 동기화마다 빈 pull
   **1회**이고, 그건 "수렴을 다음 트리거에 맡긴다"보다 싸다.
   ⚠ 마크 전진(`commitPullMark`)이 매 회차 안에 있으므로 `since` 는 단조 증가한다 → 종료가
   보장된다. 그래도 상한을 둔다(서버가 같은 구간을 반복해 주는 병리 상황의 폭주 방지). */
const MAX_PULL_DRAIN = 50;

async function runSyncOnce(): Promise<SyncResult> {
  const cfg = await readCloudConfig();
  if (!cfg) return { status: 'disconnected', pulled: 0, state: null };

  try {
    // ① 내 편집을 먼저 올린다.
    const push = await drainPush(makeTransport(cfg));

    // ② 그다음 받아온다 — **빌 때까지**. `since` 는 **받기 전용** 워터마크다(머리주석 참조).
    let pulled = 0;
    /* ⚠ **행 표현만 들고 다닌다 — 변환은 루프 뒤 1회다**(2026-08-20 리뷰 m-7).
       바로 아래 문단이 이미 *"마지막 회차의 상태만 쓴다"* 라고 적어 뒀는데, 종전엔 `merged.state`
       를 읽어 회차마다 정본 전량을 `rowsToState` 로 다시 파싱하고 마지막 하나를 뺀 전부를 버렸다
       (`MAX_PULL_DRAIN` 이 50 이다). `applyPull` 의 `state` 가 지연 게터가 되면서 여기서 `rows`
       만 보관하면 그 낭비가 사라진다 — 의미론은 한 글자도 안 바뀐다. */
    let lastRows: DbRows | null = null;
    const conflicts: NonNullable<SyncResult['conflicts']> = [];
    /* ⚠⚠ **충돌 스캔의 기준선은 동기화 *시작* 시점의 마크다 — 회차마다 다시 읽으면 안 된다**
       (H-16 · 2026-08-06 감사).

       `detectConflicts` 의 조건 (2)는 `cur.updatedAt <= pullMark` 면 "지난 pull 이후 로컬이
       안 바뀜 = 정상 최신화"로 보고 건너뛴다. 그런데 드레인은 **회차마다 마크를 전진시키므로**
       2회차부터 그 기준선이 *이번 동기화 도중의* 값이 된다 → 이 동기화 전에 한 로컬 편집이
       전부 "이미 동기화된 것"으로 접히고 **그림자가 안 잡힌다.** 200행이 넘는 pull(=드레인이
       실제로 도는 경우)에서만 나타나므로 조용하다.

       왜 중요한가: §150 이 CRDT 를 기각하며 내세운 **유일한 보상 경로**가 이 그림자다("LWW 로
       덮되 사람이 되살릴 수 있다"). 그 절반이 새면 기각 논거 자체가 무효가 된다.
       ⚠ `pullChanges` 는 계속 **전진하는** 마크를 써야 한다(안 그러면 같은 구간을 반복한다) —
       두 값의 의미가 다르므로 겸직시키지 않는다. 이 파일 머리주석의 "워터마크가 둘"과 같은 규율. */
    /* 모르는 테이블로 버린 항목의 **이번 동기화 델타**(M-10) — 누계 게터를 앞뒤로 재서 구한다.
       드레인이 여러 회차라 회차마다 세지 않고 구간으로 잡는다. */
    const droppedBefore = unknownDroppedTotal();
    const scanSince = await readPullMark();
    for (let i = 0; i < MAX_PULL_DRAIN; i++) {
      const since = await readPullMark();
      const incoming = await pullChanges(cfg, since);
      if (batchSize(incoming) === 0) {
        /* 받을 게 없어도 마크는 전진시킨다 — 안 그러면 매번 같은 구간을 다시 묻는다.
           C-1 의 빈 배치 처리와 같은 판단이고, 받은 것이 없으니 유실 위험도 없다. */
        await commitPullMark(incoming.upto);
        break;
      }

      /* ③ 병합 **직전** 충돌 스캔 — 이 시점 로컬은 아직 병합-전이라 "덮이기 직전 값"을 본다.
         읽기 전용이라 병합의 LWW 불변식(merge.ts)에 손대지 않는다(§150 조용한 손실 보완). */
      const round = await scanConflicts(incoming, scanSince);
      if (round?.length) conflicts.push(...round);

      // ④ 병합. 기준선 정리까지 `applyPull` 이 하고, 메모리 반영은 호출부 몫이다.
      const merged = await applyPull(incoming);
      /* ⚠ **병합이 끝난 뒤에만** 마크를 전진시킨다. 순서가 반대면 병합 실패 시 그 구간을
         영영 다시 안 받는다 — C-1 의 "전송 성공 뒤에만 워터마크" 계약과 같은 규율이다. */
      await commitPullMark(incoming.upto);
      pulled += merged.applied;
      /* ⚠ **마지막 회차의 상태만 쓴다.** `applyPull` 은 매번 정본 전량을 다시 읽어 오므로
         마지막 것이 곧 누적 결과다 — 중간 스냅샷을 메모리에 싣지 않는 것이 요점이다(그게
         "UI 가 갈린 중간 상태로 30초"의 원인이었다).

         ⚠⚠ **`null` 로는 덮지 않는다**(C-1 · 2026-08-06 감사 · 실패 형태 ⓑ). `applyPull` 은
         되읽기(`readRows`)가 실패하면 **던지지 않고 `state:null` 을 돌려준다** — 그런데 종전엔
         그 null 이 앞 회차의 **유효한** 스냅샷을 덮었다. 그러면 드레인 끝에 `state:null` 이라
         호출부가 `applyMerged` 를 부르지 않고, 메모리는 병합-전 · DB 는 병합-후로 갈린다.
         그 어긋남의 대가는 조용하지 않다: 다음 편집의 flush 가 **받아온 행을 되돌리는 upsert 와
         상대 기기 행의 툼스톤**을 만들고, LWW 라 그게 서버까지 이긴다. */
      if (merged.rows) lastRows = merged.rows;
      /* 스냅샷이 안 나온 회차(되읽기 실패) — 기준선은 이 회차에서 안 섰지만(merge.ts 가 `back` 이
         있을 때만 세운다) **DB 는 이미 앞서 갔다.** 기준선을 무효화해 다음 쓰기가 DB 를 재독하게
         만든다. 비싼 선택이 아니고(다음 쓰기 1회의 전량 읽기) 정합이 회복된다.
         ⚠ **드레인을 끊지는 않는다** — 끊으면 H4 가 세운 "한 동기화가 끝까지 비운다"를 되돌리게
         되고, 뒤 회차가 성공하면 그쪽이 기준선·스냅샷을 정상으로 다시 세운다. */ else setDiffBaseline(null);
    }
    const unknownDropped = unknownDroppedTotal() - droppedBefore;
    return {
      status: 'ok',
      push,
      pulled,
      state: lastRows ? rowsToState(lastRows) : null,
      conflicts: conflicts.length ? conflicts : undefined,
      unknownDropped: unknownDropped > 0 ? unknownDropped : undefined,
    };
  } catch (e) {
    /* ⚠⚠ **드레인 중간에 죽으면 기준선을 무효화한다**(C-1 · 2026-08-06 감사 · 실패 형태 ⓐ).

       H4(2026-08-01)가 pull 을 드레인 루프로 만들면서 **"병합에 성공한 회차 뒤에 실패하는"**
       경로가 정상 경로가 됐다(그전엔 병합이 `try` 의 마지막 문장이라 성립 불가였다). 루프는
       종료조건이 `n===0` 이라 **데이터가 있는 모든 pull 뒤에 요청을 한 번 더** 내므로, 그 요청이
       실패하면 여기로 온다 — 이때 DB·기준선은 라운드 N-1 까지 병합-후인데 아래 `state:null` 때문에
       `applyMerged` 가 안 불려 **메모리만 병합-전**으로 남는다.

       그 어긋남은 조용히 끝나지 않는다: `syncController` 의 C1 방어망은 병합 창만 닫고(그 주석은
       *반대* 방향만 다룬다) 이 불일치는 보지 않으므로, 다음 편집의 flush 가 병합-전 메모리를
       병합-후 기준선과 대조해 **받아온 행을 되돌리는 upsert + 상대 기기 행의 툼스톤**을 만든다.
       LWW 라 그 되돌림이 서버까지 이긴다.

       처방으로 기준선 무효화를 고른 이유는 **실패 형태 둘 양쪽에서 안전**하기 때문이다(누적
       `state` 를 실어 보내는 쪽은 ⓑ 에서 틀린다 — DB 보다 뒤처진 스냅샷을 메모리에 싣게 된다).
       다음 쓰기가 `writeRows` 안에서 DB 를 재독하므로 어느 쪽이든 정합이 회복된다.
       ⚠ `writeRows` 실패 경로가 이미 쓰는 관용구라 새 개념이 아니다. */
    setDiffBaseline(null);
    /* 재시도가 무의미한 실패(한도 소진·인증 폐기·계약 위반)는 **`blocked`** 다 — `failed` 로
       접으면 원장이 "다음 시도에 다시 올려요"라 말하는데 그건 거짓이다(H5). */
    const status = isPermanent(e) ? 'blocked' : 'failed';
    return { status, pulled: 0, state: null, error: e instanceof Error ? e.message : String(e) };
  }
}

/* ============================================================
   lib/dayBuffer.ts — **하루를 텍스트 한 장으로**(N-15 · W7 · 발산 6회차).

   ## 무엇이 없었나

   이 앱은 하루를 **여섯 표면**으로 말한다(히어로 · 흐름 · 막대 · 스트립 · 레일 · 리드아웃).
   각각은 그 자리에서 옳지만, "오늘 전체를 한 번에 훑는다"는 동작이 없다 — 그래서 사용자는
   그 훑기를 **머릿속에서**(또는 볼트에 손으로) 한다. 텍스트 한 장은 그 훑기를 앱 안으로 들인다.

   ## ⚠⚠ **읽기 전용이다 — 파서를 만들지 않는다**

   로드맵이 적은 가장 싼 검증이 정확히 그것이다: _"파서 **없이** 읽기 전용 렌더 → 사흘 '고치고
   싶었나' O/X"_. 편집을 먼저 만들면 텍스트↔상태 왕복 파서가 필요하고(그건 이 앱에서 가장 비싼
   부류의 배관이다), **그 비용을 치른 뒤에야** 사람들이 실제로 고치려 드는지 알게 된다.
   → 순서를 뒤집는다: 먼저 보여 주고, *고치고 싶었나*를 관측한 뒤에 파서를 판단한다.
   ⚠ **폐기 조건**: 사흘 동안 "고치고 싶었다"가 0이면 편집은 안 만든다(그리고 이 화면은 그대로
     남는다 — 훑기 자체가 값이라면 읽기 전용으로 충분하다).

   ⚠ 순수다: 시계·스토어·DOM 을 안 읽는다. 그래야 "무엇이 한 장에 들어가는가"라는 판단 자체가
   유닛으로 잠긴다(이 파일의 유일한 규칙이 그 선택이다).
============================================================ */
import { hLabel, toHM } from './utils';

export interface BufferBlock {
  /** 시작 시각(분). 없으면 시각 미정 — 목록 끝에 모인다. */
  start: number | null;
  min: number;
  done: boolean;
  name: string;
  /** 챕터 등 구체적 대상. 없으면 이름만 적는다. */
  detail?: string;
  /** 학습이 아닌 것(수업·일과) — 체크박스를 안 그린다. */
  routine?: boolean;
}

export interface BufferInput {
  ds: string;
  blocks: readonly BufferBlock[];
  /** 오늘 남긴 3문장 요약들. */
  summaries: readonly string[];
  /** 오늘 남긴 오답 한 줄들. */
  misses: readonly string[];
  /** 하루 판정 한 줄(`dayCapacity.fitLine`). 없으면 안 적는다. */
  fitLine?: string | null;
  /** 어제 남긴 한 줄(있으면 맨 위에 문맥으로). */
  prevNote?: string | null;
}

/** 체크박스 — 마크다운 관용구 그대로다(볼트로 복사해 붙이는 것이 이 형식의 목적). */
const box = (done: boolean): string => (done ? '- [x]' : '- [ ]');

/**
 * 하루 → 한 장의 텍스트.
 *
 * ⚠ **형식이 마크다운인 것이 의도다.** 이 앱의 볼트가 마크다운이고, 복사해 붙이는 것이 이
 * 화면의 첫 용도이기 때문이다(편집이 없는 동안에도 *가져나갈* 수는 있어야 한다).
 * ⚠ **빈 절은 안 적는다** — 비어 있는 제목은 "여기에 뭔가 있어야 하는데 없다"로 읽히고,
 * 그건 이 앱이 화면 곳곳에서 지켜 온 규율("말할 것이 없으면 안 그린다")과 같다.
 */
export function dayBuffer(i: BufferInput): string {
  const lines: string[] = [`# ${i.ds}`];
  if (i.prevNote?.trim()) lines.push('', `> 어제 — ${i.prevNote.trim()}`);
  if (i.fitLine) lines.push('', i.fitLine);

  const timed = i.blocks.filter((b) => b.start != null).sort((a, b) => a.start! - b.start!);
  const untimed = i.blocks.filter((b) => b.start == null);
  if (timed.length || untimed.length) {
    lines.push('', '## 오늘');
    for (const b of [...timed, ...untimed]) {
      const when = b.start == null ? '시각 미정' : toHM(b.start);
      const what = b.detail ? `${b.name} · ${b.detail}` : b.name;
      /* 일과·수업은 **체크박스를 안 준다** — 내가 완료를 표시하는 대상이 아니라 그냥 일어나는
         일이다. 체크박스를 주면 "안 한 것"처럼 보이고 하루가 실패로 읽힌다. */
      const head = b.routine ? '-' : box(b.done);
      lines.push(`${head} ${when} · ${what} (${hLabel(b.min)})`);
    }
  }
  if (i.summaries.length) {
    lines.push('', '## 남긴 것');
    for (const s of i.summaries) lines.push(`- ${s}`);
  }
  if (i.misses.length) {
    lines.push('', '## 틀린 것');
    for (const m of i.misses) lines.push(`- ${m}`);
  }
  return lines.join('\n');
}

/* ============================================================
   dayCapacity.ts — "오늘 안에 들어가는가"의 단일 판정(W6 · 2026-07-31 · 순수).

   ## 왜 lib 인가
   판정 자체는 E9 가 이미 오늘 탭 **컴포넌트 안에서** 하고 있었다. 옮긴 이유는 계산이 어려워서가
   아니라 **출력이 세 자리로 쪼개져 있었기** 때문이다:
     ① 리드아웃 `남은 가용 3.2h`(30px · 우상단)  ② 종결 캡 `오늘 밖 2개 · 1h`(11px · 레일 하단)
     ③ 링 분모의 조용한 축소
   셋 다 **양(量)만** 말하고 어느 자리도 "들어가는가"라는 **문장**을 말하지 않아, 사용자가 화면
   대각선으로 눈을 잇고 뺄셈(4.5−3.2)을 직접 했다. 판정을 한 함수로 모으면 문장도 한 곳에서 나온다.

   ⚠⚠ **여유가 있으면 여유를 먼저 말한다.** 매일 "N개는 오늘 밖"만 말하면 E9 가 없앤 실패감을
   히어로 크기로 되살린다. 같은 자리에서 **반대 부호**를 말하는 것이 이 모듈의 절반이다.

   ⚠ 새 계수는 0이다 — 입력은 `freeLeftMin`(남은 창)과 블록의 `min`(계획 분)뿐이고 둘 다 이미
   있던 값이다. 일과 블록은 세지 않는다(내가 하는 학습이 아니라 이미 잡힌 시간이다). 완료 블록도
   안 센다 — 이미 쓴 시간은 `freeLeftMin` 에서 빠져 있다(이중 차감 방지).
============================================================ */
import { hLabel } from './utils';

/** 판정 입력 — 오늘의 학습 블록 하나. `start` 가 null 이면 시각이 없어 순서를 못 매기므로 제외된다. */
export interface CapacityBlock {
  key: string;
  start: number | null;
  min: number;
  done: boolean;
  /** 막대 세그먼트 라벨·툴팁용. 판정에는 안 쓴다. */
  name?: string;
  /** 과목색(파생값 · 절대규칙 #3). 판정에는 안 쓴다. */
  color?: string;
}

/**
 * 막대 한 칸(P-7). **시각 순서 그대로**이고, `beyond` 인 것이 곧 남은 창 밖으로 삐져나온 부분이다.
 *
 * ⚠ 부분 절단을 하지 않는다 — 창 경계에 걸친 블록도 통째로 `beyond` 다. `beyondKeys` 와 **같은
 * 규칙**이어야 막대와 레일이 서로 다른 말을 하지 않는다(한 양 = 한 판정). 경계에 걸친 블록을
 * 반만 칠하면 "반은 오늘 안"이라는 없는 개념이 생기고, 스케줄러엔 그런 개념이 없다.
 */
export interface CapacitySegment {
  key: string;
  min: number;
  beyond: boolean;
  name: string;
  color?: string;
}

export interface DayCapacity {
  /** 남은 창을 넘겨 "오늘 밖"으로 접힌 블록 키. */
  beyondKeys: Set<string>;
  /** 그 블록들의 합(분). */
  beyondMin: number;
  /** 아직 안 한 학습 블록의 합(분) — 접힌 것 포함. */
  remainMin: number;
  /** 한 줄 판정. 오늘 할 것이 없으면 null(말할 것이 없으면 안 그린다 — 레일 신호와 같은 규칙).
   *  ⚠ P-7 이후 이 문자열은 **화면 텍스트가 아니라 막대의 `aria-label`** 이다 — 길이로 옮긴 것을
   *  SR 이 못 읽으면 그건 이전(移轉)이 아니라 손실이다. */
  fitLine: string | null;
  /**
   * **Q-2** — 오늘 남은 창에서 남은 계획을 뺀 값(분). 양수=여유 · 음수=초과 · `null`=할 것이 없음.
   *
   * ⚠ 왜 문자열(`fitLine`)이 있는데 숫자를 따로 내는가: 상단 44px 리드아웃은 **값과 단위를
   * 따로** 조판해야 하고(`Readout` 계약), 문자열을 파싱해 되돌리는 코드는 그 순간부터
   * `fitLine` 문구를 못 바꾸게 만든다. 표시 문자열에서 값을 역산하지 않는다.
   */
  slackMin: number | null;
  /** 막대 칸들(시각 순). */
  segments: CapacitySegment[];
  /**
   * 막대의 가로 축척(분) = `max(남은 창, 남은 계획)`.
   *
   * ⚠⚠ **분모가 창이 아니라 둘 중 큰 값인 것이 이 안의 핵심이다.** 창으로 나누면 초과분이
   * 100% 를 넘어 잘리고, 그러면 **넘쳤다는 사실 자체가 안 보인다** — 지금 앱이 `beyondKeys` 를
   * 조용히 필터로 지우던 것과 같은 실패를 그래픽으로 반복하는 셈이다. 0 이면 그릴 것이 없다.
   */
  scaleMin: number;
  /** 남은 창이 축척에서 차지하는 비율(0~1). 이 지점이 곧 "오늘의 끝" 표시다. */
  windowRatio: number;
  /**
   * **A-11** — 실측 배율을 먹였을 때의 여유(분). 배율이 없으면 `null`.
   *
   * ⚠⚠ 배율은 지금까지 **과목 상세에만** 있었다: 보려면 `/items` → 카드 → 상세 = 3화면·2클릭이고,
   * 오늘 화면과 연결이 **0**이었다. 그래서 앱은 "내 추정이 20% 낙관적이다"를 알면서도 아침에
   * 그 사실을 한 번도 말하지 않았다 — A-5 가 그 배율을 *계획 숫자*에 먹였다면 이건 **오늘의
   * 판정 문장**에 먹인다(같은 값이 두 시제에서 각각 쓰인다).
   * ⚠ `slackMin` 을 **덮어쓰지 않는다.** 계획된 여유와 실측 보정 여유는 다른 값이고, 하나로
   *   합치면 "계획이 틀렸다"와 "오늘이 빡빡하다"가 구분되지 않는다.
   */
  calibratedSlackMin: number | null;
}

/* ── 7-I4 **할 일도 하루를 먹는다**(발산 6회차 · 2026-08-07) ─────────────────
   ⚠⚠ `lib/events.ts` 가 자백하고 있었다: *"일정은 tasks 와 달리 **스케줄러 입력**이다"*.
   즉 3시에 2시간 약속이 있으면 가용이 줄지만, **오늘 3시간짜리 과제가 있어도 앱은 "여유
   3.2h" 라고 말한다.** 공학 전공 학기 시간의 큰 몫이 그렇게 모델 밖에 있었고, 그 결과가
   매주 반복되는 "왜 계획대로 안 됐지"다.

   ⚠ **창에서 먼저 뺀다 — 블록으로 넣지 않는다.** 두 이유:
   ① 할 일은 `start` 가 없을 수 있고(트레이·인박스) `dayCapacity` 는 시각 없는 블록을
      정의상 제외한다. 블록으로 넣으면 **시각을 안 적은 과제가 통째로 안 세어진다** — 그게
      정확히 지금 상태다.
   ② 이 값은 *배분 대상*이 아니라 **고정 소모**다(N-1 이 배분 보드에서 예산을 2단으로
      가르는 것과 같은 판단). 막대 세그먼트로 그리면 "옮길 수 있는 것"처럼 보인다.

   ⚠ 이건 N-1(과제 부하)의 **값싼 첫 조각**이다 — 스키마 0 · 스케줄러 계약 0. 주기적 과제
   모델은 W8 이 연다. */

/**
 * @param estimateRatio **A-11** — 실측 배율(`Σactual/Σplanned`). 1.2 면 *내 추정이 20% 낙관적*.
 *   `null`·1 이면 아무것도 더하지 않는다(없는 근거로 문장을 늘리지 않는다).
 */
export function dayCapacity(
  blocks: readonly CapacityBlock[],
  freeLeftMin: number,
  choreMin = 0,
  estimateRatio: number | null = null,
): DayCapacity {
  /* ⚠ 창을 먼저 깎고 그 뒤 계산은 **한 글자도 안 바뀐다** — 판정 규칙을 두 벌로 만들지 않는다.
     ⚠ 0 미만으로 안 내려간다: 음수 창은 "이미 넘었다"를 뜻하는데 그 판정은 `slackMin` 부호가
     이미 하고 있고, 창 자체를 음수로 두면 막대 축척(`scaleMin`)이 뒤집힌다. */
  const chore = Math.max(0, choreMin);
  freeLeftMin = Math.max(0, freeLeftMin - chore);
  const beyondKeys = new Set<string>();
  const segments: CapacitySegment[] = [];
  let beyondMin = 0;
  let remainMin = 0;
  let acc = 0;
  const pending = blocks.filter((b) => b.start != null && !b.done).sort((a, b) => a.start! - b.start!);
  for (const b of pending) {
    const min = b.min || 0;
    remainMin += min;
    acc += min;
    const beyond = acc > freeLeftMin;
    if (beyond) {
      beyondKeys.add(b.key);
      beyondMin += min;
    }
    segments.push({ key: b.key, min, beyond, name: b.name ?? '', color: b.color });
  }
  /* ⚠ 깎였으면 **그 사실을 말한다.** 안 말하면 창이 조용히 줄어 사용자가 "왜 갑자기 여유가
     없지"를 화면 어디서도 못 읽는다 — 이 저장소가 `adherenceFactor` 에서 이미 물린 형태다
     (앱이 용량을 깎으면서 그 사실을 말하지 않던 것 · P-5 가 고쳤다). */
  const head =
    (chore > 0 ? `창 ${hLabel(freeLeftMin)}(할 일 ${hLabel(chore)} 뺀 뒤)` : `창 ${hLabel(freeLeftMin)}`) +
    ` · 남은 계획 ${hLabel(remainMin)}`;
  /* A-11 — 실측 배율을 먹인 남은 계획. ⚠ 배율이 1에 가까우면(±5%) **말하지 않는다**: 그
     구간은 `calibrationLabel` 이 이미 "대체로 맞음"이라 부르는 잡음이고, 아침 문장에 잡음을
     한 조각 더 얹으면 그 문장 전체의 신뢰가 깎인다. */
  const ratio = typeof estimateRatio === 'number' && Number.isFinite(estimateRatio) ? estimateRatio : null;
  const useRatio = ratio != null && Math.abs(ratio - 1) >= 0.05;
  const calibratedSlackMin = pending.length && useRatio ? Math.round(freeLeftMin - remainMin * ratio) : null;
  const calTail =
    calibratedSlackMin == null
      ? ''
      : calibratedSlackMin < 0
        ? ` · 실측대로면 ${hLabel(-calibratedSlackMin)} 모자람`
        : ` · 실측대로면 여유 ${hLabel(calibratedSlackMin)}`;
  const fitLine = !pending.length
    ? null
    : beyondKeys.size
      ? `${head} — ${beyondKeys.size}개는 오늘 밖${calTail}`
      : `${head} — 여유 ${hLabel(Math.max(0, freeLeftMin - remainMin))}${calTail}`;
  const scaleMin = Math.max(freeLeftMin, remainMin);
  return {
    beyondKeys,
    beyondMin,
    remainMin,
    fitLine,
    // `fitLine` 이 null 인 조건과 **같은 조건**으로 null 이다 — 두 값이 갈리면 화면이 "여유 0"과
    // "말할 것 없음"을 같은 픽셀로 그린다.
    slackMin: pending.length ? freeLeftMin - remainMin : null,
    segments,
    calibratedSlackMin,
    scaleMin,
    windowRatio: scaleMin > 0 ? Math.min(1, freeLeftMin / scaleMin) : 0,
  };
}

