   정반대다 — 이 파일을 고치러 온 사람이 그 문장을 믿으면 경고를 지우는 쪽으로 판단한다.

   ## 지금의 계약

   · **셸**: `writeAndVerify` 가 정본을 쓴다. 실패는 `useApp` 이 사용자에게 경고한다(무시 금지).
   · **브라우저(dev·트랙 A)**: SQLite 가 정본이 아니다 → `skipped` 로 즉시 반환하고
     localStorage 경로가 저장을 맡는다(2·3단계와 같은 폴백 규율).
   · **정본인데 연결 실패**(C1 · 2026-07-26): `unavailable` 로 반환한다. 이게 `skipped` 와
     같은 값이던 것이 결함이었다 — 둘 다 "SQL 을 못 돌렸다"지만 전자는 **정상**이고 후자는
     **데이터 유실 직전**이라, 한 값으로 뭉치면 호출부가 폴백도 경고도 못 한다.

   왜 쓰기만 하지 않고 **되읽어** 대조하는가: `stateToRows`/`rowsToState` 왕복은
   `dbRows.test.ts` 가 이미 잠갔다. 남은 미지는 그 사이의 **SQL 층**(타입 강제 변환·NULL 처리)이고,
   그건 실제로 디스크를 왕복해 봐야만 드러난다. 2단계-E 의 `SQLITE_BUSY`·WAL 사고가 정확히
   거기서 나왔다 — 검증을 떼면 그 부류가 다시 조용해진다.
============================================================ */
import { stateToRows, rowsToState } from './rows';
import { readRows, readTouched, touchedKey, writeRows, isDbAvailable, isSqlitePrimary } from './sqlite';
import { pushUndo } from './undoStack';
import type { AppState } from '../types';

/** 대조 결과 — 소비처(개발 콘솔·설정 탭 진단)가 읽는다. */
export interface ParityReport {
  ok: boolean;
  /** 값이 갈린 최상위 슬라이스 이름. ok=true 면 빈 배열. */
  mismatched: string[];
  /** SQL 경로가 **정상적으로** 안 돈 경우(브라우저·dev·트랙 A — SQLite 가 정본이 아니다).
   *  이땐 ok 를 판정하지 않는다. ⚠ "DB 가 죽었다"는 여기가 아니라 `unavailable` 이다. */
  skipped: boolean;
  /** SQLite 가 **정본인데** 연결에 실패했다(C1). `ok:false` 와 함께 온다 —
   *  호출부는 localStorage 폴백 + 지속 배너로 이어야 한다. */
  unavailable: boolean;
  /** 병합 반영 창이라 **쓰지 않고 미뤘다**(C-2). 실패가 아니다 — 호출부는 편집 큐를 **되살리고**
   *  재예약해야 한다. 경고·폴백 대상이 아니므로 `ok:true` 와 함께 온다. */
  deferred?: boolean;
}

let _last: ParityReport = { ok: true, mismatched: [], skipped: true, unavailable: false };

/**
 * 행축 대조로 감당할 접촉 행 상한 — 넘으면 종전 **전량 되읽기**로 떨어진다.
 *
 * 왜 상한이 필요한가: 첫 쓰기(기준선 없음)와 대량 쓰기(가져오기·복구·되돌리기)는 손댄 행이 곧
 * 전체라(2년 근사 상태에서 5,348행), 키를 나열해 읽으면 `IN` 목록이 병적으로 길어지고 전량
 * 읽기보다 비싸진다. 400 은 `WRITE_STAMP_CHUNK` 와 같은 자릿수 — 일반 편집 flush 는 변경 행이
 * 한 자릿수라 여기 근처에도 안 온다(즉 실사용에선 **언제나 행축**이다).
 */
const ROW_VERIFY_MAX = 400;
let _inflight: Promise<unknown> | null = null;

/** 마지막 대조 결과(설정 탭 진단·테스트가 읽는다). */
export function lastParity(): ParityReport {
  return _last;
}

/* ⚠⚠ **병합 반영 진행 플래그(C1 · 2026-07-24 감사)** — `runExclusive` 가 못 닫는 잔여 창을 막는다.
   `runExclusive` 는 병합 *배치 쓰기 도중*의 flush 만 직렬화한다. 그런데 `applyPull`(merge.ts)이
   병합-후 행으로 **diff 기준선을 세우고 반환한 뒤**, 메모리 반영(`useApp.applyMerged`)은 그 사이의
   `await commitPullMark`(체인 밖 IPC) + `syncOnce` 언와인드가 끝난 다음에야 일어난다. 그 창에서
   `useApp` 디바운스 flush 가 발화하면 **낡은 메모리를 병합-후 기준선과 diff** 해서 받아온 행을
   되돌리는 문장을 만들고, 그 되돌림이 LWW 로 서버까지 이겨 다른 기기 편집이 조용히 소실된다.
   기준선-세우기(`applyPull`)와 메모리-반영(`applyMerged`) 사이 동안 flush 를 **미룬다**. */
let _mergeApplyPending = false;

/* ⚠⚠ **우회 검출을 "중첩"이 아니라 "게이트 밖"으로 판정한다(M-2 · 2026-08-06).**

   종전 검출기는 _이미 열린 창을 또 열면_ 보고했다. 그 판정에는 결함이 둘 있었다:

   · **거짓 양성이 상시였다.** H4(2026-08-01)가 pull 을 드레인 루프로 만든 뒤부터 한 동기화가
     `applyPull` 을 **여러 회차** 부르고, 창을 닫는 것은 드레인이 다 끝난 뒤의 `applyMerged`
     /`finally` 다 → **2회차부터 매번** "중첩"이었다. 200행 넘는 pull 마다 텔레메트리가 울렸고,
     상시 우는 검출기는 곧 아무도 안 보는 검출기다.
   · **거짓 음성이 남았다.** 우회 경로가 *혼자* 돌면(동시 병합 없음) 중첩이 성립하지 않아
     **아무것도 보고되지 않는다** — 정작 잡으려던 것이 조용한 경우다.

   막으려는 것은 겹침이 아니라 **게이트(`exclusiveMerge`)를 안 타는 것**이므로, 그것을 직접
   본다: 병합 세션 안에서 창을 여는 것은 몇 번이든 정상이고(드레인), 세션 **밖**에서 여는 것은
   한 번이라도 우회다. 세션을 여닫는 곳은 `store/syncController.ts` 의 `exclusiveMerge` 하나다. */
let _mergeSessions = 0;

/**
 * 병합 세션 안에서 `fn` 을 돌린다 — **`exclusiveMerge` 의 짝**이고 유일한 정상 진입로다.
 *
 * ⚠ 게이트(직렬화) 자체는 store 층이 갖는다(`exclusiveMerge`). 여기 있는 것은 그 게이트를
 * **탔다는 사실**뿐이다 — `lib` 은 zustand 를 모르므로 게이트를 여기로 내릴 수 없고, 반대로
 * 검출기(`beginMergeApply`)는 `lib` 에 있어야 하므로 이 표식이 경계를 잇는다.
 * ⚠ 카운터인 이유: 세션이 중첩될 일은 없지만, 언젠가 생겨도 바깥 세션을 조기에 닫지 않는다
 * (불리언이면 안쪽 `finally` 가 바깥 표식을 지운다 — H8 이 창에서 겪은 그 형태).
 */
export async function withMergeSession<T>(fn: () => Promise<T>): Promise<T> {
  _mergeSessions++;
  try {
    return await fn();
  } finally {
    _mergeSessions--;
  }
}

/**
 * 병합 반영 창 시작 — `applyPull` 이 기준선을 세운 직후(같은 `runExclusive` 안) 켠다.
 *
 * ⚠⚠ **이 플래그는 불리언이라 중첩되지 않는다 — 그리고 중첩이 실제로 났었다(H8 · 2026-07-31).**
 * `runSync` 와 `restoreConflict` 가 둘 다 창을 열고 둘 다 `finally` 에서 무조건 닫는데 겹침
 * 가드를 공유하지 않아, 안쪽 finally 가 바깥 창을 조기에 닫고 그 틈으로 flush 가 통과했다.
 * 처방은 카운터가 아니라 **직렬화**다(`store/syncController.ts` 의 `exclusiveMerge`) — 무조건
 * 닫는 방어망이 C1 의 안전장치라 카운터로 바꾸면 그 방어망이 남의 창을 감산한다.
 *
 * 여기 있는 것은 그 처방의 **집행자**다: 게이트 밖에서 창을 열면 시끄럽게 보고한다(관측 없는
 * 규율은 다음 리팩터에서 조용히 되돌아간다). 판정 기준의 근거는 위 M-2 절.
 */
export function beginMergeApply(): void {
  if (_mergeSessions === 0) {
    /* 삼키지 않는다 — 그러나 던지지도 않는다(병합 도중 예외는 워터마크·기준선 계약을 흔든다).
       관측만 하고 창은 그대로 켠다(안 켜면 flush 가 통과해 받아온 행을 되돌린다 — 더 나쁘다). */
    /* ⚠ 종전엔 텔레메트리로 보고했다 — 그 층이 은퇴했다(I052 · 2026-08-22). 남은 채널은
       콘솔이고, 그건 dev·셸 로그에서만 보인다(폰 브라우저에서는 아무 데도 안 남는다). */
    console.error('[db] 병합 반영 창이 exclusiveMerge 밖에서 열렸다 — 게이트를 우회한 경로가 있다');
  }
  _mergeApplyPending = true;
}

/**
 * 병합 반영 창이 닫힐 때까지 **짧게** 기다린다(H9 · 창 닫기 가드 전용).
 *
 * ⚠ 왜 필요한가: 병합창에서 `flushNow()` 를 부르면 `writeAndVerify` 가 `deferred:true` 로 즉시
 * 반환하고 400ms 타이머를 재예약한다. 그런데 `whenSettled()` 는 그 체인 링크가 이미 resolve 됐으므로
 * **곧바로 통과**하고 창이 파괴된다 — **타이머는 영원히 안 뛴다.** 즉 가드의 존재 이유(비동기 SQL
 * 쓰기가 잘리는 것을 막는다)가 정확히 이 경우에만 무력화돼 있었다.
 *
 * ⚠ 상한을 두는 것이 이 함수의 계약이다. 무한히 기다리면 "인터넷이 죽으면 앱이 안 닫힌다"의
 * 로컬판이 된다 — 바깥 `installCloseGuard` 가 이미 3초 상한을 걸므로 여기는 그보다 짧아야 한다.
 */
export function waitForMergeWindow(timeoutMs = 1200, stepMs = 25): Promise<boolean> {
  if (!_mergeApplyPending) return Promise.resolve(true);
  const deadline = Date.now() + timeoutMs;
  return new Promise<boolean>((resolve) => {
    const tick = (): void => {
      if (!_mergeApplyPending) return resolve(true);
      if (Date.now() >= deadline) return resolve(false);
      setTimeout(tick, stepMs);
    };
    setTimeout(tick, stepMs);
  });
}

/** 병합 반영 창 종료 — `applyMerged`(메모리 반영 완료) + `runSync` finally(방어)가 끈다. */
export function endMergeApply(): void {
  _mergeApplyPending = false;
}

/** flush 가 이 창에서 쓰면 받아온 행을 되돌린다 — `useApp.flush` 가 이 값을 보고 미룬다. */
export function isMergeApplyPending(): boolean {
  return _mergeApplyPending;
}

/** 진행 중인 SQL 쓰기가 끝날 때까지 기다린다(없으면 즉시 resolve).
    창 닫기 가드가 쓴다 — **실측(2026-07-19)**: 디바운스 대기 중 창을 닫으면 비동기 SQL 쓰기가
    통째로 잘린다(트랙 B `2단계-C` 케이스). 동기 localStorage 는 `pagehide` 로 지켜지지만
    `await` 가 걸린 경로는 못 지켜진다. 정본이 SQLite 인 지금 이 대기는 **데이터 보존 계약**이다.

    ## ⚠ 여기서 기다리는 것은 **로컬 디스크뿐이다**(C-1 · 설계서 §5-2)

    클라우드 밀어올리기(`lib/cloud/push.ts`)를 `_inflight` 체인에 **넣지 말 것.** 넣으면 창
    닫기가 네트워크를 기다리게 되어 **인터넷이 죽었을 때 앱이 안 닫힌다** — 1단계에서 다른
    원인으로 이미 겪은 실패 모드다. 성질이 다르기 때문에 경계가 여기 있다:
    · 로컬 쓰기 유실 = **소실**(정본이 여기다) → 기다릴 값이 있다.
    · 원격 전송 유실 = **지연**(워터마크가 안 전진해 다음 시도가 재개한다) → 기다릴 값이 없다.

    타임아웃을 달아 "적당히 기다리기"로 절충하지 않는 이유도 같다 — 그건 느리지만 성공했을
    로컬 쓰기를 버리는 쪽이라, 막으려는 것(유실)을 스스로 저지른다. */
export function whenSettled(): Promise<void> {
  return Promise.resolve(_inflight).then(
    () => undefined,
    () => undefined,
  );
}

/** 최상위 슬라이스별로 갈린 곳을 찾는다 — 통짜 비교는 "다르다"까지만 알려줘 진단이 안 된다. */
function diffSlices(a: AppState, b: AppState): string[] {
  const ra = a as unknown as Record<string, unknown>;
  const rb = b as unknown as Record<string, unknown>;
  const keys = new Set([...Object.keys(ra), ...Object.keys(rb)]);
  const out: string[] = [];
  for (const k of keys) {
    // JSON 문자열 비교 — 키 순서까지 같아야 하는 건 아니지만, 두 경로 모두 같은 매퍼를 타므로
    // 순서도 결정적이다. 다르면 일단 보고하고 사람이 본다(거짓 양성이 침묵보다 낫다).
    if (JSON.stringify(ra[k]) !== JSON.stringify(rb[k])) out.push(k);
  }
  return out.sort();
}

/**
 * 상태를 SQLite 에 쓰고 되읽어 대조한다. **셸에선 이것이 정본 저장이다.**
 * 호출부(`useApp.flush`)를 막지 않지만(그래야 UI 가 안 멈춘다), **실패를 삼키지도 않는다** —
 * `ParityReport.ok` 가 거짓이면 호출부가 사용자에게 경고한다. 옛 이름 `mirrorAndVerify` 의
 * "mirror" 는 부차적 사본을 뜻해 오해를 불렀다(정본을 미러라 부르면 실패를 가볍게 다루게 된다).
 */
export interface WriteOptions {
  /**
   * 이 쓰기의 pre-image 를 **되돌리기 스택에 쌓을 것인가**(기본 참 · 전역 ⌘Z).
   *
   * ⚠ **`loadState` 경로(가져오기·초기화·복구)는 거짓을 준다.** 두 이유가 겹친다:
   * ① 그건 "편집"이 아니라 상태 통째 교체라 되돌리기 단위가 다르고, 사용자 결정대로 그 층은
   *    **`BACKUP_KEY` 스냅샷**이 계속 맡는다. ② 손댄 행이 곧 전체(2년 근사 상태에서 5,348행 ·
   *    166KB)라 한 번에 예산을 통째로 먹고, 그러면 **평범한 편집의 되돌리기가 전부 밀려난다** —
   *    스냅샷이 이미 덮는 사건 하나를 위해 안 덮는 사건 수십 개를 버리는 교환이다.
   */
  undo?: boolean;
}

export function writeAndVerify(state: AppState, opts: WriteOptions = {}): Promise<ParityReport> {
  // 체인으로 이어 붙인다 — 동시 실행하면 두 스냅샷 쓰기가 서로 섞여 마지막 것이 정본이 아닐 수 있다.
  // 그리고 `whenSettled()` 가 기다릴 대상이 하나로 모인다.
  return runExclusive(async () => {
    /* ⚠⚠ **병합창 판정은 반드시 체인 *안*에서 한다(C-2 · 2026-07-30 `/감사 근본`).**

       종전엔 `useApp.flush` 가 체인 **밖에서** `isMergeApplyPending()` 을 보고 통과 여부를
       정했다. 그런데 창을 켜는 `beginMergeApply()` 는 `applyPull` 의 `runExclusive` 콜백
       **마지막 줄**에 있다 — 즉 그 콜백이 도는 동안(데스크톱 plugin-sql 순차 execute 라
       pull 200행이면 수백 ms) 플래그는 **아직 false** 다. 그 창에 flush 가 판정하면:

         ① 가드를 통과한다(플래그 false) → ② `writeAndVerify` 가 체인 **뒤에** 줄을 선다
         → ③ `applyPull` 이 끝나 기준선이 **병합-후**로 세워진다
         → ④ 이제 우리 차례인데 손에 든 것은 **병합-전 메모리**다
         → `diffRowsDetailed(병합-후 기준선, 병합-전 메모리)` = **받아온 행을 되돌리는 upsert
           + 상대 기기가 만든 행의 툼스톤** → 다음 push 가 그걸 서버까지 밀어 **다른 기기
           편집이 영구 소실**된다.

       가드가 막으려던 결과와 **정확히 같다** — 판정 시점만 창 밖이었다. 체인 안으로 옮기면
       ①③ 사이가 원자적이 되어 인터리브 자체가 성립하지 않는다.

       ⚠ H4(2026-07-24)가 병합 *쓰기*를 이 체인에 얹었고, C1 이 *플래그*를 더했다. 남아 있던
         것은 **그 플래그를 어디서 읽는가**였다. 두 수정의 미완이 이 한 줄이다. */
    if (isMergeApplyPending()) {
      /* ⚠ `_last` 를 갈아치우지 않는다 — 미룬 것은 대조 결과가 아니다. 여기서 덮으면 설정 탭
         진단이 "마지막 저장은 skipped" 라고 말하기 시작한다(안 잰 것을 결과로 보고하는 형태). */
      return { ok: true, mismatched: [], skipped: true, unavailable: false, deferred: true };
    }
    return runWrite(state, opts.undo ?? true);
  });
}

/**
 * 임의의 로컬 DB 쓰기를 flush 와 **같은 직렬화 단위**에서 돌린다(H4).
 *
 * 동기화 병합(`cloud/merge.ts` 의 `applyPull`)이 쓰는 동안 useApp 디바운스 flush 가 끼어들면,
 * 아직 기준선이 안 세워진 창에 **낡은 메모리를 더 큰 스탬프로 써서 받아온 행을 되돌릴** 수 있다
 * (그 되돌림이 LWW 로 서버까지 이겨 다른 기기의 편집이 조용히 소실된다). 병합 쓰기를 이 체인에
 * 얹으면 flush 와 병합이 절대 겹치지 않는다.
 *
 * ⚠ 병합은 **로컬 쓰기**라 `whenSettled()`(창 닫기 가드)가 기다려도 §5-2 의 "로컬만 기다린다"를
 * 어기지 않는다 — 원격 push 는 여전히 이 체인 밖이다(`push.ts` 머리주석).
 */
export function runExclusive<T>(fn: () => Promise<T>): Promise<T> {
  const next = Promise.resolve(_inflight)
    .catch(() => undefined)
    .then(fn);
  _inflight = next;
  return next;
}

async function runWrite(state: AppState, captureUndo: boolean): Promise<ParityReport> {
  if (!(await isDbAvailable())) {
    /* ⚠ 여기가 C1 의 자리다. 같은 `null` 이 두 뜻이었다 — 아래 두 갈래로 가른다.
       (`isDbAvailable()` 이 `getDb()` 를 부르며 가용성 플래그를 갱신하므로 순서가 중요하다.) */
    if (!isSqlitePrimary()) {
      _last = { ok: true, mismatched: [], skipped: true, unavailable: false };
      return _last;
    }
    _last = { ok: false, mismatched: ['<DB 연결 불가>'], skipped: false, unavailable: true };
    return _last;
  }
  try {
    const wrote = await writeRows(stateToRows(state));
    if (!wrote.ok) {
      _last = { ok: false, mismatched: ['<쓰기 실패>'], skipped: false, unavailable: false };
      return _last;
    }
    /* ⚠ **성공한 뒤에만 쌓는다**(전역 ⌘Z). 쓰기가 실패했으면 DB 는 pre-image 그대로이거나 부분
       적용이라 "직전"이 무엇인지 모른다 — 그 상태를 되돌릴 수 있다고 말하는 것이 더 나쁘다.
       ⚠ 이 자리가 **캡처의 유일한 지점**이다: 병합 쓰기(`applyPull`)는 `batchDb` 로 가고
       (내 편집이 아니다), 최초 이관(`boot.ts`)은 `writeRows` 를 직접 부른다(기준선이 없어
       `preImages` 가 애초에 빈 배열이다). 즉 여기 없는 경로는 원리적으로 안 쌓인다. */
    if (captureUndo) pushUndo(wrote.preImages, wrote.stamp);
    /* ── 되읽기 대조의 이력(읽는 순서대로) ──────────────────────────────────
       ① 처음엔 **매 flush 전량**이었다. 쓰기는 증분(diff)인데 검증만 O(전체) — 8테이블을 통째로
          읽고(`readRows`) 상태로 되돌린 뒤 양쪽을 stringify 했다. 2년 근사 상태(10,380행/0.67MB)
          에서 순수 JS 10ms + IPC 690KB 를 400ms 마다.
       ② H6(2026-07-26 감사)이 그걸 **표본**(첫 쓰기 + 20회당 1회)으로 바꿨다. 근거: 이 층이 잡는
          것은 스키마·매퍼의 성질이라 한 번 어긋나면 계속 어긋난다 = 표본으로 잡힌다.
       ③ 지금은 **행축**이다(아래). 표본이 옳았던 전제는 "전량이 비싸다"였는데, 손댄 행만 보면
          그 전제 자체가 사라진다.

       ⚠ ②가 남긴 규율은 지금도 유효하다: **안 잰 회차에 `ok:true` 를 새로 쓰지 않는다.** 안 잰
       것을 "일치"라고 보고하면 설정 탭 진단이 거짓말을 한다(감사가 반복해 잡은 부류). 아래
       "바뀐 행 없음" 분기가 직전 결과를 그대로 두는 이유가 그것이다. */
    /* ⚠⚠ **대조를 시간축에서 행축으로 옮겼다(2026-07-29).** 표본 설계의 대가는
       **20회 중 19회가 무검증**이라는 것이었다. 이 층이 잡으려는 것(SQL 층의 타입 강제변환·
       NULL 처리)은 **행의 성질**이므로, 손댄 행만 되읽으면 비용이 O(변경행)으로 떨어지면서
       **매 flush 검증**이 된다 — 더 싸고 탐지력은 오른다. 표본은 "전량이 비싸다"의 우회였지
       목적이 아니었다.

       ⚠ 전량 경로는 **지우지 않고 남긴다.** 첫 쓰기(기준선 없음)와 대량 쓰기(가져오기·복구·
       되돌리기)는 손댄 행이 곧 전체라, 키를 나열해 읽는 것이 오히려 비싸고 `IN` 목록도
       병적으로 길어진다. 그 경계가 `ROW_VERIFY_MAX` 다.

       ⚠ 건너뛰지 않으므로 "안 잰 회차"가 없다 — H6 이 걱정한 "안 잰 것을 일치라고 보고"할
       여지 자체가 사라진다. */
    /* ⚠⚠ **삭제도 대조 대상이다**(H6 · 2026-08-01). 종전엔 `touched`(= upsert 만)로만 판정해서
       삭제만 있는 flush 는 `touched.length === 0` 으로 빠져 **직전 결과를 재사용**했다:
       직전이 `unavailable` 이면 성공한 삭제가 실패로 보고되고, 직전이 `ok` 면 삭제 반영을
       **한 번도 확인하지 않고** "일치"라 말한다 — 이 층이 존재하는 이유의 정반대다.
       (할일·요약·보충 제거가 전부 이 부류다: 지우기만 하는 편집은 흔하다.)
       ⚠ 지운 행은 **없어야** 통과다 — 있으면 SQL 이 안 먹은 것이고, 그건 다음 pull 에서
       삭제가 부활하는 경로다. */
    const probes = [...wrote.touched, ...wrote.removed];
    if (probes.length && probes.length <= ROW_VERIFY_MAX) {
      const back = await readTouched(probes);
      if (!back) {
        _last = { ok: false, mismatched: ['<되읽기 실패>'], skipped: false, unavailable: false };
        return _last;
      }
      const bad = new Set<string>();
      for (const r of wrote.removed) {
        if (back.has(touchedKey(r.table, r.key))) bad.add(r.table);
      }
      for (const t of wrote.touched) {
        const got = back.get(touchedKey(t.table, t.key));
        /* ⚠ 비교는 **문자열로** 한다. SQLite 는 열 친화성에 따라 숫자를 number 로 돌려주는데
           우리가 쓴 값은 string 일 수 있다 — 그 강제변환이야말로 이 층이 잡으려는 것이지만,
           JSON 값이 그대로 왕복하는 한 정상이다. 원시 타입이 갈리는 것 자체는 SQLite 의 정상
           거동이라 `===` 로 보면 전 행이 불일치가 된다(그러면 경고가 소음이 되어 죽는다). */
        if (!got || got.length !== t.vals.length || got.some((v, i) => String(v) !== String(t.vals[i]))) {
          bad.add(t.table);
        }
      }
      const mismatched = [...bad];
      _last = { ok: !mismatched.length, mismatched, skipped: false, unavailable: false };
      if (mismatched.length) console.warn('[db] 쓴 행과 되읽은 행이 다릅니다:', mismatched);
      return _last;
    }
    if (!probes.length) return _last; // 바뀐 행이 없다 = 검증할 것도 없다(직전 결과 유지)
    const back = await readRows();
    if (!back) {
      _last = { ok: false, mismatched: ['<되읽기 실패>'], skipped: false, unavailable: false };
      return _last;
    }
    const mismatched = diffSlices(state, rowsToState(back));
    _last = { ok: !mismatched.length, mismatched, skipped: false, unavailable: false };
    if (mismatched.length) {
      /* ⚠ 셸에선 이 불일치가 **정본이 의도와 다르게 저장됐다**는 뜻이다. 콘솔 경고는 진단용이고,
         사용자에게 알리는 책임은 호출부(`useApp` → `warnSaveFailure`)에 있다 — 여기서 토스트를
         띄우면 같은 사건을 두 층이 각자 알리게 된다. */
      console.warn('[db] 저장한 상태가 되읽은 것과 다릅니다:', mismatched);
    }
    return _last;
  } catch (e) {
    console.error('[db] 저장/대조 중 예외', e);
    _last = { ok: false, mismatched: [`<예외: ${(e as Error).message}>`], skipped: false, unavailable: false };
    return _last;
  }
}

/* ── 쓰기 실패 재시도 백오프(H5 · 순수) ──────────────────────────────────────
   ⚠⚠ **이 정책이 순수 함수로 나와 있는 이유는 "검증할 수 없었기 때문"이다**(2026-08-20 리뷰 M-11).

   종전엔 이 수열이 `store/useApp` 의 `create()` 안 지역 클로저였다(`scheduleRetry`). 밖에서 잡을
   손잡이가 `mutate`/`flushNow` 둘뿐이라 **수열 자체를 단언할 방법이 없었고**, 실측 커버리지가
   그것을 그대로 보여 줬다: `saveFailure.test.ts` 는 브라우저 가지만 보고 `dbUnavailable.test.ts`
   는 배너·임시사본만 단언한 뒤 `sleep(600)` 하고 끝난다. `retryMs`·상한·리셋을 건드리는 테스트는
   **0건**이었다.

   그런데 그 클로저는 자기 주석에 위험을 명시해 뒀다 — *"400ms 고정 재시도는 시간당 9,000회
   전량 쓰기가 된다."* 즉 누가 승수를 되돌리거나 성공 경로의 리셋을 잘못 옮기면 앱이 조용히
   초당 재시도로 떨어지는데, 게이트는 그대로 녹색이다.

   ⚠ 정책만 나온다(타이머·스토어는 그대로 호출부 몫이다) — `lib` 은 zustand 를 모른다. */

/** 편집 → 정본 쓰기까지의 디바운스이자 **백오프의 첫 칸**(ms). */
export const PERSIST_MS = 400;
/** 백오프 상한(ms). 원인이 영구적이어도 재시도는 계속돼야 하되 **초당이 아니라 30초당**이다. */
export const PERSIST_RETRY_MAX_MS = 30_000;

/**
 * 다음 재시도 간격 — `0`(= 아직 실패한 적 없음)에서 시작해 배로 늘고 상한에서 멈춘다.
 * 성공하면 호출부가 `0` 으로 되돌린다(그래야 다음 실패가 다시 첫 칸부터다).
 *
 * 수열: `0 → 400 → 800 → 1600 → … → 30000 → 30000 …`
 */
export function nextRetryMs(cur: number): number {
  return cur ? Math.min(cur * 2, PERSIST_RETRY_MAX_MS) : PERSIST_MS;
}

/* ============================================================
   knowledgeElements.ts — **N-4 지식요소(KC) 축**(순수 · React 무관)

   ## 이 파일이 여는 것: 챕터를 **가로지르는** 약점
   이 앱의 모든 약점 축이 `sid|챕터명` 이라, 3장·5장·7장에서 각각 한 번씩 막히면 **어느
   챕터도 `weakSpots` 임계(2회)에 안 들어오고 앱은 "괜찮다"고 말한다.** 실제로는 세 챕터의
   공통 도구에서 세 번 막힌 것이다 — 단원별로는 다 통과인데 시험에서 무너지는 형태.

   `weakSpots`(챕터 단위)와 **경쟁하지 않는다.** 같은 오답을 두 축으로 볼 뿐이고, 둘이 다른
   답을 내는 것이 정상이다: 챕터 축은 *어디를 다시 볼까*, 요소 축은 *무엇을 훈련할까*.

   ## ⚠⚠ 처방이 다르다는 것이 이 축의 전부다
   챕터 축의 처방은 "그 챕터를 다시 봐라"이고, 이 축의 처방은 **"챕터 3개를 각각 정독하지
   말고 요소 1개를 훈련해라"** 다. 그 차이가 없으면 이 축은 중복이다.

   ## ⚠ 폐기 조건이 붙어 있다
   로드맵 N-4 의 전제는 *"한 요소가 실제로 2개 이상 챕터에 걸친다"* 이고, 안 걸치면
   **요소 = 챕터**라 이 축은 중복이다. 그래서 `crossChapter` 가 이 파일의 판정 함수다 —
   그 목록이 계속 비면 축을 지운다(발산 §1-b 의 폐기 조건을 코드로 옮긴 것).
============================================================ */
import type { AppState, Cbms } from './types';

/** 태그 정규화 — **`trim` 만 한다.** 동의어 통합은 사람이 볼 문제이고, 자동으로 묶으면
 *  묶은 근거가 어디에도 안 남는다(대소문자·띄어쓰기도 그 사람의 표기다). */
export const normKc = (s: string): string => s.trim();

/** 한 기록의 태그들(중복 제거 · 빈 값 제거). */
export function kcOf(e: Pick<Cbms, 'kc'>): string[] {
  const out: string[] = [];
  for (const raw of e.kc || []) {
    const k = normKc(raw);
    if (k && !out.includes(k)) out.push(k);
  }
  return out;
}

export interface KcStat {
  kc: string;
  /** 이 요소로 태그된 오답 수. */
  hits: number;
  /** 그 오답들이 걸친 **서로 다른 챕터** 키(`sid|chapter`). */
  chapters: string[];
  /** 가장 최근 기록일. */
  lastDs: string;
}

/**
 * 요소별 집계 — 걸친 챕터가 많은 순 → 횟수 순.
 *
 * ⚠ 정렬 1순위가 **횟수가 아니라 걸친 챕터 수**인 것이 의도다. 한 챕터에서 5번 막힌 것은
 * 챕터 축이 이미 잡는다(`weakSpots`). 이 축이 유일하게 볼 수 있는 것은 **번짐**이다.
 * ⚠ 미래 기록은 안 센다(시드·시계 어긋남 방어 — 이 저장소 공통 규율).
 */
export function kcStats(state: AppState, todayDs: string): KcStat[] {
  const by = new Map<string, { hits: number; chapters: Set<string>; lastDs: string }>();
  for (const e of state.cbms || []) {
    if (!e.ds || e.ds > todayDs) continue;
    const chapterKey = e.sid && e.chapter ? e.sid + '|' + e.chapter : '';
    for (const kc of kcOf(e)) {
      const g = by.get(kc);
      if (g) {
        g.hits++;
        if (chapterKey) g.chapters.add(chapterKey);
        if (e.ds > g.lastDs) g.lastDs = e.ds;
      } else {
        by.set(kc, { hits: 1, chapters: new Set(chapterKey ? [chapterKey] : []), lastDs: e.ds });
      }
    }
  }
  return [...by.entries()]
    .map(([kc, g]) => ({ kc, hits: g.hits, chapters: [...g.chapters].sort(), lastDs: g.lastDs }))
    .sort((a, b) => b.chapters.length - a.chapters.length || b.hits - a.hits || (a.kc < b.kc ? -1 : 1));
}

/**
 * **챕터를 가로지르는** 요소만 — 이 축의 존재 이유이자 폐기 조건.
 *
 * 2개 이상 챕터에 걸친 요소가 없다면 요소 = 챕터이고, 그러면 이 축은 중복이라 **지워야 한다**
 * (로드맵 N-4 의 검증: *"다른 챕터에서 같은 태그가 2회 이상 나오면 참, 0이면 폐기"*).
 */
export function crossChapter(state: AppState, todayDs: string): KcStat[] {
  return kcStats(state, todayDs).filter((s) => s.chapters.length >= 2);
}

/** 지금까지 쓴 태그 전부(최근 쓴 순) — 입력 자동완성용. 새 분류 체계를 만들지 않는 대신
 *  **이미 쓴 말을 다시 제안**하는 것이 동의어 난립을 막는 유일한 장치다. */
export function knownKc(state: AppState, todayDs: string): string[] {
  return kcStats(state, todayDs)
    .slice()
    .sort((a, b) => (a.lastDs > b.lastDs ? -1 : a.lastDs < b.lastDs ? 1 : a.kc < b.kc ? -1 : 1))
    .map((s) => s.kc);
}

/**
 * 한 칸(`sid|chapter`)의 오답 전부에 요소 태그를 **덧붙인다**(N-4 입구).
 *
 * ⚠ 왜 기록 단위가 아니라 칸 단위인가: 이 축의 검증이 *"기존 오답 30건에 손으로 달아 본다"*
 * 인데, 기록마다 달게 하면 30번을 눌러야 해서 **실험 자체가 안 일어난다**(오답 로그가 항목당
 * 시간에서 죽는다는 것이 `ReviewRun` 이 이미 인용한 근거다). 칸 단위면 한 번에 끝나고,
 * 이 축이 보려는 것(**챕터를 가로지르는 번짐**)은 칸 단위로도 그대로 관측된다 —
 * 다른 칸에 같은 태그가 붙는지가 전부이기 때문이다.
 *
 * ⚠ **덧붙이기다(덮어쓰기 아님)** — 한 오답이 두 도구에 걸칠 수 있고, 기존 태그를 지우는
 * 것은 이 함수의 일이 아니다(떼는 것은 `untagChapter` 가 한다).
 * ⚠ 챕터가 빈 칸(`sid|`)도 태그할 수 있다 — `mistakeArchive` 가 그 기록을 안 버리는 것과
 * 같은 이유다(과목 단위로라도 "여기서 막힌다"는 사실이 남는다).
 */
export function tagChapter(state: AppState, sid: string, chapter: string, kc: string): number {
  const tag = normKc(kc);
  if (!tag) return 0;
  let n = 0;
  for (const e of state.cbms || []) {
    if ((e.sid || '') !== sid || (e.chapter || '').trim() !== chapter) continue;
    const cur = kcOf(e);
    if (cur.includes(tag)) continue;
    e.kc = [...cur, tag];
    n++;
  }
  return n;
}

/** 그 칸에서 태그 하나를 뗀다(잘못 단 것을 되돌리는 유일한 경로). 뗀 기록 수를 돌려준다. */
export function untagChapter(state: AppState, sid: string, chapter: string, kc: string): number {
  const tag = normKc(kc);
  let n = 0;
  for (const e of state.cbms || []) {
    if ((e.sid || '') !== sid || (e.chapter || '').trim() !== chapter) continue;
    const cur = kcOf(e);
    if (!cur.includes(tag)) continue;
    e.kc = cur.filter((k) => k !== tag);
    n++;
  }
  return n;
}

/** 그 칸에 이미 붙어 있는 태그들(표시용 · 정렬 고정). */
export function chapterKc(state: AppState, sid: string, chapter: string): string[] {
  const out = new Set<string>();
  for (const e of state.cbms || []) {
    if ((e.sid || '') !== sid || (e.chapter || '').trim() !== chapter) continue;
    for (const k of kcOf(e)) out.add(k);
  }
  return [...out].sort();
}

/* ============================================================
   mistakes.ts — 오답 아카이브(ID-9) 순수 집계.

   ## 무엇을 세는가 — **CBMS 기록 하나만** 센다

   백지 실패(`blankResults`)를 따로 합치지 않는다. `setBlankResult` 가 **막힘 + (메모 또는 챕터)**
   를 이미 CBMS 'C' 항목으로 자동 연결하기 때문이다 — 둘을 합치면 같은 사건이 두 번 세어진다.
   메모도 챕터도 없는 막힘은 CBMS 가 안 생기는데, 그건 **아카이브할 내용이 없는 기록**이다
   (무엇을 다시 볼지 가리키는 정보가 0). 그래서 여기서 세지 않는 것이 손실이 아니라 정직이다.

   ## 왜 '주간 리뷰'가 아니라 별도 화면인가

   리뷰는 *이번 주 처방*이고 여기는 *전 기간 아카이브*다 — 시제가 다르다. 한 화면에 섞으면
   주간 프레이밍이 흐려진다. 반대로 나브에 독립 탭으로 세우면 두 화면이 서로를 먹는다.
   그래서 같은 호스트(학습 기록)의 **이웃 세그먼트**다(사용자 결정 2026-07-25).

   ⚠ 순수·결정론: 벽시계를 안 본다(정렬 키는 기록의 ds). React·DOM 무관.
============================================================ */
import { CBMS_CODES } from './methodology';
import type { AppState, CbmsCode } from './types';

/** 오답 한 묶음 = (과목, 챕터) 한 칸. 챕터 미기재는 `chapter: ''` 로 모인다. */
export interface MistakeRow {
  /** `${sid}|${chapter}` — weakSpots 와 같은 키 규약(두 화면이 같은 것을 같은 이름으로 부른다). */
  key: string;
  sid: string;
  subject: string;
  chapter: string;
  /** 이 칸의 오답 기록 수. */
  count: number;
  /** '확신했는데 틀림' 횟수 — 가장 위험한 부류(안다고 믿어 복습을 건너뛴다). */
  confident: number;
  /** 등장한 CBMS 유형(빈도 내림차순 · 동률은 CBMS_CODES 순). */
  codes: CbmsCode[];
  /** 최빈 유형 = 이 칸의 '근본원인' 대용. 기록이 있으면 항상 있다. */
  topCode: CbmsCode;
  /** 가장 최근 기록일(YYYY-MM-DD) — 정렬·'마지막으로 틀린 날'. */
  lastDs: string;
  /** 최근 메모(최신순 · 빈 메모 제외). 화면이 잘라 쓴다. */
  notes: { ds: string; text: string }[];
}

export interface MistakeFilter {
  /** 이 과목만(빈 값=전체). */
  sid?: string;
  /** 이 유형만(빈 값=전체). */
  code?: CbmsCode;
}

/**
 * 전 기간 오답을 (과목, 챕터)로 묶어 아카이브 행을 만든다.
 *
 * 정렬은 **횟수 내림차순 → 최근 순 → 이름** 이다. 횟수를 먼저 두는 이유: 이 화면의 질문은
 * "무엇이 반복해서 나를 막는가"이지 "무엇이 최근인가"가 아니다(최근 순은 학습 기록이 이미 준다).
 */
export function mistakeArchive(state: AppState, filter?: MistakeFilter): MistakeRow[] {
  const byKey = new Map<string, MistakeRow & { _codeN: Record<string, number> }>();
  for (const e of state.cbms || []) {
    if (filter?.sid && e.sid !== filter.sid) continue;
    if (filter?.code && e.code !== filter.code) continue;
    const chapter = (e.chapter || '').trim();
    const key = (e.sid || '') + '|' + chapter;
    let row = byKey.get(key);
    if (!row) {
      row = {
        key,
        sid: e.sid || '',
        subject: e.name || '?',
        chapter,
        count: 0,
        confident: 0,
        codes: [],
        topCode: e.code,
        lastDs: '',
        notes: [],
        _codeN: {},
      };
      byKey.set(key, row);
    }
    row.count += 1;
    if (e.conf) row.confident += 1;
    row._codeN[e.code] = (row._codeN[e.code] || 0) + 1;
    // ⚠ 과목명은 **최신 기록 것**을 쓴다 — 과목 이름을 바꾸면 옛 기록엔 옛 이름이 박혀 있어,
    //   먼저 만난 것을 그대로 쓰면 아카이브만 옛 이름으로 남는다. lastDs 갱신과 한 자리에 둔다
    //   (따로 두면 "이미 갱신한 lastDs 와 비교"라는 조용한 버그가 난다).
    if (e.ds >= row.lastDs) {
      row.lastDs = e.ds;
      if (e.name) row.subject = e.name;
    }
    const text = (e.note || '').trim();
    if (text) row.notes.push({ ds: e.ds, text });
  }

  const rows: MistakeRow[] = [];
  for (const r of byKey.values()) {
    // 빈도 내림차순 · 동률은 CBMS_CODES 순(결정론 — Object.keys 순서에 기대지 않는다).
    const codes = CBMS_CODES.filter((c) => r._codeN[c]).sort(
      (a, b) => (r._codeN[b] || 0) - (r._codeN[a] || 0) || CBMS_CODES.indexOf(a) - CBMS_CODES.indexOf(b),
    );
    r.notes.sort((a, b) => (a.ds < b.ds ? 1 : a.ds > b.ds ? -1 : 0));
    const { _codeN, ...row } = r;
    void _codeN;
    rows.push({ ...row, codes, topCode: codes[0] ?? r.topCode });
  }
  return rows.sort(
    (a, b) => b.count - a.count || (a.lastDs < b.lastDs ? 1 : a.lastDs > b.lastDs ? -1 : 0) || (a.key < b.key ? -1 : 1),
  );
}

/* ── P-14 오늘 볼 것 (2026-08-01) ────────────────────────────────────────────
   `mistakeArchive` 는 전 기간 전량을 **상한 없이** 돌려준다. 문제는 도달(클릭 2)이 아니라
   **도착 후**다 — 스무 칸짜리 목록 앞에서 무엇부터 볼지가 다시 사용자의 일이 된다.
   외부 근거: 오답 노트가 다시 안 읽히는 이유는 _"다음에 같은 상황에서 무엇을 할지"_ 가 없어
   읽어도 행동으로 안 이어지기 때문이고, 권고는 전부가 아니라 **매일 1~3분**이다
   (note.com/toge0000 · 확인 2026-08-01).

   ⚠ **회전은 새 계수가 아니다** — 이 저장소는 같은 문제(매일 한 장을 고른다)를 이미 날짜 해시로
     풀어 뒀다(`retrieval.pickRetrieval`·`pickConfidentWrong`). 같은 규칙을 쓰는 것이 규약이고,
     새 규칙을 지어내는 것이 일탈이다.
   ⚠ **정렬을 다시 정하지 않는다** — 창이 도는 대상은 `mistakeArchive` 가 이미 정한 순서
     (횟수 내림차순 → 최근 순)다. 즉 첫날 창은 *가장 자주 막히는 것*에서 시작하고, 날이 가며
     아카이브 전체를 훑는다. 여기서 순위를 새로 매기면 두 화면이 다른 이야기를 한다. */
export const TODAY_PICK_N = 3;

/** 안정 해시(문자열→비음수 정수) — 같은 날 같은 창, 날이 바뀌면 회전. `retrieval.ts` 와 같은 식. */
function hashStr(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (Math.imul(h, 31) + s.charCodeAt(i)) | 0;
  return Math.abs(h);
}

/**
 * 오늘 볼 몇 건 — 정렬 순서 위를 **날짜로 회전하는 창**. 행이 `n` 이하면 그대로 전부.
 *
 * ⚠ 순수·결정론: 벽시계를 안 본다(`todayDs` 를 받는다). 같은 날 여러 번 열어도 같은 창이다.
 */
export function todayMistakes(rows: readonly MistakeRow[], todayDs: string, n = TODAY_PICK_N): MistakeRow[] {
  if (rows.length <= n) return [...rows];
  const start = hashStr(todayDs) % rows.length;
  return Array.from({ length: n }, (_, i) => rows[(start + i) % rows.length]!);
}

/** 아카이브 한눈 집계 — 화면 상단 리드아웃(칸·기록·과신). 행이 없으면 전부 0. */
export function mistakeTotals(rows: MistakeRow[]): { spots: number; records: number; confident: number } {
  let records = 0;
  let confident = 0;
  for (const r of rows) {
    records += r.count;
    confident += r.confident;
  }
  return { spots: rows.length, records, confident };
}

