============================================================ */

export interface CaptureResult {
  title: string; // 토큰 제거 후 남은 텍스트(트림). 절대 비지 않음 — 비면 원본 raw.
  dateISO?: string; // 'YYYY-MM-DD'(로컬), now 기준으로 산출.
  dateLabel?: string; // 확인칩용 사람말 라벨: '내일' · '금요일' · '3월 2일'
  subject?: string; // 제공된 목록과 매칭된 정확한 항목명
  chapter?: string; // '2챕터' · '3장' · 'ch 5' (매칭된 형태 보존)
}

/* 날짜 헬퍼는 utils가 단일 원천 — 이 파일은 한때 iso/addDays/startOfDay/mondayOf 넷을 자체
   재구현했다(주석이 "utils와 동일 규약"이라 자인까지 했다). 같은 lib 계층이라 import에 제약도 없다.
   ⚠ 옛 로컬 addDays는 인자를 자정으로 절삭했지만 utils.addDays는 시각을 보존한다 — 여기 호출부는
   전부 이미 절삭된 base(startOfDay·mondayOf 산출)를 넘기므로 동작은 동일하다. */
import { iso, addDays, mondayOf, startOfDay } from './utils';
import { addBacklog } from './methodology';
import type { AppState } from './types';

/** raw에서 needle(대소문자 무시) 첫 등장을 공백으로 치환 — title 걷어내기용. */
function stripOnce(hay: string, needle: string): string {
  if (!needle) return hay;
  const i = hay.toLowerCase().indexOf(needle.toLowerCase());
  if (i < 0) return hay;
  return hay.slice(0, i) + ' ' + hay.slice(i + needle.length);
}

/* 요일 문자 → JS getDay (일=0..토=6) */
const WEEKDAY_DAYIDX: Record<string, number> = { 일: 0, 월: 1, 화: 2, 수: 3, 목: 4, 금: 5, 토: 6 };
/* 월요일 시작 주 인덱스(월=0..일=6) — '이번주/다음주 X요일' 계산용 */
const WEEK_MON_ORDER = '월화수목금토일';

interface DateHit {
  dateISO: string;
  label: string;
  strip: string;
}

/* ── 날짜 인식의 네 전략 (2026-08-20 리뷰 M-14 원장 축소) ────────────────────────
   ⚠ **동작은 안 바뀐다 — 순서가 곧 우선순위다**: 상대어 → 절대(N월 N일) → N/N → 요일.
   첫 매칭만 채택한다. 종전엔 넷이 한 함수 안에 순서대로 있었고 각자 루프·조건을 품어
   인지복잡도의 전부를 만들었다. 전략끼리는 서로를 모른다 — 각자 *이 표기를 아는가* 만 안다.
   ⚠ 우선순위를 바꾸려면 아래 `DATE_STRATEGIES` 배열 순서를 바꾼다. 그게 유일한 자리다. */
type DateStrategy = (raw: string, base: Date) => DateHit | null;

const relativeDate: DateStrategy = (raw, base) => {
  // ① 상대어: 오늘/내일/모레/글피 + 영어 today/tomorrow
  const rel: Array<[RegExp, number, string]> = [
    [/모레/, 2, '모레'],
    [/글피/, 3, '글피'],
    [/내일/, 1, '내일'],
    [/오늘/, 0, '오늘'],
    [/\btomorrow\b/i, 1, '내일'],
    [/\btoday\b/i, 0, '오늘'],
  ];
  for (const [re, off, label] of rel) {
    const m = raw.match(re);
    if (m) return { dateISO: iso(addDays(base, off)), label, strip: m[0] };
  }
  return null;
};

const absoluteDate: DateStrategy = (raw, base) => {
  // ② 절대 N월 N일 — 올해 기준, 이미 지났으면 내년으로 롤.
  const mAbs = raw.match(/(\d{1,2})\s*월\s*(\d{1,2})\s*일/);
  if (mAbs) {
    const mo = Number(mAbs[1]);
    const dy = Number(mAbs[2]);
    if (mo >= 1 && mo <= 12 && dy >= 1 && dy <= 31) {
      let cand = new Date(base.getFullYear(), mo - 1, dy);
      if (cand.getTime() < base.getTime()) cand = new Date(base.getFullYear() + 1, mo - 1, dy);
      return { dateISO: iso(cand), label: `${mo}월 ${dy}일`, strip: mAbs[0] };
    }
  }
  return null;
};

const slashDate: DateStrategy = (raw, base) => {
  // ③ N/N (슬래시) — 시간 HH:MM(콜론)과 구문이 겹치지 않음.
  const mSlash = raw.match(/(\d{1,2})\/(\d{1,2})/);
  if (mSlash) {
    const mo = Number(mSlash[1]);
    const dy = Number(mSlash[2]);
    if (mo >= 1 && mo <= 12 && dy >= 1 && dy <= 31) {
      let cand = new Date(base.getFullYear(), mo - 1, dy);
      if (cand.getTime() < base.getTime()) cand = new Date(base.getFullYear() + 1, mo - 1, dy);
      return { dateISO: iso(cand), label: `${mo}/${dy}`, strip: mSlash[0] };
    }
  }
  return null;
};

const weekdayDate: DateStrategy = (raw, base) => {
  // ④ 요일 — '이번주/다음주/담주' 접두 + X요일, 또는 X요일, 또는 홀로 선 X요일 문자.
  //    접두+요일(요일 옵션) → 접두없는 요일 → 홀로 선 문자 순으로 시도.
  const weekRes: RegExp[] = [
    /(이번주|다음주|담주)\s*([월화수목금토일])요일/,
    /(이번주|다음주|담주)\s*([월화수목금토일])/,
    /([월화수목금토일])요일/,
    /(?:^|\s)([월화수목금토일])(?=\s|$)/,
  ];
  for (const re of weekRes) {
    const m = raw.match(re);
    if (!m) continue;
    // 접두가 있는 규칙은 m[1]=접두·m[2]=요일, 없는 규칙은 m[1]=요일.
    const hasPrefix = m[1] === '이번주' || m[1] === '다음주' || m[1] === '담주';
    const prefix = hasPrefix ? m[1] : '';
    const ch = hasPrefix ? m[2]! : m[1]!;
    const dayIdx = WEEKDAY_DAYIDX[ch];
    if (dayIdx === undefined) continue;

    let target: Date;
    if (prefix === '이번주') {
      target = addDays(mondayOf(base), WEEK_MON_ORDER.indexOf(ch));
    } else if (prefix === '다음주' || prefix === '담주') {
      target = addDays(mondayOf(base), 7 + WEEK_MON_ORDER.indexOf(ch));
    } else {
      // 홑 요일 → now 이후 '다음 등장'(오늘이 그 요일이면 다음 주).
      let ahead = (dayIdx - base.getDay() + 7) % 7;
      if (ahead === 0) ahead = 7;
      target = addDays(base, ahead);
    }
    const label = (prefix ? `${prefix} ` : '') + `${ch}요일`;
    return { dateISO: iso(target), label, strip: m[0] };
  }
  return null;
};

/** 우선순위 = 이 순서. 첫 매칭만 채택한다. */
const DATE_STRATEGIES: readonly DateStrategy[] = [relativeDate, absoluteDate, slashDate, weekdayDate];

/** 날짜 인식 — 우선순위는 위 `DATE_STRATEGIES` 가 소유한다. */
function matchDate(raw: string, now: Date): DateHit | null {
  const base = startOfDay(now);
  for (const strategy of DATE_STRATEGIES) {
    const hit = strategy(raw, base);
    if (hit) return hit;
  }
  return null;
}

/** 챕터 인식 — 'N챕터' · 'N장' · 'ch N' · 'chapter N'. 매칭된 형태를 그대로 라벨로. */
function matchChapter(raw: string): { chapter: string; strip: string } | null {
  // 수량자를 상한 있는 형태로 — 무한 `\d+`/`\s*`는 매칭 실패 시 시작위치마다 재스캔해
  // 초선형이 된다(sonarjs/super-linear-regex). 챕터 번호가 4자리를 넘을 일은 없으므로 의미 손실 0.
  let m = raw.match(/\d{1,4}[ \t]{0,4}(?:챕터|장)/);
  if (m) return { chapter: m[0].trim(), strip: m[0] };
  m = raw.match(/(?:chapter|ch)[ \t]{0,4}\d{1,4}/i);
  if (m) return { chapter: m[0].trim(), strip: m[0] };
  return null;
}

/** 과목 매칭 — ① 부분문자열(대소문자 무시) 중 가장 긴 항목명, ② 없으면 토큰 공유 중 가장 긴 항목명. */
function matchSubject(raw: string, subjects: string[]): { subject: string; strip: string } | null {
  const lower = raw.toLowerCase();
  // ① 부분문자열 매칭 — 긴 이름 우선(가장 구체적인 것).
  const subs = subjects.filter((s) => s && lower.includes(s.toLowerCase())).sort((a, b) => b.length - a.length);
  if (subs.length) {
    const subject = subs[0]!;
    const i = lower.indexOf(subject.toLowerCase());
    const strip = raw.slice(i, i + subject.length); // raw 원본 표기 보존
    return { subject, strip };
  }
  // ② 토큰 공유 — raw 토큰과 과목명 토큰이 하나라도 겹치면 후보, 가장 긴 이름 채택.
  const rawTokens = new Set(lower.split(/\s+/).filter(Boolean));
  let best: string | null = null;
  let bestStrip = '';
  for (const s of subjects) {
    if (!s) continue;
    const stoks = s.toLowerCase().split(/\s+/).filter(Boolean);
    const shared = stoks.find((t) => rawTokens.has(t));
    if (shared && (best === null || s.length > best.length)) {
      best = s;
      const i = lower.indexOf(shared);
      bestStrip = i >= 0 ? raw.slice(i, i + shared.length) : shared;
    }
  }
  if (best) return { subject: best, strip: bestStrip };
  return null;
}

/**
 * 자연어 한 줄 → 구조화된 캡처 의도.
 * @param raw      사용자가 친 원문
 * @param now      기준시각(주입) — 상대날짜 계산의 결정성 확보
 * @param subjects 알려진 항목명 목록(과목 매칭용, 선택)
 * @returns raw가 공백이면 null, 그 외엔 항상 CaptureResult(최소 title).
 */
export function parseCapture(raw: string, now: Date, subjects?: string[]): CaptureResult | null {
  if (!raw || !raw.trim()) return null;

  const result: CaptureResult = { title: '' };
  const strips: string[] = [];

  try {
    // 날짜
    const d = matchDate(raw, now);
    if (d) {
      result.dateISO = d.dateISO;
      result.dateLabel = d.label;
      strips.push(d.strip);
    }

    // 챕터
    const c = matchChapter(raw);
    if (c) {
      result.chapter = c.chapter;
      strips.push(c.strip);
    }

    // 과목
    if (subjects && subjects.length) {
      const sub = matchSubject(raw, subjects);
      if (sub) {
        result.subject = sub.subject;
        strips.push(sub.strip);
      }
    }
  } catch {
    // 견고성: 어떤 단계든 예외는 삼키고 최소 title만 반환.
  }

  // title — 매칭 substring을 긴 것부터 걷어내고 공백 정리. 비면 raw로 폴백.
  let title = raw;
  for (const st of strips.slice().sort((a, b) => b.length - a.length)) {
    title = stripOnce(title, st);
  }
  title = title.replace(/\s+/g, ' ').trim();
  result.title = title || raw.trim();

  return result;
}

/**
 * 여러 줄 → 다건 캡처(I-11). 각 줄을 parseCapture로 독립 파싱, 빈 줄·파싱 실패는 조용히 제외.
 * 배치 프리필(usePrefill.requestBatch)의 입력. now 주입으로 결정적.
 */
export function parseCaptureBatch(raw: string, now: Date, subjects?: string[]): CaptureResult[] {
  return (raw || '')
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean)
    .map((l) => parseCapture(l, now, subjects))
    .filter((x): x is CaptureResult => x !== null);
}

/* ── 캡처 → 보충 레코드(E2·E14 · 2026-07-29) ─────────────────────────────
   데스크톱 ⌘Enter 와 폰 캡처 바가 **같은 규칙**으로 같은 곳에 착지해야 한다(§9-4 — 화면은
   따로, 규칙은 lib). 두 화면이 각자 조립하면 어느 기기에서 담았느냐에 따라 레코드 모양이
   달라지고, 그 차이는 목록에서만 뒤늦게 보인다. */
export interface CaptureRecord {
  /** 매칭된 과목 id — 못 찾으면 ''(보충 스키마가 허용한다). */
  sid: string;
  /** 매칭된 과목명 — 못 찾으면 ''. */
  name: string;
  /** 토큰을 걷어낸 제목. */
  topic: string;
  /** 원문 — `topic` 이 이미 원문이면 ''(같은 글자를 두 칸에 넣지 않는다). */
  note: string;
}

/**
 * 파싱 결과 + 원문 → 보충 레코드 필드. 빈 입력이면 null.
 *
 * ⚠ **원문은 어느 칸에든 반드시 온전히 남는다.** 토큰을 전부 뽑았을 때 `parseCapture` 는
 * `title` 을 원문으로 폴백하므로(그 계약이 여기 전제다) `topic` 이 원문을 들고 `note` 는 빈다.
 * 일부만 뽑았으면 `topic` 은 남은 조각이라 `note` 가 원문을 든다. 어느 쪽이든 사용자가 친
 * 글자가 사라지는 경우는 없다 — 그것이 이 함수의 유일한 불변식이다.
 */
export function captureRecord(
  cap: CaptureResult | null,
  raw: string,
  subjects: readonly { id: string; name: string }[],
): CaptureRecord | null {
  const text = (raw || '').trim();
  if (!text) return null;
  const name = cap?.subject ?? '';
  const sid = name ? (subjects.find((i) => i.name === name)?.id ?? '') : '';
  const topic = (cap?.title || text).trim() || text;
  return { sid, name, topic, note: topic === text ? '' : text };
}

/**
 * 캡처 한 줄을 **보충 백로그에 담기까지** — 파싱·레코드 조립·저장을 한 함수로.
 *
 * ## 왜 이게 여기 있나 (G7 → H22 · 2026-08-01)
 *
 * 캡처 입구가 셋이다: ⌘K 팔레트 · 미니 HUD · 폰 캡처 바. `MiniHud` 는 오랫동안 자기 주석에
 * *"폰 캡처 바와 같은 함수"* 라 적고 있었는데 **사실이 아니었다**(G7 이 잡았다) — 폰은 레이어
 * 규약상 `@/shell` 을 못 물어 커밋 사슬을 **따로 갖고** 있었고, 공유되는 것은 레코드 조립까지였다.
 * 즉 세 입구 중 둘만 같은 함수였다. 캡처는 "떠올랐을 때 한 줄"을 받는 기능이라 결말이 갈리면
 * 그게 곧 조용한 데이터 손실이다(D-2·W8 이 같은 부류에 물렸다).
 *
 * ⚠ **경계 정책을 바꿀 일이 아니었다.** H22 는 이 수렴을 `hooks → shell/toast` 개방에 묶어
 * 뒀는데, 갈려 있던 것은 *데이터 경로*이고 그건 순수 lib 이다. 토스트를 쓸 자리가 없어서가
 * 아니라 **공통부가 lib 으로 안 내려와 있어서** 갈렸다.
 *
 * ⚠ **표시는 여기 없다** — 데스크톱은 되돌리기 토스트, 폰은 6초 인라인 확인 줄이다. 그 차이는
 * 드리프트가 아니라 표면의 차이다(폰엔 토스트 자리가 없다). 되돌리기용 `id` 만 돌려준다.
 */
export function fileCapture(state: AppState, raw: string, now: Date): { id: string; rec: CaptureRecord } | null {
  const items = state.items;
  const rec = captureRecord(
    parseCapture(
      raw,
      now,
      items.map((i) => i.name),
    ),
    raw,
    items,
  );
  if (!rec) return null;
  /* I042 — 캡처는 **판정 전**으로 들어온다(마지막 인자). 세 입구가 전부 이 함수를 지나므로
     그 사실이 한 곳에서 정해진다 — 입구마다 정하면 하나가 반드시 빠진다(G7 이 물린 형태). */
  return { id: addBacklog(state, rec.sid, rec.name, rec.topic, rec.note, false), rec };
}

/* ============================================================
   records.ts — 개인 기록·시즌 페이스·연속성(I-6/7/13) — 순수·무의존(서버 불필요).
   completions/rituals를 1회 순회해 '성취를 회수'하는 신호를 만든다. 처방(review)과 톤 분리:
   여기는 격려·리듬·연속성. 앱의 '오늘'(todayISO)을 주입받아 결정적으로 계산한다.
============================================================ */
import { addDays, dayDiff, iso, mondayOf, parseISO, todayISO } from './utils';
import { completionMin } from './persistence';
import type { AppState } from './types';

/** 하루별 완료 학습 분(done 세션의 min 합). 완료 없는 날은 키 없음. */
function dailyFocusMin(state: AppState): Record<string, number> {
  const comp = state.completions || {};
  const out: Record<string, number> = {};
  for (const ds of Object.keys(comp)) {
    let min = 0;
    let any = false;
    for (const k of Object.keys(comp[ds] || {})) {
      const e = comp[ds]![k];
      if (e?.done) {
        any = true;
        min += completionMin(e);
      }
    }
    if (any) out[ds] = min;
  }
  return out;
}

export interface PersonalBests {
  longestStreak: number; // 최장 연속 학습일
  currentStreak: number; // 오늘(또는 어제)까지 이어지는 현재 연속
  bestFocusMin: number; // 하루 최다 학습 분
  bestFocusDs: string; // 그 날('' = 기록 없음)
  mostSessionsWeek: number; // 한 주 최다 완료 세션
  totalDays: number; // 학습한 날 총수
}

/** 개인 기록(I-6) — completions 1회 순회로 최장/현재 연속·최고 집중일·주 최다 세션. 기록 없으면 전부 0. */
export function personalBests(state: AppState): PersonalBests {
  const dayMin = dailyFocusMin(state);
  const days = Object.keys(dayMin).sort();

  // 최장 연속: 인접일(dayDiff===1) 이어붙이기.
  let longest = 0;
  let run = 0;
  let prev = '';
  for (const ds of days) {
    run = prev && dayDiff(prev, ds) === 1 ? run + 1 : 1;
    if (run > longest) longest = run;
    prev = ds;
  }

  // 현재 연속: 오늘 있으면 오늘, 없고 어제 있으면 어제부터 역방향(오늘 아직 안 했어도 어제까지 인정).
  const set = new Set(days);
  const today = todayISO(state);
  const yest = iso(addDays(parseISO(today), -1));
  let cursor = set.has(today) ? today : set.has(yest) ? yest : '';
  let cur = 0;
  while (cursor && set.has(cursor)) {
    cur++;
    cursor = iso(addDays(parseISO(cursor), -1));
  }

  // 최고 집중일.
  let bestFocusMin = 0;
  let bestFocusDs = '';
  for (const ds of days) {
    if (dayMin[ds]! > bestFocusMin) {
      bestFocusMin = dayMin[ds]!;
      bestFocusDs = ds;
    }
  }

  // 주별 완료 세션(월요일 시작).
  const comp = state.completions || {};
  const weekDone: Record<string, number> = {};
  for (const ds of Object.keys(comp)) {
    const wk = iso(mondayOf(parseISO(ds)));
    for (const k of Object.keys(comp[ds] || {})) if (comp[ds]![k]?.done) weekDone[wk] = (weekDone[wk] || 0) + 1;
  }
  const mostSessionsWeek = Object.values(weekDone).reduce((m, n) => Math.max(m, n), 0);

  return {
    longestStreak: longest,
    currentStreak: cur,
    bestFocusMin,
    bestFocusDs,
    mostSessionsWeek,
    totalDays: days.length,
  };
}

export interface SeasonPace {
  thisWeekMin: number; // 이번 주 완료 학습 분
  avgWeekMin: number; // 직전 baselineWeeks주 평균(이번주 제외)
  ahead: boolean; // 이번 주가 평균 이상인가(리듬 유지/초과)
  deltaPct: number; // (this-avg)/avg*100 반올림, avg 0이면 0
  weeks: { weekMon: string; min: number }[]; // 오래된→최신(이번주 포함) 스파크/서사용
}

/** 시즌 페이스(I-7) — '완료율'이 아니라 '리듬': 이번 주 학습량 vs 직전 몇 주 평균.
   시간 대비 앞섰나/뒤졌나를 서사화. baselineWeeks주 이력이 없으면 있는 만큼으로 평균. */
export function seasonPace(state: AppState, baselineWeeks = 4): SeasonPace {
  const mon0 = mondayOf(parseISO(todayISO(state)));
  const dayMin = dailyFocusMin(state);
  const weekMin = (mon: Date): number => {
    const from = iso(mon);
    const to = iso(addDays(mon, 6));
    let sum = 0;
    for (const ds of Object.keys(dayMin)) if (ds >= from && ds <= to) sum += dayMin[ds]!;
    return sum;
  };

  const weeks: { weekMon: string; min: number }[] = [];
  for (let i = baselineWeeks; i >= 0; i--) {
    const mon = addDays(mon0, -7 * i);
    weeks.push({ weekMon: iso(mon), min: weekMin(mon) });
  }
  const thisWeekMin = weeks[weeks.length - 1]!.min;
  const prior = weeks.slice(0, -1);
  const avgWeekMin = prior.length ? Math.round(prior.reduce((t, w) => t + w.min, 0) / prior.length) : 0;
  const deltaPct = avgWeekMin ? Math.round(((thisWeekMin - avgWeekMin) / avgWeekMin) * 100) : 0;
  return { thisWeekMin, avgWeekMin, ahead: thisWeekMin >= avgWeekMin, deltaPct, weeks };
}

export interface RitualChain {
  streak: number; // 오늘부터 역방향 연속 셧다운 일수
  days: { ds: string; done: boolean }[]; // 오래된→최신(마지막=오늘) 연속성 도트용
}

/** 셧다운 체인(I-13) — 최근 back일의 저녁 셧다운 의식 완료 도트 + 현재 연속(오늘부터 역방향).
   "Don't break the chain" — rituals[ds].shutdown 저활용 데이터를 연속성 신호로 부활. */
export function shutdownChain(state: AppState, back = 14): RitualChain {
  const today = parseISO(todayISO(state));
  const rituals = state.rituals || {};
  const days: { ds: string; done: boolean }[] = [];
  for (let i = back - 1; i >= 0; i--) {
    const ds = iso(addDays(today, -i));
    days.push({ ds, done: !!rituals[ds]?.shutdown });
  }
  let streak = 0;
  for (let i = days.length - 1; i >= 0; i--) {
    if (days[i]!.done) streak++;
    else break;
  }
  return { streak, days };
}

/* ── On This Day 회고(ID-4) ─────────────────────────────────────────────────
   달력상 '같은 날'(−4주·−1년)의 실기록 한 줄을 회수한다("4주 전 오늘, {과목} — {요약}").
   회상 카드와 선택 기준이 다르다: 회상은 age+해시로 도는데 여기는 **달력 정합**(정확히 −28/−365일)이다.
   실기록이 그날 있을 때만 내보내(0의 벽 방지) · 이력 30일 미만이면 통째로 침묵(신규 사용자엔 과거가 없다). */
export interface OnThisDayEntry {
  ds: string;
  daysAgo: number;
  /** '4주 전 오늘' | '1년 전 오늘' */
  offsetLabel: string;
  sid: string;
  subject: string;
  /** 그날의 실기록 한 줄 — 요약 s1(있으면) 또는 완료 학습 분. */
  detail: string;
}

const ON_THIS_DAY_OFFSETS: readonly { days: number; label: string }[] = [
  { days: 28, label: '4주 전 오늘' },
  { days: 365, label: '1년 전 오늘' },
];
/** 이력 게이트 — 첫 기록이 이 일수 이상 과거라야 회고가 의미 있다(0의 벽 방지). */
export const ON_THIS_DAY_MIN_HISTORY = 30;

/** 가장 오래된 실기록 날짜(completions·summaries 통틀어) — 없으면 ''. */
function earliestRecordDs(state: AppState): string {
  let earliest = '';
  const scan = (ds: string) => {
    if (!earliest || ds < earliest) earliest = ds;
  };
  for (const ds of Object.keys(state.completions || {})) scan(ds);
  for (const ds of Object.keys(state.summaries || {})) scan(ds);
  return earliest;
}

/** 달력상 같은 날(−4주·−1년)의 과거 실기록 한 줄들. 이력 30일 미만이거나 그날 기록이 없으면 빈 배열. */
export function onThisDay(state: AppState, todayDs: string): OnThisDayEntry[] {
  const earliest = earliestRecordDs(state);
  if (!earliest || dayDiff(earliest, todayDs) < ON_THIS_DAY_MIN_HISTORY) return [];
  const out: OnThisDayEntry[] = [];
  for (const off of ON_THIS_DAY_OFFSETS) {
    const ds = iso(addDays(parseISO(todayDs), -off.days));
    // 우선순위 ① 그날 남긴 요약(가장 풍부한 회고) — 첫 항목의 s1 을 한 줄로.
    const sums = state.summaries?.[ds];
    if (sums && sums.length) {
      const s = sums[0]!;
      out.push({
        ds,
        daysAgo: off.days,
        offsetLabel: off.label,
        sid: s.sid,
        subject: s.name || '',
        detail: (s.s1 || '').trim() || '요약을 남겼어요',
      });
      continue;
    }
    // ② 요약이 없으면 완료 학습(실기록)로 폴백. 그마저 없으면 이 오프셋은 침묵(0의 벽).
    const comp = state.completions?.[ds];
    if (comp) {
      let min = 0;
      let any = false;
      for (const k of Object.keys(comp)) {
        const e = comp[k];
        if (e?.done) {
          any = true;
          min += completionMin(e);
        }
      }
      if (any) {
        out.push({
          ds,
          daysAgo: off.days,
          offsetLabel: off.label,
          sid: '',
          subject: '',
          detail: `${Math.round(min)}분 학습했어요`,
        });
      }
    }
  }
  return out;
}

/* ============================================================
   scheduler/dayPlanOverride.ts — 자동 산출 위에 사용자의 수동 배치를 얹는 후처리.
   ⚠ 핵심 불변식: 수동 오버라이드가 없으면 완전 무동작 → 자동 산출이 100% 그대로여야 한다.
============================================================ */
import { REVIEW_OFFSETS, REVIEW_OFFSETS_WEAK, REVIEW_TAIL_OFFSET, clamp, dayDiff, reviewBlockMin } from '../utils';
import { latestBlank } from './priority';
import type { AppState, Day } from '../types';

/** 일일 배치 오버라이드 후처리(§4-2) — mode==='manual'인 날의 day.items를 dayPlans 블록으로 치환.
 *  각 블록에 명시 start를 실어 layoutDay가 그 시각에 배치한다. day.used도 블록 합으로 갱신.
 *  ⚠ 불변식: 수동 오버라이드가 없으면(dayPlans 부재/빈값) 완전 무동작 → 자동 산출 100% 불변.
 *  (§4-3 복습 재씨앗은 별도 — 수동 new 블록의 하류 복습 생성은 후속 패스에서. 자동-only 불변이 전제.) */
export function applyDayPlans(state: AppState, days: Day[]): void {
  const plans = state.dayPlans;
  if (!plans) return; // 무 dayPlans → 무동작(자동 산출 불변)
  for (const d of days) {
    const dp = plans[d.ds];
    if (!dp || dp.mode !== 'manual') continue;
    d.items = dp.blocks.map((b) => ({
      type: b.type,
      sid: b.sid,
      name: b.name,
      color: b.color,
      min: b.min,
      chapters: b.chapters ? b.chapters.slice() : undefined,
      start: b.start, // 명시 배치 시각(있으면) — layoutDay가 존중
    }));
    d.used = d.items.reduce((t, it) => t + it.min, 0);
  }
}

/** §4-3 복습 재씨앗 — applyDayPlans 직후, manual인 날의 new 블록 하류 복습을 보강한다.
 *  ⚠ 불변식: manual인 날이 하나도 없으면 완전 무동작 → 자동 산출 100% 불변(회귀 고정 전제).
 *  이중계상 방지: 대상 날에 그 과목 rev가 이미 그 챕터를 덮으면 skip한다 — 수동이 '자동초안 스냅샷'인
 *  일반 경우엔 자동 패스가 만든 하류 rev가 이미 그 챕터를 덮으므로 실질 무보강(사용자가 새 챕터의
 *  new 블록을 손수 얹었을 때만 그 하류 복습이 새로 생긴다). 대상 날이 manual이면 사용자 소유라 주입 안 함.
 *  reviewViaAnki면 복습은 Anki/FSRS 소유라 생략(자동 패스와 동일 규칙). */
/* ⚠ **복습 한 칸 주입**을 갈라 둔다(2026-08-20 리뷰 M-14 원장 축소). 종전엔 `reseedManualReviews`
   안에 루프 셋이 중첩돼 있었고(날 → 블록 → 오프셋) 가장 안쪽이 다시 조건 넷을 품었다.
   이 함수는 *한 날에 한 복습을 어떻게 얹는가* 만 안다 — 어느 날에 얹을지는 호출부가 정한다. */
function injectReview(
  td: Day,
  src: { sid: string; name: string; color?: string; chapters?: string[] },
  revMin: number,
  plans: NonNullable<AppState['dayPlans']>,
): void {
  if (plans[td.ds]?.mode === 'manual') return; // 사용자 소유 날 — 주입 안 함
  const ex = td.items.find((x) => x.type === 'rev' && x.sid === src.sid);
  const missing = (src.chapters ?? []).filter((c) => !(ex && ex.chapters && ex.chapters.includes(c)));
  if (!missing.length) return; // 이미 하류 rev 가 그 챕터를 덮음 → 이중계상 방지
  if (ex && ex.chapters) {
    missing.forEach((c) => ex.chapters!.push(c)); // 기존 rev 에 챕터만 병합(min 보수적 유지)
    return;
  }
  td.items.push({ type: 'rev', sid: src.sid, name: src.name, color: src.color, min: revMin, chapters: missing });
  td.used += revMin;
}

export function reseedManualReviews(
  state: AppState,
  days: Day[],
  start: string,
  ML: number,
  reviewViaAnki: boolean,
): void {
  const plans = state.dayPlans;
  if (!plans) return;
  if (reviewViaAnki) return;
  if (!days.some((d) => plans[d.ds]?.mode === 'manual')) return; // auto-only → 무동작
  const revMin = reviewBlockMin(ML);
  /* ⚠ 아래 두 조회는 **블록마다** 불린다(manual 인 날 × 그날 new 블록). 종전엔 각각
     `state.items` 선형 탐색과 `blankResults` 전량 스캔이라 그 곱이 그대로 비용이었다
     (2026-08-20 리뷰 M-4 · `engine.ts` 의 `blankBySid` 와 같은 처방). sid 는 과목 수만큼만
     존재하므로 한 번 접어 두면 그 축이 사라진다. */
  const itemById = new Map((state.items || []).map((x) => [x.id, x]));
  const dlIdxOf = (sid: string): number => {
    const it = itemById.get(sid);
    return it?.deadline ? dayDiff(start, it.deadline) : Infinity;
  };
  const blankCache = new Map<string, boolean | null>();
  const blankOf = (sid: string): boolean | null => {
    let v = blankCache.get(sid);
    if (v === undefined) {
      v = latestBlank(state, sid);
      blankCache.set(sid, v);
    }
    return v;
  };
  for (const d of days) {
    if (plans[d.ds]?.mode !== 'manual') continue;
    for (const it of d.items) {
      if (it.type !== 'new' || !it.chapters || !it.chapters.length) continue;
      const anchor = anchorIdx(state, d.ds, it.sid, start, days.length);
      for (const off of offsetsFor(blankOf(it.sid))) {
        const ti = anchor + off;
        if (ti >= days.length || ti > dlIdxOf(it.sid)) continue;
        injectReview(days[ti]!, it, revMin, plans);
      }
    }
  }
}

/** 하류 복습의 앵커 인덱스 — **실제 완료일(`doneDs`) 우선**, 없으면 배치일(자동 패스와 동일 규칙). */
function anchorIdx(state: AppState, ds: string, sid: string, start: string, len: number): number {
  const comp = state.completions?.[ds]?.[sid + '|new'];
  return comp?.done && comp.doneDs ? clamp(dayDiff(start, comp.doneDs), 0, len - 1) : dayDiff(start, ds);
}

/** 백지 성과에 따른 사다리 — 막힘이면 단축, 통과면 꼬리 연장, 기록 없으면 기본(②#23). */
function offsetsFor(blank: boolean | null): readonly number[] {
  if (blank === false) return REVIEW_OFFSETS_WEAK;
  if (blank === true) return [...REVIEW_OFFSETS, REVIEW_TAIL_OFFSET];
  return REVIEW_OFFSETS;
}

/* ============================================================
   scheduler/engine.ts — 통합 스케줄 엔진의 본체 schedule().

   하루 가용시간을 모듈(기본 2h)로 쪼개고, 과목의 '주당 목표 시간'만큼 모듈을 그 주에
   인터리빙·마감 우선으로 분배한다. 챕터 포인터가 전진하고, 복습은 배운 챕터를
   +1·3·7·16일에 생성 — 앵커는 실제 완료일(doneDs · ②#23). 백지복습 최근 실패 과목은
   단축 사다리(1·2·4·8·16)·통과 과목은 +34일 꼬리 1회로 적응. daily(Anki)는 매일 먼저 확보.

   ⚠ 이 파일은 회귀로 동결된 코어다. 동작은 scheduler.test.ts와 100% 동일하게 보존한다.
============================================================ */
import {
  REVIEW_OFFSETS,
  REVIEW_OFFSETS_WEAK,
  REVIEW_TAIL_OFFSET,
  addDays,
  clamp,
  dayDiff,
  iso,
  mondayOf,
  parseISO,
  reviewBlockMin,
  round1,
  todayISO,
} from '../utils';
import { isWeekManaged } from '../weekAlloc';
import { EXAM_LABEL, examScopes, examsOf, scopeIndexFor } from '../semester';
import { dayStudyMin, studyMinByWeekday } from './windows';
import { adherenceFactor, itemTotalHours, latestBlank, masteryNeed, mistakeNeed } from './priority';
import { applyDayPlans, reseedManualReviews } from './dayPlanOverride';
import type { SchedSubject } from './types';
import type { AppState, Day, Item, ItemStat, ScheduleResult, Shortfall } from '../types';

/* ── `schedule()` 의 두 단계 (2026-08-20 리뷰 M-14 원장 축소) ──────────────────────
   ⚠⚠ **이 파일은 회귀로 동결된 코어다**(머리주석). 그래서 여기 옮긴 것은 **문장이 아니라 위치**뿐
   이다 — 조건·순서·반올림 어느 것도 안 바꿨고 `scheduler.test.ts` 가 그것을 잠근다.
   단계 둘을 뺀 이유는 크기가 아니라 **독립성**이다: daily 배치는 weekly 를 모르고, 복습 대상 날
   고르기는 복습 내용을 모른다. */

/** ③ daily(Anki) — 매일 고정 분 확보. 챕터가 없어 구간이 무의미하므로 과목의 **마지막 시험**까지
 *  매일 돈다(시험이 없으면 지평 끝까지). */
function placeDaily(days: Day[], s: Item, start: string, horizon: number): void {
  const dailyEx = examsOf(s);
  const dailyDs = dailyEx.length ? dailyEx[dailyEx.length - 1]!.date : undefined;
  const dlIdx = clamp(dailyDs ? dayDiff(start, dailyDs) : horizon, 0, days.length - 1);
  for (let j = 0; j <= dlIdx; j++) {
    const d = days[j]!;
    if (d.studyMin - d.used <= 0) continue;
    const m = Math.min(+(s.dailyMin || 0), d.studyMin - d.used);
    if (m <= 0) continue;
    d.items.push({ type: 'anki', sid: s.id, name: s.name, min: Math.round(m), color: s.color });
    d.used += m;
  }
}

/** ⑤ 그 주의 **날 인덱스** — 월요일부터 7일 중 지평 안에 드는 것만. 부분주(시작일이 월요일이
 *  아닌 첫 주 · 지평 끝의 잘린 주)에서 배열이 7보다 짧아지는 것이 정상이고, 통째로 비면 호출부가
 *  그 주를 건너뛴다.
 *  ⚠ **스칼라만 받는다** — `days` 배열도 안 보고 길이만 본다. 그래서 이 추출은 이 파일이 경계하는
 *  *"공유 가변 상태를 인자로 흘리는 설계 변경"* 이 아니라 문자 그대로 **위치 이동**이다
 *  (`schedule()` 안에서 이 블록만이 그 성질을 가졌다 — 2026-08-20). */
function weekIndices(start: string, wStart: Date, dayCount: number): number[] {
  const widx: number[] = [];
  for (let k = 0; k < 7; k++) {
    const di = dayDiff(start, iso(addDays(wStart, k)));
    if (di >= 0 && di < dayCount) widx.push(di);
  }
  return widx;
}

/** ⑥ 복습 대상 날 — **세 순위**로 고른다. 못 찾으면 `-1`(= 미배치, 호출부가 센다).
 *  ① 복습예산(`revLeft`)이 남은 첫 날 → ② 그냥 여유가 남은 첫 날 → ③ 여유가 **가장 큰** 날.
 *  ⚠ ③이 있는 이유가 "no silent caps" 다 — 창 안이 전부 빡빡해도 조용히 버리지 않고 가장 덜
 *  빡빡한 날에 넘겨 끼우고, 그 사실을 호출부가 경고로 말한다. */
function pickReviewDay(days: Day[], from: number, min: number): number {
  const end = Math.min(days.length - 1, from + 6);
  for (let j = from; j <= end; j++) if (days[j]!.revLeft >= min) return j;
  for (let j = from; j <= end; j++) if (days[j]!.studyMin - days[j]!.used >= min) return j;
  let best = -1;
  let bestRoom = -1;
  for (let j = from; j <= end; j++) {
    const rm = days[j]!.studyMin - days[j]!.used;
    if (rm > bestRoom) {
      bestRoom = rm;
      best = j;
    }
  }
  return best;
}

export function schedule(state: AppState): ScheduleResult {
  // 시작일 방어 — 사용자가 시작일을 빈 값으로 지우면 parseISO('')=Invalid → dayDiff=NaN →
  // horizon=Math.max(6,NaN)=NaN → 루프가 0회 → days=[]로 전 탭이 빈 화면이 됐다. 오늘로 폴백.
  const start = Number.isNaN(parseISO(state.startDate).getTime()) ? todayISO(state) : state.startDate;
  const items = state.items.filter((s) => s.name);
  const warnings: string[] = [];
  const shortfalls: Shortfall[] = [];
  const capWd = studyMinByWeekday(state);
  const ML = state.moduleLen || 120;
  const revFrac = (state.reviewRatio || 0) / 100;
  const weeklyRaw = items.filter((s) => s.mode !== 'daily' && +(s.weeklyHours || 0) > 0);
  const daily = items.filter((s) => s.mode === 'daily' && +(s.dailyMin || 0) > 0);
  if (!items.length)
    return { days: [], itemStat: [], weekHours: {}, chapterLog: [], warnings, shortfalls, capUsed: 0, capTotal: 0, ML };

  /* 1) 기간(horizon) */
  // T-1. horizon 이 시험을 넘어서야 하므로 **모든 시험 중 가장 늦은 날짜**를 본다. 시험이 승격된
  // 옛 저장에서는 `deadline` 하나뿐이라 종전 값과 같다.
  const lastDL = items.reduce((m, s) => {
    const ex = examsOf(s);
    const d = ex.length ? ex[ex.length - 1]!.date : '';
    return d > m ? d : m;
  }, '');
  let weeksNeed = 8;
  weeklyRaw.forEach((s) => {
    const th = itemTotalHours(s);
    if (th > 0) weeksNeed = Math.max(weeksNeed, Math.ceil(th / Math.max(0.1, +(s.weeklyHours || 0))));
  });
  weeksNeed = Math.min(weeksNeed, 26);
  const endByPace = iso(addDays(mondayOf(parseISO(start)), weeksNeed * 7 + 6));
  const endDate = lastDL && lastDL > endByPace ? lastDL : endByPace;
  const today = todayISO(state);
  // 마감 경로도 상한(18개월) — 먼 미래 마감 하나가 수천 일 배열을 만들어 편집마다 재계산 지연.
  // X-10: 경과한 startDate/짧은·과거 계획(가벼운 콘텐츠·마감없음)이어도 표시창이 오늘을 포함하도록
  //       전방 확장 — 없으면 lastDay가 오늘 이전에서 끝나 복귀 사용자에게 빈 앱이 된다. 세 번째 항이
  //       오늘까지 보장하며(동일 546 상한), 페이스 계산엔 개입하지 않는 표시-only 확장이다.
  // ⚠ 오늘 보장 항에 같은 546 상한을 걸면 보장 자체가 깨진다: startDate가 546일보다 더 과거면
  //   (예: 2024-01-01 시작 + 오늘 2026-07 = 929일) 배열이 오늘 *이전*에서 끝나 오늘 탭이 비고,
  //   그 상태로 편집하면 빈 자동초안이 manual로 승격돼 그날이 영구히 빈 계획이 된다.
  //   → 오늘 항은 별도의 넉넉한 상한(약 5년)을 쓴다. 상한을 아예 없애지 않는 이유는 startDate가
  //     쓰레기 값(1970-01-01 등)일 때 수만 일 배열이 생기는 것만 막기 위해서다.
  const PACE_HORIZON_MAX = 546; // 18개월 — 페이스/마감 경로(편집마다 재계산되므로 짧게)
  const TODAY_HORIZON_MAX = 1826; // 약 5년 — 표시-only 전방 확장의 안전 상한
  const horizon = Math.max(
    6,
    Math.min(dayDiff(start, endDate), PACE_HORIZON_MAX),
    Math.min(dayDiff(start, today), TODAY_HORIZON_MAX),
  );

  /* 2) 일자 생성 + (적응형) 가용 용량 */
  const adapt = adherenceFactor(state, start, horizon, capWd, today);
  const days: Day[] = [];
  /* ⚠ 루프 밖에서 한 번만 판다(2026-08-20 리뷰 n-3) — 종전엔 `addDays(parseISO(start), i)` 로 매 회 같은 문자열을
     다시 파싱했다(`parseISO` 는 split 배열 + map 배열 + Date 를 할당한다). `priority.ts` 의
     H29 주석이 **바로 이웃에서** 같은 결함을 명시하고 이 처방을 적용했는데 이 루프엔 안 왔다. */
  const startDate = parseISO(start);
  for (let i = 0; i <= horizon; i++) {
    const date = addDays(startDate, i);
    const ds = iso(date);
    const wd = date.getDay();
    let sMin = dayStudyMin(state, ds, wd, capWd);
    if (adapt < 1 && ds >= today) sMin = Math.round(sMin * adapt); // 오늘/미래만 축소(과거 원본 유지)
    days.push({ ds, date, wd, studyMin: sMin, used: 0, modLeft: 0, revLeft: 0, items: [] });
  }
  const adaptApplied = adapt < 1;

  /* 3) daily(Anki) 먼저 — 매일 고정 분 확보 */
  daily.forEach((s) => placeDaily(days, s, start, horizon));
  /* 남은 시간 → 학습 모듈 + 복습예산 */
  days.forEach((d) => {
    const rem = Math.max(0, d.studyMin - d.used);
    const learn = Math.round(rem * (1 - revFrac));
    d.modLeft = Math.floor(learn / ML); // 그날 가능한 학습 모듈 수
    d.revLeft = rem - d.modLeft * ML; // 나머지 = 복습예산
  });

  /* 4) 과목 진행 상태 초기화 (챕터 포인터) — done 챕터는 계획에서 제외 */
  const weekly: SchedSubject[] = weeklyRaw.map((it) => {
    const all = it.chapters || [];
    // T-1. 시험 구간(`examScopes`)이 옛 `deadline`+`deadlineThru` 계산을 **집어삼켰다** — 시험이
    // 0~1개면 구간 하나가 `0..scopeEnd` 라 결과가 종전과 동일하다(`lib/semester.ts` 머리주석 §2).
    // 옛 id 를 못 찾으면 전 범위로 폴백하는 P-10 의 판단도 `examScopes` 안으로 옮겨갔다.
    const scopes = examScopes(it);
    // deferred(P-9)는 done 과 같은 자리에서 빠진다 — 블록도 안 만들고 부족분에도 안 센다.
    // 다만 `_allTotal`·`_done0` 은 원본 그대로라 통계가 포기를 진척으로 세지 않는다.
    const chs = all
      .map((c, i) => ({ c, i }))
      .filter(({ c }) => !c.done && !c.deferred)
      .map(({ c, i }) => {
        const segIdx = scopeIndexFor(scopes, i);
        return { id: c.id, name: c.name, hours: Math.max(0.1, +c.hours || 1), inScope: segIdx >= 0, segIdx };
      });
    // 구간별 남은 시간과 누적 끝 — `_cum` 과 직접 비교해 **시험마다** 부족분을 낸다.
    let cum = 0;
    const segs = scopes.map((sc, si) => {
      const hours = chs.reduce((t, c) => t + (c.segIdx === si ? c.hours : 0), 0);
      cum += hours;
      return { exam: sc.exam, dlIdx: clamp(dayDiff(start, sc.exam.date), 0, days.length - 1), hours, cumEndH: cum };
    });
    return {
      ...it,
      _allTotal: all.length,
      _done0: all.filter((c) => c.done).length,
      _hadChapters: all.length > 0,
      _chs: chs,
      _cum: 0,
      _idx: 0,
      _totalH: chs.reduce((t, c) => t + c.hours, 0),
      _scopeH: chs.reduce((t, c) => t + (c.inScope ? c.hours : 0), 0),
      _segs: segs,
      _dlIdx: segs.length ? segs[segs.length - 1]!.dlIdx : horizon,
      _schedMin: 0,
      _sessions: [],
      _carry: 0,
      // Q-3. "약한 과목 먼저"의 근거가 **둘**이 됐다: 지식엔진 숙달도(외부 관측)와 반복 오답
      // (내 기록). 둘을 더해 **정렬 항 하나**로 둔다 — 항을 늘리면 "왜 이 과목이 먼저인가"의
      // 설명이 조합적으로 불어난다. 둘 다 `graphPriority` 한 스위치가 끈다.
      // ⚠ 종전 이 줄은 "(기본 off → 영향 0)"이라 적었는데 **사실과 다르다** — I-6(W7)이 기본을
      //   `true` 로 뒤집었다(`persistence.ts` 의 `defaults()`). 그 오해 때문에 `mistakeNeed` 의
      //   전량 스캔 비용이 검토 밖에 남아 있었다(2026-08-20 리뷰 m-6). 지금은 그쪽에 참조 캐시가
      //   붙어 과목 수와 무관하게 1회만 돈다.
      _masteryNeed: masteryNeed(state, it.name) + mistakeNeed(state, it.id),
      _weekTgt: 0,
      _weekDone: 0,
    };
  });

  /* ⚠ **과목당 한 번만 판다**(2026-08-20 리뷰 M-4). `latestBlank(state, sid)` 는
     `(blankResults, sid)` 의 순수 함수인데 `pushReviewTasks` 가 **new 블록을 놓을 때마다**
     불렀다 — 자동 경로(일자 × modLeft) + 배분 경로(주 × 7 × 과목) + 수동 배치(날 × 블록)라
     호출이 네 자릿수가 되고, 매 호출이 `blankResults` 전량 스캔이었다. sid 는 과목 수만큼만
     존재하므로 여기서 한 번 접어 두면 그 축이 통째로 사라진다. */
  const blankBySid = new Map<string, boolean | null>();
  for (const s of weekly) blankBySid.set(s.id, latestBlank(state, s.id));
  function advance(s: SchedSubject, addMin: number): string[] {
    if (!s._chs.length) return [];
    const addH = addMin / 60;
    const from = s._cum;
    const to = Math.min(s._totalH, s._cum + addH);
    const covered: string[] = [];
    let acc = 0;
    for (let k = 0; k < s._chs.length; k++) {
      const ch = s._chs[k]!;
      const cs = acc;
      const ce = acc + ch.hours;
      if (ce > from + 1e-6 && cs < to - 1e-6) {
        covered.push(ch.name);
        if (to >= ce - 1e-6) s._idx = Math.max(s._idx, k + 1);
      }
      acc = ce;
    }
    s._cum = to;
    return covered;
  }
  function chaptersLeft(s: SchedSubject): boolean {
    if (!s._hadChapters) return true; // 챕터 없는 과목: 무기한 진행
    if (!s._chs.length) return false; // 모든 챕터 완료
    return s._cum < s._totalH - 1e-6;
  }
  /** T-1. **지금 배치하려는 챕터**의 마감 인덱스. 새 챕터 배치·긴급도 정렬이 보는 값이다.
   *  ⚠ 시험이 0~1개면 항상 `s._dlIdx` 와 같다 — 구간이 하나뿐이고 구간 밖은 폴백이 같은 값이라
   *  종전 동작이 **한 글자도 안 바뀐다**(`scheduler.test.ts` 가 잠근 계약).
   *  ⚠ 복습 꼬리(`pushReviewTasks`)는 일부러 이걸 안 쓴다 — 중간고사 범위의 복습은 시험을 지나
   *  기말까지 이어져야 하므로 바깥 울타리(`_dlIdx`)가 맞다. */
  function curDl(s: SchedSubject): number {
    const ch = s._chs[s._idx];
    const seg = ch && ch.segIdx >= 0 ? s._segs[ch.segIdx] : undefined;
    return seg ? seg.dlIdx : s._dlIdx;
  }

  /* 5) 주(週) 단위 학습 모듈 배분 */
  interface ReviewTask {
    idx: number;
    sid: string;
    name: string;
    color?: string;
    chapters: string[];
    min: number;
  }
  const reviewTasks: ReviewTask[] = [];
  const reviewViaAnki = state.reviewViaAnki === true && daily.length > 0;
  const firstMon = mondayOf(parseISO(start));
  // 같은 날 같은 과목의 new는 **한 행**이어야 한다 — 완료 키가 `sid|type`이라 행이 2개면
  // 하나를 체크했을 때 다른 하나도 체크되는 충돌이 난다(rev 병합과 동일 불변식 · T28).
  // 배분(managed) 경로와 자동 분배 경로가 각자 같은 본문을 갖고 있었다 — 한쪽만 고치면 조용히 갈라지는 형태라 합친다.
  const pushNewBlock = (day: Day, s: SchedSubject, mins: number, covered: string[]): void => {
    const exNew = day.items.find((it) => it.type === 'new' && it.sid === s.id);
    if (exNew) {
      exNew.min += mins;
      covered.forEach((c) => {
        if (exNew.chapters && !exNew.chapters.includes(c)) exNew.chapters.push(c);
      });
      return;
    }
    day.items.push({
      type: 'new',
      sid: s.id,
      name: s.name,
      color: s.color,
      min: mins,
      chapters: covered.slice(),
      mod: true,
    });
  };

  // 복습 씨앗(그날 배운 챕터 근거) — 자동·배분 두 경로가 **같은 코드**로 예약해 산출 동형(회귀 안전).
  // reviewViaAnki면 Anki/FSRS 소유라 무동작(자동 경로의 기존 가드와 동일). 앵커=완료일(doneDs)·백지 성과 사다리 보존(②#23).
  const pushReviewTasks = (s: SchedSubject, di: number, covered: string[]): void => {
    if (reviewViaAnki) return;
    const comp = state.completions?.[days[di]!.ds]?.[s.id + '|new'];
    const anchor = comp?.done && comp.doneDs ? clamp(dayDiff(start, comp.doneDs), 0, days.length - 1) : di;
    const blank = blankBySid.get(s.id) ?? null; // 위에서 과목당 1회 계산(M-4)
    const offsets =
      blank === false ? REVIEW_OFFSETS_WEAK : blank === true ? [...REVIEW_OFFSETS, REVIEW_TAIL_OFFSET] : REVIEW_OFFSETS;
    offsets.forEach((off) => {
      const ti = anchor + off;
      if (ti < days.length && ti <= s._dlIdx)
        reviewTasks.push({
          idx: ti,
          sid: s.id,
          name: s.name,
          color: s.color,
          chapters: covered.slice(),
          min: reviewBlockMin(ML),
        });
    });
  };
  for (let w = 0; w * 7 <= horizon + 6; w++) {
    const wStart = addDays(firstMon, w * 7);
    const wk = iso(wStart);
    const widx = weekIndices(start, wStart, days.length);
    if (!widx.length) continue;
    // ── 배분 주도(managed week, §12-4) — 그 주 weekAlloc가 있으면 사용자 요일 벡터로 new 블록을 구동. ──
    // 배분에 없는 sid는 그 주 0. 챕터 소진/마감 초과 셀은 스킵(경고는 보드 소관). 복습은 배치된 covered에서 자동(동일 헬퍼).
    // ⚠ weekAlloc 부재 시 이 분기 자체가 실행 안 됨 → 아래 else(자동)가 종전과 100% 동일(회귀 불변식).
    // managed 판정은 lib/weekAlloc.isWeekManaged 단일 술어 — 빈 주 객체(`weekAlloc[wk]={}`)는 managed가
    // 아니다. 예전엔 `{}`도 truthy라 이 분기가 전 과목 0분으로 돌며 그 주 new 블록을 무음 전멸시켰다.
    const alloc = state.weekAlloc?.[wk];
    if (alloc && isWeekManaged(state, wk)) {
      widx.forEach((di) => {
        const day = days[di]!;
        weekly.forEach((s) => {
          const mins = alloc[s.id]?.[day.wd] || 0;
          if (mins <= 0 || !chaptersLeft(s) || di > curDl(s)) return;
          const covered = advance(s, mins);
          pushNewBlock(day, s, mins, covered);
          s._schedMin += mins;
          s._sessions.push({ di, ds: day.ds, chapters: covered });
          day.used += mins;
          pushReviewTasks(s, di, covered);
        });
      });
      continue; // 이 주는 배분 구동 완료 — 자동 분배 스킵.
    }
    // 과목별 이번 주 목표 모듈 — 분수 모듈을 캐리오버해 과/미배정 방지.
    // SD-4: 시작일이 월요일이 아니면 첫 주(w===0)는 부분주 — 7일치 목표를 짧은 첫 주에 통째로
    //       잡으면 미달충(정수 모듈 유실)되던 것을, 실제 가용 일수 비중(widx.length/7)만큼만
    //       앵커하고 나머지는 _carry로 이월한다. 온전한 주(widx.length===7)는 wkFrac=1로 무변경.
    const wkFrac = w === 0 ? widx.length / 7 : 1;
    weekly.forEach((s) => {
      if (!chaptersLeft(s)) {
        s._weekTgt = 0;
        s._weekDone = 0;
        return;
      }
      const perWeek = ((+(s.weeklyHours || 0) * 60) / ML) * wkFrac;
      const avail = s._carry + perWeek;
      const tgt = Math.floor(avail + 1e-9);
      s._carry = avail - tgt;
      s._weekTgt = tgt;
      s._weekDone = 0;
    });
    // 슬롯 채우기: 날짜순 → 마감 임박 & (그래프) 약한 & 덜 채운 과목
    let lastSid: string | null = null;
    widx.forEach((di) => {
      const day = days[di]!;
      let cap = day.modLeft;
      while (cap > 0) {
        const cand = weekly.filter((s) => s._weekDone < s._weekTgt && chaptersLeft(s) && di <= curDl(s));
        if (!cand.length) break;
        cand.sort((a, b) => {
          const ua = curDl(a) - di;
          const ub = curDl(b) - di; // ① 마감 임박(하드 제약) — T-1 이후 "현재 챕터가 속한 시험"까지
          if (ua !== ub) return ua - ub;
          if (a._masteryNeed !== b._masteryNeed) return b._masteryNeed - a._masteryNeed; // ② 약한 과목
          return a._weekDone / a._weekTgt - b._weekDone / b._weekTgt; // ③ 덜 채운 과목
        });
        const pick = cand.find((s) => s.id !== lastSid) ?? cand[0]!; // 같은 과목 연속 회피
        const covered = advance(pick, ML);
        pushNewBlock(day, pick, ML, covered);
        pick._weekDone++;
        pick._schedMin += ML;
        pick._sessions.push({ di, ds: day.ds, chapters: covered });
        lastSid = pick.id;
        cap--;
        day.used += ML;
        // 복습 예약(그날 배운 챕터 근거) — 배분 경로와 공유하는 pushReviewTasks(reviewViaAnki 가드·완료일 앵커·백지 사다리 내장).
        pushReviewTasks(pick, di, covered);
      }
    });
  }

  /* 6) 복습 배치 — 복습예산 우선, 없으면 모듈 잔여, 그래도 없으면 여유 큰 날. "no silent caps". */
  reviewTasks.sort((a, b) => a.idx - b.idx);
  let revMissed = 0;
  let revOver = 0;
  reviewTasks.forEach((t) => {
    const tg = pickReviewDay(days, t.idx, t.min);
    if (tg < 0) {
      revMissed++;
      return;
    } // 창 안 모든 날 초과 → 미배치
    if (days[tg]!.studyMin - days[tg]!.used < t.min) revOver++; // 여유 없는 날에 넘겨 끼움
    const d = days[tg]!;
    const ex = d.items.find((it) => it.type === 'rev' && it.sid === t.sid);
    if (ex) {
      ex.min += t.min;
      t.chapters.forEach((c) => {
        if (ex.chapters && !ex.chapters.includes(c)) ex.chapters.push(c);
      });
    } else {
      d.items.push({ type: 'rev', sid: t.sid, name: t.name, color: t.color, min: t.min, chapters: t.chapters.slice() });
    }
    d.used += t.min;
    d.revLeft = Math.max(0, d.revLeft - t.min);
  });
  if (revMissed > 0)
    warnings.push(
      `복습 ${revMissed}개가 용량 부족으로 미배치됐어요 — 주당 시간↑·복습비중↑ 또는 가용시간 확보를 검토하세요.`,
    );
  if (revOver > 0)
    warnings.push(
      `복습 ${revOver}개가 여유 없는 날에 끼워졌어요(그날 계획이 가용시간을 초과) — 일부 복습을 줄이거나 날을 비우세요.`,
    );

  /* 6.5) 백지 복습(방법론 9절) — 단원(챕터) 단위로 마지막 학습 직후 여유 날에 1개씩. */
  if (state.blankReviewWeekly === true) {
    const blankMin = Math.max(30, Math.round(ML * 0.4));
    interface BlankTask {
      afterIdx: number;
      sid: string;
      name: string;
      color?: string;
      chapters: string[];
      min: number;
    }
    const blankTasks: BlankTask[] = [];
    weekly.forEach((s) => {
      const lastDiOf: Record<string, number> = {};
      (s._sessions || []).forEach((se) => {
        (se.chapters || []).forEach((c) => {
          lastDiOf[c] = Math.max(lastDiOf[c] == null ? -1 : lastDiOf[c], se.di);
        });
      });
      Object.keys(lastDiOf).forEach((ch) => {
        blankTasks.push({
          afterIdx: lastDiOf[ch]!,
          sid: s.id,
          name: s.name,
          color: s.color,
          chapters: [ch],
          min: blankMin,
        });
      });
    });
    blankTasks.sort((a, b) => a.afterIdx - b.afterIdx);
    blankTasks.forEach((t) => {
      const end = Math.min(days.length - 1, t.afterIdx + 6);
      let tg = -1; // 학습 직후 며칠 내 여유 큰 날 — 뒤에서부터
      for (let j = end; j >= t.afterIdx; j--) {
        if (days[j]!.studyMin - days[j]!.used >= t.min) {
          tg = j;
          break;
        }
      }
      if (tg < 0) return; // 용량 없으면 건너뜀(과적재 방지)
      days[tg]!.items.push({
        type: 'blank',
        sid: t.sid,
        name: t.name,
        color: t.color,
        min: t.min,
        chapters: t.chapters.slice(),
      });
      days[tg]!.used += t.min;
    });
  }

  /* 6.6) 모의시험(방법론 12절) — N주마다 1회, 그 주말 여유 날에 1모듈. */
  const mockN = +state.mockEveryWeeks || 0;
  if (mockN > 0) {
    for (let w = 0; w * 7 <= horizon + 6; w++) {
      if ((w + 1) % mockN !== 0) continue;
      const wStart = addDays(firstMon, w * 7);
      let tg = -1;
      for (let k = 6; k >= 0; k--) {
        const di = dayDiff(start, iso(addDays(wStart, k)));
        if (di < 0 || di >= days.length) continue;
        if (days[di]!.studyMin - days[di]!.used >= ML) {
          tg = di;
          break;
        }
      }
      if (tg < 0) continue;
      const learnedBefore = days.slice(0, tg + 1).some((d) => d.items.some((it) => it.type === 'new'));
      if (!learnedBefore) continue; // 배운 게 있어야 모의시험 의미
      // color 없음 — 모의는 연결된 과목이 없어 팔레트 색이 없다. 색 리터럴을 산출물에 굳히면
      // 인라인 --seg가 뷰의 .mock 토큰(var(--bad))을 덮어 절대규칙 3(색=PALETTE 파생)을 깬다.
      // 표시는 type==='mock' 플래그 → CSS 토큰이 담당(DayPlanner·WeekCalendar 동일 규약).
      days[tg]!.items.push({ type: 'mock', sid: 'mock', name: '모의시험', min: ML, chapters: [] });
      days[tg]!.used += ML;
    }
  }

  /* 6.9) 일일 배치 오버라이드(§4-2) — manual인 날의 items를 사용자 배치로 치환.
     무 dayPlans면 무동작(자동 불변). 이후 통계·주별시간·cap이 최종 items를 반영. */
  applyDayPlans(state, days);
  /* 6.95) 복습 재씨앗(§4-3) — 수동 new 블록의 하류 복습 보강. manual 날 없으면 무동작(자동 불변). */
  reseedManualReviews(state, days, start, ML, reviewViaAnki);

  /* 7) 통계 */
  const itemStat: ItemStat[] = weekly.map((s) => {
    const total = s._allTotal;
    const doneCh = Math.min(s._done0 + s._idx, total);
    let lastIdx = -1;
    for (let j = days.length - 1; j >= 0; j--)
      if (days[j]!.items.some((it) => it.sid === s.id && it.type === 'new')) {
        lastIdx = j;
        break;
      }
    const finishDate = lastIdx >= 0 ? days[lastIdx]!.ds : null;
    const finished = !chaptersLeft(s);
    // T-1. "마감"의 대표값 = **마지막 시험 날짜**. 옛 저장은 시험이 승격된 하나뿐이라 `s.deadline`
    // 과 같은 값이고, 시험을 안 쓰는 과목은 종전대로 undefined 다.
    const lastExamDs = s._segs.length ? s._segs[s._segs.length - 1]!.exam.date : s.deadline;
    /* ⚠⚠ **D-day 는 마지막 시험이 아니라 다가오는 시험이다**(H-2 · 2026-08-06 감사).
       `semester.ts` 의 `nextExamOf` 가 정확히 이 이유로 만들어졌는데(_"중간고사가 코앞인데
       기말까지의 D-60 을 보여주면 그 숫자는 거짓말"_) 화면 다섯이 계속 `deadline` 을 그리고
       있었다 — 새 어휘를 만들고 소비처를 안 옮기면 옛 값이 그대로 산다.
       여기서 함께 내보내 **파생이 한 곳**이 되게 한다(화면마다 `nextExamOf` 를 부르면 그 다섯이
       각자 today 를 구하게 되고, 그건 H-17 이 잡은 자정 넘김 버그의 생산 라인이다). */
    /* ⚠ 기준은 `start`(스케줄 시작일)가 아니라 **`today`** 다 — 시작일은 학기 시작이라 과거일 수
       있고, 그걸로 재면 이미 지난 중간고사가 "다가오는 시험"이 된다. 반대로 시작일이 미래면
       코앞의 시험이 통째로 빠진다(실측: 이 실수로 `/today` 의 마감 스트립이 비었다). */
    const nextExamDs =
      s._segs.find((g) => g.exam.date >= today)?.exam.date ??
      (s.deadline && s.deadline >= today ? s.deadline : undefined);
    const late = finished && finishDate && lastExamDs ? Math.max(0, dayDiff(lastExamDs, finishDate)) : 0;
    // _hadChapters 가드 — 챕터 없는 과목은 chaptersLeft()가 늘 true라 finished가 영영 false다.
    // 그 상태에서 마감만 있으면 경고가 영구히 뜨는 오탐이라 실제 챕터가 있던 과목만 본다.
    // ⚠ 판정 분모가 `_totalH`(전부)에서 `_scopeH`(마감이 덮는 범위)로 바뀌었다 — P-10.
    //   `deadlineThru` 가 없으면 둘이 같으므로 종전 동작과 한 글자도 다르지 않다.
    // ⚠ 그리고 이 자리는 이제 **문자열 경고를 안 만든다** — P-9. 옛 문장의 유일한 처방이
    //   `주당 시간↑` 이었는데 그건 사용자가 할 수 없는 것이라 액션이 0이었다. 대신 부족분과
    //   컷 후보를 구조로 내보내고, 화면이 "무엇을 뺄까"를 묻는다.
    // ⚠⚠ T-1 이후 이 판정은 **시험 구간마다** 돈다. 옛 모델은 과목당 마감 1개라 부족분도 하나였는데,
    //   중간은 벅찬데 기말은 여유로운 상태가 실재하고 그 둘은 처방이 다르다(중간 범위를 컷해도 기말
    //   부족분은 안 줄어든다). 시험이 0~1개면 루프가 1회라 **종전과 결과가 동일**하다.
    let emitted = false;
    if (s._hadChapters) {
      s._segs.forEach((seg, si) => {
        // 이 구간이 덮는 남은 시간 중 실제로 들어간 만큼 — `_cum` 은 챕터 순서대로 쌓이고 구간도
        // 챕터 순서대로 이어지므로, 구간 [cumEndH-hours, cumEndH) 와 `_cum` 의 교집합이 곧 커버다.
        const segStartH = seg.cumEndH - seg.hours;
        const fit = clamp(s._cum - segStartH, 0, seg.hours);
        if (seg.hours <= 1e-6 || fit >= seg.hours - 1e-6) return;
        const inSeg = s._chs.filter((c) => c.segIdx === si);
        // 규칙: **남은 시간 큰 것부터 · 동률이면 뒤 챕터부터.** 화면에도 이 한 줄을 적어 사용자가
        // 뒤집을 수 있게 한다 — 컷 순서를 학습과학으로 정당화하지 않는다(트리아지 문헌과 깊이-넓이
        // 문헌이 정면으로 갈린다). 근거 없이 똑똑한 척하는 순위가 이 축에서 가장 위험하다.
        const candidates = inSeg
          .map((c, i) => ({ c, i }))
          .sort((a, b) => b.c.hours - a.c.hours || b.i - a.i)
          .map(({ c }) => ({ id: c.id, name: c.name, hours: round1(c.hours) }));
        const gapH = seg.hours - fit;
        const suggest: string[] = [];
        let acc = 0;
        for (const c of candidates) {
          if (acc >= gapH - 1e-6) break;
          suggest.push(c.id);
          acc += c.hours;
        }
        emitted = true;
        shortfalls.push({
          sid: s.id,
          name: s.name,
          color: s.color,
          deadline: seg.exam.date,
          examId: seg.exam.id,
          examLabel: EXAM_LABEL[seg.exam.kind],
          needH: round1(seg.hours),
          fitH: round1(fit),
          gapH: round1(gapH),
          // "범위가 좁혀졌나" = 이 구간이 남은 챕터 전부를 덮지는 않는다.
          scoped: inSeg.length < s._chs.length,
          candidates,
          suggest,
        });
      });
    }
    if (!emitted && late > 0) warnings.push(`"${s.name}": 학습 종료(${finishDate})가 마감(${lastExamDs}) 초과.`);
    return {
      id: s.id,
      name: s.name,
      color: s.color,
      weeklyHours: +(s.weeklyHours || 0),
      totalCh: total,
      doneCh,
      totalH: round1(s._totalH),
      schedH: round1(s._schedMin / 60),
      deadline: lastExamDs,
      nextExam: nextExamDs,
      finishDate,
      finished,
      late,
    };
  });
  daily.forEach((s) => {
    const planned = days.filter((d) => d.items.some((it) => it.sid === s.id)).length;
    itemStat.push({
      id: s.id,
      name: s.name,
      color: s.color,
      daily: true,
      dailyMin: +(s.dailyMin || 0),
      days: planned,
      schedH: round1((planned * +(s.dailyMin || 0)) / 60),
    });
  });

  /* 주별 과목 시간 + 챕터 학습 로그 */
  const weekHours: Record<string, Record<string, number>> = {};
  const chapterLog: ScheduleResult['chapterLog'] = [];
  days.forEach((d) => {
    const wk = iso(mondayOf(d.date));
    d.items.forEach((it) => {
      if (it.type === 'anki' || it.type === 'new') {
        weekHours[wk] = weekHours[wk] || {};
        weekHours[wk][it.sid] = (weekHours[wk][it.sid] || 0) + it.min / 60;
      }
      if (it.type === 'new' && it.chapters && it.chapters.length)
        chapterLog.push({ ds: d.ds, date: d.date, name: it.name, color: it.color, chapters: it.chapters });
    });
  });

  let capTotal = 0;
  let capUsed = 0;
  days.forEach((d) => {
    capTotal += d.studyMin;
    capUsed += d.used;
  });
  return {
    days,
    itemStat,
    weekHours,
    chapterLog,
    warnings: [...new Set(warnings)],
    shortfalls,
    capUsed,
    capTotal,
    ML,
    adapt,
    adaptApplied,
    reviewViaAnki,
  };
}

/* ============================================================
   semantic.ts — 로컬 임베딩 시맨틱 레이어(킬러 기능 ②).
   내 학습 자산(챕터·요약·독후감·백로그)을 로컬 Ollama 임베딩(셸 커맨드 /api/embed 프록시)으로
   벡터화해 ① ⌘K 의미 검색("그때 읽은 인플레이션 글") ② 지식맵 과목-간 자동 연결 엣지를 만든다.
   전부 로컬(local-first) — 텍스트는 localhost 밖으로 나가지 않는다.

   구조: 순수 계산(해시·코사인·topK·코퍼스 구성)과 IO(임베딩 fetch·IDB 캐시)를 분리.
   벡터 캐시는 텍스트 해시 키 — 내용이 안 바뀐 항목은 재임베딩하지 않는다(증분).
   Ollama/임베딩 모델이 없으면 조용히 비활성(한 세션 1회만 시도) — 기능은 보강이지 의존이 아니다.
============================================================ */
import { embedTexts } from './api';
import { idbMirror, idbLoad } from './idb';
import type { AppState } from './types';

export type SemKind = 'chapter' | 'summary' | 'backlog' | 'mistake';

export interface SemEntry {
  id: string;
  kind: SemKind;
  /** 팔레트에 보여줄 제목. */
  label: string;
  /** 임베딩 입력 텍스트(짧게 — 서버 캡 3000자). */
  text: string;
  /** 선택 시 이동할 라우트. */
  to: string;
}

export interface SemHit extends SemEntry {
  sim: number;
}

/* ── 순수 계산 ─────────────────────────────────────────────── */

/** djb2 문자열 해시(증분 캐시 키) — 빠르고 충분히 분산. */
export function hashText(s: string): string {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(36);
}

/** 코사인 유사도. 길이 불일치·영벡터는 0. */
export function cosine(a: number[], b: number[]): number {
  if (!a.length || a.length !== b.length) return 0;
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i]! * b[i]!;
    na += a[i]! * a[i]!;
    nb += b[i]! * b[i]!;
  }
  if (na === 0 || nb === 0) return 0;
  return dot / (Math.sqrt(na) * Math.sqrt(nb));
}

/** 질의 벡터에 가장 가까운 상위 k개(minSim 미만은 제외, 유사도 내림차순). */
export function topK(query: number[], entries: { entry: SemEntry; vec: number[] }[], k = 5, minSim = 0.35): SemHit[] {
  return entries
    .map(({ entry, vec }) => ({ ...entry, sim: cosine(query, vec) }))
    .filter((h) => h.sim >= minSim)
    .sort((a, b) => b.sim - a.sim)
    .slice(0, k);
}

/** 앱 상태 → 임베딩 코퍼스. 순수(입력만 사용) — 테스트 가능.
 *  ⚠ 종전엔 독후감(읽을거리 로컬 블롭)이 셋째 축이었다. P10 W4 에서 그 화면이 `survey/` 로 가며
 *  빠졌고, **`reads` 인자도 함께 뺐다** — 항상 `null` 인 인자를 남기면 호출부가 그걸 채울 것을
 *  계속 찾는다(그게 이 저장소가 반복해 만든 '사문 배선'의 형태다). */
export function buildCorpus(state: AppState): SemEntry[] {
  const out: SemEntry[] = [];
  // ① 챕터 — 과목명과 함께(짧은 이름만으론 의미가 빈약).
  for (const it of state.items || []) {
    if (!it.name) continue;
    for (const ch of it.chapters || []) {
      if (!ch.name) continue;
      out.push({
        id: `ch:${it.id}:${ch.id}`,
        kind: 'chapter',
        label: `${it.name} — ${ch.name}`,
        text: `${it.name} ${ch.name}`,
        // 챕터의 집은 지식맵이 아니라 **학습 항목**이다. `/graph` 로 보내면 노드가 어디 있는지
        // 스스로 찾아야 했다 — AN-17 의 `?focus=` 앵커로 그 과목 카드까지 데려다준다
        // (contentSearch 와 같은 목적지 = 두 검색이 같은 것을 찾으면 같은 곳에 착지).
        to: `/subject/${encodeURIComponent(it.id)}`,
      });
    }
  }
  // ② 내가 쓴 3문장 요약(학습 기록, s1~s3) — 가장 밀도 높은 의미 자산.
  const sm = state.summaries || {};
  for (const ds of Object.keys(sm)) {
    for (const s of sm[ds] || []) {
      const text = [s.s1, s.s2, s.s3]
        .map((x) => (x || '').trim())
        .filter(Boolean)
        .join(' ');
      if (!text) continue;
      out.push({
        id: `sum:${ds}:${s.id}`,
        kind: 'summary',
        label: `${ds.slice(5)} 요약 · ${s.name || '무제'}`,
        text: `${s.name || ''} ${text}`.slice(0, 2000),
        to: '/day',
      });
    }
  }
  // ③ 보충 백로그(승격된 소비물 포함 — 소비→학습 루프의 의미 검색).
  for (const bl of state.backlog || []) {
    const topic = (bl.topic || '').trim();
    if (!topic) continue;
    out.push({
      id: `bl:${bl.id}`,
      kind: 'backlog',
      label: `백로그 · ${topic}`,
      text: `${topic} ${bl.note || ''}`.slice(0, 1200),
      to: '/day',
    });
  }
  /* ⑤ 오답 메모 — 의미 검색이 이 코퍼스에서만 빠져 있었다. "적분 치환에서 왜 막혔더라"처럼
     **단어가 안 겹치는** 질의가 정확히 이 자료를 찾아야 하는 부류다(부분문자열 검색이 가장
     못하는 자리 = 의미 검색이 가장 잘하는 자리).
     ⚠ 벡터 캐시 키는 텍스트 해시라 항목이 늘어도 기존 캐시는 무효화되지 않는다. */
  for (const e of state.cbms || []) {
    const note = (e.note || '').trim();
    if (!note) continue;
    out.push({
      id: `cbms:${e.id}`,
      kind: 'mistake',
      label: `오답 · ${e.name || '?'}${e.chapter ? ' ' + e.chapter : ''}`,
      text: `${e.name || ''} ${e.chapter || ''} ${note}`.slice(0, 1200),
      to: `/mistakes?sid=${encodeURIComponent(e.sid)}`,
    });
  }
  return out;
}

/* ── IO — 벡터 캐시(IDB) + 임베딩 ─────────────────────────── */

const IDB_KEY = 'semvec';
const BATCH = 16; // 서버 캡 32의 절반 — 콜드 로드에도 응답이 빠르게 오도록

interface VecCache {
  model: string;
  vecs: Record<string, number[]>; // hashText(text) → vector
}

let _cache: VecCache | null = null;
let _cacheLoaded = false;

async function loadCache(): Promise<VecCache> {
  if (_cache) return _cache;
  if (!_cacheLoaded) {
    _cacheLoaded = true;
    try {
      const raw = await idbLoad(IDB_KEY);
      if (raw) {
        const p = JSON.parse(raw) as VecCache;
        if (p && typeof p === 'object' && p.vecs) _cache = { model: p.model || '', vecs: p.vecs };
      }
    } catch {
      /* 캐시는 보강 — 없으면 새로 */
    }
  }
  if (!_cache) _cache = { model: '', vecs: {} };
  return _cache;
}

function saveCache(): void {
  if (!_cache) return;
  try {
    idbMirror(JSON.stringify(_cache), IDB_KEY);
  } catch {
    /* 비차단 */
  }
}

/** 세션 가용성 — 임베딩 실패(Ollama 꺼짐·모델 미설치) 시 이 세션에선 재시도하지 않는다. */
let _disabled = false;
export function semanticAvailable(): boolean {
  return !_disabled;
}

/** 텍스트 배열 → 벡터 배열(캐시 우선, 미스만 배치 임베딩). 실패 시 null(세션 비활성). */
export async function vectorsFor(texts: string[]): Promise<(number[] | null)[] | null> {
  if (_disabled) return null;
  const cache = await loadCache();
  const hashes = texts.map(hashText);
  let missIdx = hashes.map((h, i) => (cache.vecs[h] ? -1 : i)).filter((i) => i >= 0);
  let modelChecked = false;
  for (let off = 0; off < missIdx.length; off += BATCH) {
    const slice = missIdx.slice(off, off + BATCH);
    try {
      const res = await embedTexts(slice.map((i) => texts[i]!));
      if (!res.ok || !res.vectors) {
        _disabled = true; // 모델 미설치·Ollama 꺼짐 — 이 세션은 조용히 비활성
        return null;
      }
      const model = res.model || '';
      // 모델 변경 선감지(L-11): 임베드 모델이 캐시와 다르면 옛 벡터는 다른 임베딩 공간이라 전부 폐기하고
      // 전 인덱스를 미스로 재산정해 처음부터 다시 임베딩한다. 예전엔 배치 도중 캐시를 비우되 미스만
      // 다시 채워, 이번 호출에서 기캐시(옛 모델) 텍스트가 최종 반환 배열에 spurious null로 남았다.
      if (!modelChecked && cache.model && model && cache.model !== model) {
        cache.vecs = {};
        missIdx = hashes.map((_, i) => i);
        modelChecked = true;
        off = -BATCH; // 다음 반복에서 off=0부터 — 전 인덱스 재임베딩
        continue;
      }
      modelChecked = true;
      cache.model = model || cache.model;
      slice.forEach((i, j) => {
        const v = res.vectors![j];
        if (v) cache.vecs[hashes[i]!] = v;
      });
    } catch {
      _disabled = true;
      return null;
    }
  }
  if (missIdx.length) saveCache();
  return hashes.map((h) => cache.vecs[h] ?? null);
}

/** 코퍼스 전체의 (entry, vec) 짝 — 캐시 증분 임베딩. 실패 시 null. */
export async function indexCorpus(entries: SemEntry[]): Promise<{ entry: SemEntry; vec: number[] }[] | null> {
  if (!entries.length) return [];
  const vecs = await vectorsFor(entries.map((e) => e.text));
  if (!vecs) return null;
  const out: { entry: SemEntry; vec: number[] }[] = [];
  entries.forEach((entry, i) => {
    const vec = vecs[i];
    if (vec) out.push({ entry, vec });
  });
  return out;
}

/* ── 지식맵 자동 연결(챕터 ↔ 챕터, 과목 경계 너머) ─────────────── */

export interface SemEdge {
  /** Graph 잎 노드 id(= chapter.id) 쌍. */
  source: string;
  target: string;
  sim: number;
}

/** 서로 다른 과목의 챕터 벡터 쌍 중 유사도 minSim 이상 상위 maxEdges — 순수(테스트 대상).
    같은 과목 안 챕터는 이미 허브로 이어져 있어 제외한다. */
export function crossChapterEdges(
  chapters: { itemId: string; chapterId: string; vec: number[] }[],
  minSim = 0.62,
  maxEdges = 24,
): SemEdge[] {
  const out: SemEdge[] = [];
  for (let i = 0; i < chapters.length; i++) {
    for (let j = i + 1; j < chapters.length; j++) {
      const a = chapters[i]!;
      const b = chapters[j]!;
      if (a.itemId === b.itemId) continue;
      const sim = cosine(a.vec, b.vec);
      if (sim >= minSim) out.push({ source: a.chapterId, target: b.chapterId, sim });
    }
  }
  return out.sort((a, b) => b.sim - a.sim).slice(0, maxEdges);
}

/* ⚠⚠ **`semanticChapterEdges`(지식맵용 챕터-간 의미 연결)가 여기 있었다 — 유일한 소비처인
   학습 구조도가 삭제됐다**(I044 · 2026-08-22). 챕터 임베딩 자체는 이 파일의 다른 함수가
   여전히 쓴다 — 사라진 것은 «과목을 가로지르는 엣지를 그린다»는 그 화면의 질문이다. */

/** 의미 검색 — 질의를 임베딩해 코퍼스 상위 k. Ollama 불가·코퍼스 빈 경우 []. */
export async function semanticSearch(query: string, state: AppState, k = 5): Promise<SemHit[]> {
  const q = query.trim();
  if (!q || _disabled) return [];
  const corpus = buildCorpus(state);
  if (!corpus.length) return [];
  const indexed = await indexCorpus(corpus);
  if (!indexed || !indexed.length) return [];
  const qv = await vectorsFor([q]);
  if (!qv || !qv[0]) return [];
  return topK(qv[0], indexed, k);
}

/* ============================================================
   spacedReview.ts — 개념(챕터) 레벨 간격반복 위험 — 순수·무의존.
   Anki가 '카드' 레벨을 소유한다면 여기선 '개념(챕터)' 레벨: 내가 실제로 학습/복습/백지한
   (완료된) 세션에서 챕터별 '마지막으로 만진 날'을 뽑아, 망각곡선상 오래 방치된 챕터를 위험으로 표식.

   신호원: 스케줄의 완료 세션(new/rev/blank) + chapters. isDone으로 게이팅 — 계획만 있고 안 한 건 제외.
   이 스캔은 **진행 중** 챕터를 본다(REVIEW_OFFSETS 1·3·7·16 정렬).

   ⚠ 끝낸(done) 챕터는 여기 원리적으로 안 들어온다 — 스케줄러가 `!done` 만 계획에 넣으므로
      **계획이 재생성되는 순간 과거 블록에서도 사라진다**. 예전엔 그 사실이 이 자리에 "⚠ 한계"로
      적혀 있었는데, 그건 문서가 아니라 결함이었다: 끝낸 날부터 그 챕터를 다시 볼 앱 내 경로가
      0이 된다(6개월 전 챕터는 존재하지 않는 것과 같다). 그 구멍은 아래 **유지(maintenance)
      사다리**가 별도 함수로 메운다 — 입력이 '스케줄'이 아니라 '챕터 카탈로그'다.
============================================================ */
import { dayDiff, hash32, REVIEW_OFFSETS, REVIEW_TAIL_OFFSET, addDays, iso, parseISO, reviewBlockMin } from './utils';
import { chapterCoefficient, chapterStrengths, unseenAt, type ChapterStrength } from './chapterStrength';
import { isDone } from './persistence';
import { CBMS_ADVANCES_REVIEW } from './methodology';
import { vaultAnchors } from './vaultAnchors';
import type { AppState, CbmsCode, Day, SessionType } from './types';

export type ReviewRisk = 'fresh' | 'due' | 'overdue';

export interface ChapterReview {
  sid: string;
  subject: string;
  color?: string;
  chapter: string;
  lastDs: string; // 마지막으로 만진 날
  daysSince: number; // 오늘로부터 경과일
  risk: ReviewRisk;
  /** 유지(끝낸 챕터) 출신 표식 — 본 사다리 항목엔 없다(N-10). 큐·UI 가 한 배열에서 구분한다. */
  maintenance?: true;
  /** 앵커가 **볼트 `reviewed:`**(검증 통과일)에서 왔다 — 앱 안에 인출 기록이 아직 없다는 뜻(W2).
   *  UI 는 이걸 배지로 구분해야 한다: 부모가 라이브 관측이 흐르면 이 지표를 폴백으로 강등하라고
   *  적었는데, 구분 없이 승격시키면 강등할 주체가 사라진다(`vaultAnchors.ts` 머리주석). */
  fromVault?: true;
  /** **만성 실패**(A-4). 이 챕터는 앞당김을 받지 않는다 — 처방이 간격이 아니라 자료다.
   *  ⚠ UI 는 이걸 *다른 문구*로 그려야 한다. 표식 없이 빈도만 낮추면 사용자에겐 그냥
   *  "앱이 이 챕터를 잊었다"로 보이고, 그건 이 항목이 만들려던 것의 정반대다. */
  leech?: true;
}

/** 간격반복의 마지막 오프셋(16) 기준: 그 이상 방치=overdue, 마지막 직전(7)↑=due. */
const DUE_DAYS = REVIEW_OFFSETS[REVIEW_OFFSETS.length - 2] ?? 7; // 7
const OVERDUE_DAYS = REVIEW_OFFSETS[REVIEW_OFFSETS.length - 1] ?? 16; // 16
/* ID-10(실패 방향) — 직전 백지가 '막힘'이면 **사다리를 한 칸 앞당긴다**(7→3 · 16→7).
   임의 계수를 만들지 않는 것이 요점이다: 앞당김 폭이 REVIEW_OFFSETS 자신에서 나오므로
   사다리를 고치면 여기가 따라오고, "왜 하필 그 숫자인가"라는 질문이 안 생긴다. */
const FAIL_DUE_DAYS = REVIEW_OFFSETS[REVIEW_OFFSETS.length - 3] ?? 3; // 3
const FAIL_OVERDUE_DAYS = DUE_DAYS; // 7
/* Q-4(통과 방향) — 붙은 챕터는 **한 칸 미룬다**(7→16 · 16→34). 앞당김과 **정확히 대칭**이고
   폭이 역시 사다리 자신에서 나온다(꼬리 34 = `REVIEW_TAIL_OFFSET`). ⚠ **상한 한 칸**이다 —
   두 칸을 허용하면 잘 본 챕터가 두 달 뒤로 사라지고, 그건 간격반복이 아니라 방치다. */
const STRONG_DUE_DAYS = OVERDUE_DAYS; // 16
const STRONG_OVERDUE_DAYS = REVIEW_TAIL_OFFSET; // 34

/**
 * 경과일 → 위험도. `failing` 이면 한 칸 **앞당기고**(ID-10), `strong` 이면 한 칸 **미룬다**(Q-4).
 *
 * ## ⚠⚠ 이 함수는 한동안 의도적으로 **비대칭**이었다 — 그 근거가 2026-08-02 에 무효가 됐다
 * 옛 주석(그대로 옮긴다): _"통과 방향을 정밀하게 하려면 백지 결과가 챕터 단위여야 하는데
 * (현재는 과목-일 단위 = 토대 B) 그 전엔 잘한 챕터와 못 한 챕터가 한 신호를 공유한다.
 * 앞당김은 그 거친 신호로도 안전하다 — 최악이 '덜 급한 챕터를 조금 일찍 본다'이기 때문이다.
 * 반대 방향은 최악이 '잊은 챕터를 안 보여준다'라 같은 근거로 못 넣는다."_
 *
 * **그 전제가 사라졌다**: `blankResults[].chapter` 가 2026-08-01 근본이관 ①로 들어와, 통과/막힘이
 * **챕터 단위로 관측된다**(`chapterStrength`). 즉 미룸을 정밀하게 걸 수 있게 됐다. 그래서 비대칭을
 * 유지할 이유가 없어졌고, Q-4 가 통과 방향을 연다.
 *
 * ## 그래도 남는 두 안전장치
 * ① **상한 한 칸.** 두 칸 미룸은 없다 — 최악이 여전히 "잊은 챕터를 안 보여준다"라서다.
 * ② **`failing` 이 이긴다.** 둘 다 참일 수 없어야 하지만 신호가 갈리면(과목은 막혔는데 이 챕터는
 *    연속 통과) **앞당김을 택한다** — 위험 쪽으로 틀리는 편이 안전하다.
 */
/**
 * @param coef **I-1(W7)** — 챕터별 연속 계수(`chapterCoefficient`). 사다리 칸을 곱해 늘리거나
 *   줄인다. `null` 이면 종전 그대로(칸 이동만).
 *
 * ⚠⚠ **`failing` 은 계수를 안 탄다.** 막힌 챕터에 1.4 를 곱하면 *방금 막힌 것을 더 늦게*
 *   보게 되는데, 그건 이 함수 머리주석의 안전 방향(위험 쪽으로 틀린다)을 정면으로 뒤집는다.
 *   계수는 **base·strong 에만** 적용된다.
 * ⚠ 최소 1일 — 계수가 아무리 작아도 "오늘 보고 오늘 또"가 되지 않게.
 */
export function riskOf(
  daysSince: number,
  failing = false,
  strong = false,
  coef: number | null = null,
  fuzz = 0,
): ReviewRisk {
  const shift = failing ? 'fail' : strong ? 'strong' : 'base'; // failing 이 strong 을 이긴다(안전 방향)
  let over = shift === 'fail' ? FAIL_OVERDUE_DAYS : shift === 'strong' ? STRONG_OVERDUE_DAYS : OVERDUE_DAYS;
  let due = shift === 'fail' ? FAIL_DUE_DAYS : shift === 'strong' ? STRONG_DUE_DAYS : DUE_DAYS;
  if (coef != null && Number.isFinite(coef) && shift !== 'fail') {
    over = Math.max(1, Math.round(over * coef));
    due = Math.max(1, Math.round(due * coef));
  }
  /* I020 평탄화 — 사다리 **전체를** 같은 만큼 민다(칸 간격은 그대로). `failing` 은 안 탄다:
     `coef` 와 **정확히 같은 이유**로, 방금 막힌 챕터를 하루 늦추는 것은 이 함수 머리주석의
     안전 방향(위험 쪽으로 틀린다)을 뒤집는다. 근거 전문은 `chapterFuzz`. */
  if (fuzz && shift !== 'fail') {
    over = Math.max(1, over + fuzz);
    due = Math.max(1, Math.min(due + fuzz, over)); // due 가 over 를 넘어서면 사다리가 뒤집힌다
  }
  if (daysSince >= over) return 'overdue';
  if (daysSince >= due) return 'due';
  return 'fresh';
}

/* ── 부하 평탄화(I020 · 2026-08-22 발상 축) ────────────────────────────────────
   ⚠⚠ **같은 날 시작한 챕터는 영원히 같은 날 몰린다.** 이 파일의 임계는 전부 상수라
   (`DUE_DAYS`·`OVERDUE_DAYS` + 칸 이동 + 계수), 같은 `lastDs` 를 가진 챕터 열 개는 **같은 날
   한꺼번에** `due` 로 넘어간다. 그리고 한 번 몰린 무리는 함께 복습되어 다시 같은 `lastDs` 를
   갖는다 — 몰림이 스스로를 재생산한다.

   밖의 대응은 due 를 날짜에 걸쳐 흩는 것이고, 그 문서가 **스스로 못박는 것**이 요점이다:
   *"재분배지 감면이 아니다"* (docs.ankiweb.net/deck-options.html · 확인 2026-08-22). 총량은
   그대로이고 어느 날이 물리적으로 불가능해지는 것만 막는다.

   ⚠ **±1일이다.** 폭을 키우면 사다리(1·3·7·16)의 칸 간격 자체를 침범한다 — 3↔7 사이가 4일인데
   ±2 를 주면 두 칸이 겹쳐 「사다리」라는 말이 뜻을 잃는다.
   ⚠ **결정적이어야 한다**(난수 금지). 부팅마다 흔들리면 같은 챕터의 due 가 매일 바뀌고,
   사용자에겐 앱이 마음을 바꾸는 것으로 보인다. 파생 키가 **정체성**(sid|chapter)인 것도
   과목 색과 같은 이유다(`utils.colorForId` · 절대규칙 #3): 위치로 파생하면 챕터를 하나
   지웠을 때 뒤 챕터들의 due 가 통째로 밀린다. */

/** 챕터별 결정적 ±1일 흔들기. 소비처는 `riskOf` 의 `fuzz` 하나. */
export function chapterFuzz(sid: string, chapter: string): number {
  return (hash32(sid + '|' + chapter) % 3) - 1; // -1 · 0 · +1
}

/**
 * 직전 백지 복습이 **막힘**으로 끝난 과목 id 집합(ID-10 입력).
 *
 * 과목당 가장 최근(오늘 이하) 백지 결과 하나만 본다 — 오래된 실패가 영원히 따라다니면 그건
 * 간격반복이 아니라 낙인이다. 그 뒤 통과 기록이 있으면 자연히 빠진다.
 * ⚠ 백지 결과는 (날짜, 과목) 단위다(챕터 아님 · 토대 B). 그래서 이 신호는 **과목 전체**에
 *   걸린다 — 같은 과목의 안 막힌 챕터도 함께 앞당겨진다. 위 비대칭 근거가 그것을 허용한다.
 */
export function failingSids(state: AppState, todayDs: string): Set<string> {
  const latest = new Map<string, { ds: string; passed: boolean }>();
  for (const r of state.blankResults || []) {
    if (!r.ds || r.ds > todayDs) continue; // 미래 기록 무시(시드·시계 어긋남 방어)
    const cur = latest.get(r.sid || '');
    if (!cur || r.ds > cur.ds) latest.set(r.sid || '', { ds: r.ds, passed: !!r.passed });
  }
  const out = new Set<string>();
  for (const [sid, v] of latest) if (sid && !v.passed) out.add(sid);
  return out;
}

/**
 * (과목|챕터) → **가장 최근 CBMS 코드**(P-3 입력). 챕터가 빈 기록은 안 센다 — 사다리는 챕터
 * 단위라 붙일 자리가 없다.
 *
 * ⚠ `failingSids` 와 **입도가 다른 것이 이 함수의 전부다.** 저쪽은 백지 결과가 (날짜, 과목)
 * 단위라(토대 B) 신호가 과목 전체에 걸리고, 그래서 같은 과목의 안 막힌 챕터까지 함께
 * 앞당겨진다. CBMS 기록은 **챕터를 알고 있으므로** 그 번짐을 안 만든다.
 * ⚠ 과거의 실패가 영원히 따라다니지 않게 **가장 최근 하나만** 본다(`failingSids` 와 같은 규율 —
 * 오래된 실패가 영원히 남으면 그건 간격반복이 아니라 낙인이다).
 */
export function latestCbmsByChapter(state: AppState, todayDs: string): Map<string, CbmsCode> {
  const latest = new Map<string, { ds: string; at: number; code: CbmsCode }>();
  for (const e of state.cbms || []) {
    const chapter = (e.chapter || '').trim();
    if (!e.sid || !chapter) continue;
    if (!e.ds || e.ds > todayDs) continue; // 미래 기록 무시(시드·시계 어긋남 방어)
    const key = e.sid + '|' + chapter;
    const cur = latest.get(key);
    // 같은 날 여러 건이면 작성시각(`at`)이 동률을 깬다 — 없으면 뒤에 온 것이 이긴다(안정 정렬).
    if (!cur || e.ds > cur.ds || (e.ds === cur.ds && (e.at ?? 0) >= cur.at))
      latest.set(key, { ds: e.ds, at: e.at ?? 0, code: e.code });
  }
  const out = new Map<string, CbmsCode>();
  for (const [k, v] of latest) out.set(k, v.code);
  return out;
}

/* ── 만성 실패(leech · A-4) ────────────────────────────────────────────────
   ⚠⚠ **처방이 한 방향뿐이었다.** 막히면 사다리를 앞당기고(ID-10), 그게 전부다 — 4회째 무너진
   챕터도 10회째 무너진 챕터도 **같은 처방**을 받는다. 그 사이 그 챕터는 큐 앞자리를 계속
   점유하는데, 그것이 밖에서 부르는 `leech` 의 정의 그대로다: *더 자주 보여줘서 시간을 빨아먹는
   항목*. Anki 는 그 지점에서 **스케줄을 만지는 대신 자동으로 멈추고 사람에게 넘긴다** —
   "간격이 문제가 아니라 **자료가 문제**"라는 판정이기 때문이다.

   그래서 이 앱의 두 번째 처방: **앞당김을 멈춘다.** 멈추면 기본 사다리로 되돌아가 등장이
   드물어지고(사라지지 않는다 — 그건 방치다), 대신 화면이 *다른 것*을 요구한다(챕터를 쪼개라 ·
   3문장 요약을 다시 써라 · 문항으로 내려가라).

   ⚠ **임계를 지어내지 않는다** — 이 파일의 규율은 계수를 만들지 않는 것이고(`FAIL_DUE_DAYS`·
   `MAINTENANCE_OFFSETS` 가 전부 사다리에서 파생됐다), 여기서도 임계가 **사다리의 칸 수**다.
   사다리가 바뀌면 이 수가 따라오고 "왜 하필 4인가"가 안 생긴다. */
export const LEECH_FAILS = REVIEW_OFFSETS.length; // 4

export interface Leech {
  sid: string;
  subject: string;
  color?: string;
  chapter: string;
  /** 채점된 시도 중 **막힘**의 수. */
  fails: number;
  /** 총 시도 수(막힘 비율의 분모). */
  attempts: number;
  /** 최근 실패 사이의 간격(일 · 오래된 것 → 최근). **줄어드는데도 계속 실패했다**는 증거. */
  gaps: number[];
}

/**
 * 만성 실패 챕터. `LEECH_FAILS` 회 이상 막혔고 **마지막 시도도 막힘**인 것만.
 *
 * ⚠ 마지막이 통과면 제외한다 — 과거의 실패가 영원히 따라다니면 그건 간격반복이 아니라 낙인이고,
 * 이 파일이 `failingSids`·`latestCbmsByChapter` 에서 이미 두 번 세운 규율이다.
 */
export function leechChapters(state: AppState, todayDs: string, cap = 5): Leech[] {
  /* ⚠ 키로 쪼개지 않고 `sid`·`chapter` 를 **값에 함께 담는다.** 이 파일의 다른 곳은 `sid+'|'+ch`
     를 조회 키로만 쓰는데, 되돌리려고 `split('|')` 하면 챕터명에 `|` 가 있는 순간 조용히 어긋난다. */
  const byChapter = new Map<string, { sid: string; chapter: string; rows: { ds: string; passed: boolean }[] }>();
  for (const b of state.blankResults || []) {
    const chapter = (b.chapter || '').trim();
    if (!b.sid || !chapter || !b.ds || b.ds > todayDs) continue;
    const key = b.sid + '|' + chapter;
    const row = { ds: b.ds, passed: !!b.passed };
    const g = byChapter.get(key);
    if (g) g.rows.push(row);
    else byChapter.set(key, { sid: b.sid, chapter, rows: [row] });
  }
  const itemOf = new Map((state.items || []).map((it) => [it.id, it]));
  const out: Leech[] = [];
  for (const { sid, chapter, rows } of byChapter.values()) {
    rows.sort((a, b) => (a.ds < b.ds ? -1 : a.ds > b.ds ? 1 : 0));
    if (rows[rows.length - 1]!.passed) continue; // 마지막이 통과 → 지금은 leech 가 아니다
    const fails = rows.filter((r) => !r.passed);
    if (fails.length < LEECH_FAILS) continue;
    const it = itemOf.get(sid);
    const gaps: number[] = [];
    for (let i = 1; i < fails.length; i++) gaps.push(dayDiff(fails[i - 1]!.ds, fails[i]!.ds));
    out.push({
      sid,
      subject: it?.name || sid,
      color: it?.color,
      chapter,
      fails: fails.length,
      attempts: rows.length,
      gaps,
    });
  }
  return out
    .sort((a, b) => b.fails - a.fails || (a.subject + a.chapter < b.subject + b.chapter ? -1 : 1))
    .slice(0, cap);
}

/** 사다리 이동 판정에 필요한 것 전부 — 한 번 만들어 여러 챕터에 재사용한다(과목 스캔 반복 방지). */
export interface ShiftContext {
  failing: Set<string>;
  cbmsByChapter: Map<string, CbmsCode>;
  /** `sid|chapter` 집합. */
  leeches: Set<string>;
  strong: (sid: string, chapter: string) => boolean;
  /** I-1 — 챕터별 연속 계수(`chapterCoefficient`). 표본이 얇으면 `null`. */
  coef: (sid: string, chapter: string) => number | null;
}

/** 위 컨텍스트를 만든다. `chapterReviews`·`examStaleChapters` 가 **같은 것을** 쓴다. */
export function shiftContext(state: AppState, todayDs: string): ShiftContext {
  /* ⚠⚠ **강도는 여기서 한 번만 판다**(2026-08-20 리뷰 M-5). 종전엔 `strong`·`coef` 가 클로저라
     호출 시점마다 `chapterStrength` 를 돌렸고, 그 함수는 매번 `blankResults` 전량을
     `.filter().sort()` 한다. 게다가 `chapterShift` 는 같은 (sid, chapter)로 **두 필드를 각각**
     부르므로 챕터당 전량 스캔이 2회였다 — 이 인터페이스의 첫 줄("한 번 만들어 재사용한다 ·
     과목 스캔 반복 방지")이 정확히 그 두 필드에서만 거짓이었다. 지금은 선언이 곧 구현이다. */
  const strengths = chapterStrengths(state, todayDs);
  const at = (sid: string, chapter: string): ChapterStrength =>
    strengths.get(sid + '|' + chapter) ?? unseenAt(state, sid, chapter, todayDs);
  return {
    failing: failingSids(state, todayDs),
    cbmsByChapter: latestCbmsByChapter(state, todayDs),
    leeches: new Set(leechChapters(state, todayDs, Infinity).map((l) => l.sid + '|' + l.chapter)),
    strong: (sid, chapter) => at(sid, chapter).band === 'strong',
    /* ⚠ `strong` 과 **같은 관측**에서 나온다(같은 강도 객체) — 하나는 3구간으로 접고 하나는
       연속으로 쓴다. 두 축이 서로 다른 표본을 보면 화면이 "붙었다"고 말하면서 사다리는 줄어드는
       상태가 생긴다. 이제는 같은 Map 항목이라 갈릴 수가 없다. */
    coef: (sid, chapter) => chapterCoefficient(at(sid, chapter)),
  };
}

/**
 * 이 챕터의 사다리 이동(앞당김/미룸) 판정 — **`chapterReviews` 와 `examStaleChapters` 가 공유**한다.
 *
 * 두 곳이 각자 판정하면 오늘 화면은 "급함"이라 하고 시험 예보는 "괜찮음"이라 말하는 상태가
 * 생기고, 어느 쪽이 맞는지 화면 어디에도 안 적힌다. 규칙 자체는 `riskOf` 머리주석이 소유한다.
 */
export function chapterShift(
  sid: string,
  chapter: string,
  ctx: ShiftContext,
): { failing: boolean; strong: boolean; coef: number | null } {
  /* A-4 — **leech 는 앞당기지 않는다.** 앞당김이 이미 여러 번 실패한 챕터라, 한 번 더 앞당기는
     것은 같은 처방의 반복이다. 기본 사다리로 되돌리면 등장이 드물어지고, 그 자리를 *다른 처방*
     (쪼개기·요약 재작성)이 받는다. ⚠ 미룸(`strong`)도 안 준다 — 붙지 않은 것을 미루면 방치다. */
  /* ⚠ leech 는 계수도 안 받는다 — 계수는 *얼마나 붙었나*의 함수인데, 만성 실패 챕터에 대해
     그 질문은 이미 답이 나와 있고(안 붙는다) 처방이 간격이 아니다(A-4). */
  if (ctx.leeches.has(sid + '|' + chapter)) return { failing: false, strong: false, coef: null };
  const code = ctx.cbmsByChapter.get(sid + '|' + chapter);
  return {
    failing: code ? CBMS_ADVANCES_REVIEW.has(code) : ctx.failing.has(sid),
    strong: ctx.strong(sid, chapter),
    // I-1(W7) — 간격만 연속으로. **표시는 3구간 그대로**(`chapterStrength` 머리주석의 범위 분할).
    coef: ctx.coef(sid, chapter),
  };
}

const TOUCH_TYPES: ReadonlySet<SessionType> = new Set<SessionType>(['new', 'rev', 'blank']);

/** 챕터별 '마지막으로 만진 날' → 경과일·위험도. todayDs 이후(미래) 배치는 무시. 위험 큰 순 정렬. */
/** 챕터별 '마지막으로 만진 날' 표. `sid|chapter` → 그 챕터의 최근 앵커. */
type LastTouch = Map<
  string,
  { ds: string; subject: string; sid: string; color?: string; chapter: string; fromVault?: true }
>;

/* ── 앵커 소스 셋 (2026-08-20 리뷰 M-14 원장 축소) ───────────────────────────────
   ⚠ **동작·순서는 안 바뀐다**: 스케줄(완료된 세션) → 인출 터치(계획 밖) → 볼트(`reviewed:`).
   셋은 서로를 모르고 각자 *어떤 기록이 앵커가 되는가* 만 안다 — 종전엔 한 함수 안에 삼중
   루프째로 겹쳐 있었고 그게 `chapterReviews` 인지복잡도의 대부분이었다. */

/** ① 스케줄에서 **완료된** 터치 세션 → 챕터별 최근일. 미래(`ds > todayDs`)는 무시한다. */
function anchorsFromSchedule(state: AppState, days: Day[], todayDs: string): LastTouch {
  const last: LastTouch = new Map();
  for (const d of days) {
    if (d.ds > todayDs) continue;
    for (const it of d.items) {
      if (!TOUCH_TYPES.has(it.type) || !it.chapters || !it.chapters.length) continue;
      if (!isDone(state, d.ds, it.sid, it.type)) continue;
      for (const ch of it.chapters) {
        const key = it.sid + '|' + ch;
        const cur = last.get(key);
        if (!cur || d.ds > cur.ds)
          last.set(key, { ds: d.ds, subject: it.name, sid: it.sid, color: it.color, chapter: ch });
      }
    }
  }
  return last;
}

/** ② ReviewRun 챕터 터치(계획 밖 인출) 병합 — 계획 파생 lastDs 와 max(감사 #22: 밀린 챕터를
 *  복습해도 overdue 가 안 풀리던 루프). 스캔에 없는 키는 과목 메타를 몰라 건너뛴다 — 위험으로
 *  뜨는 챕터는 완료 이력이 있어 항상 스캔에 존재한다. 미래 ds 는 스캔과 동일하게 무시. */
function mergeRetrievalTouches(last: LastTouch, state: AppState, todayDs: string): void {
  const touches = state.reviewTouches || {};
  for (const k in touches) {
    const ds = touches[k]!;
    const cur = last.get(k);
    if (cur && ds > cur.ds && ds <= todayDs) cur.ds = ds;
  }
}

/** ③ 볼트 `reviewed:` 앵커 주입. ⚠ **앱 앵커가 아예 없는 챕터에만** 넣는다(`last.has` 가 그
 *  가드다) — 볼트 값은 검증 통과일이라 인출 기록을 절대 이기면 안 된다(방향 제약 · 자세한
 *  근거는 `lib/vaultAnchors.ts` 머리주석). 끝낸 챕터는 유지 큐가 소유하므로 여기서 뺀다. */
function mergeVaultAnchors(last: LastTouch, state: AppState, todayDs: string): void {
  const anchors = vaultAnchors();
  if (!anchors.size) return;
  for (const it of state.items || []) {
    for (const ch of it.chapters || []) {
      if (ch.done) continue;
      const key = it.id + '|' + ch.name;
      if (last.has(key)) continue;
      const ds = anchors.get(key);
      if (!ds || ds > todayDs) continue;
      last.set(key, { ds, subject: it.name, sid: it.id, color: it.color, chapter: ch.name, fromVault: true });
    }
  }
}

/** 세 소스를 **선언된 순서로** 합친다. 순서가 규칙이다(뒤가 앞을 조건부로만 보강한다). */
function lastTouchedByChapter(state: AppState, days: Day[], todayDs: string): LastTouch {
  const last = anchorsFromSchedule(state, days, todayDs);
  mergeRetrievalTouches(last, state, todayDs);
  mergeVaultAnchors(last, state, todayDs);
  return last;
}

export function chapterReviews(
  state: AppState,
  days: Day[],
  todayDs: string,
  /** ⚠ 이미 만들어 둔 컨텍스트가 있으면 넘긴다 — 없으면 여기서 만든다. `examStaleChapters` 가
   *  자기 `ctx` 를 만든 뒤 이 함수를 불러 **한 호출에 컨텍스트가 두 벌**이던 것을 없앤다
   *  (2026-08-20 리뷰 M-5). 기본값이 있어 기존 호출부는 한 글자도 안 바뀐다. */
  sharedCtx?: ShiftContext,
): ChapterReview[] {
  const last = lastTouchedByChapter(state, days, todayDs);
  /* ID-10 — 직전 백지가 막힌 과목은 임계를 한 칸 앞당긴다(성패 가중 · 실패 방향만).
     ⚠⚠ **P-3(2026-08-01) — 그 트리거를 챕터의 CBMS 코드가 가른다.** 순서가 규칙이다:
       ① 이 챕터에 최근 CBMS 코드가 있으면 **그것이 결정한다**(지식 결손 계열만 앞당긴다).
       ② 없으면 종전대로 과목 단위 백지 신호(`failingSids`)로 떨어진다.
     ①이 ②를 이기는 이유: CBMS 는 **챕터를 알고** 백지 결과는 과목만 안다. 더 정밀한 신호가
     있는데 거친 신호로 덮으면, 검산 한 번 놓친 챕터(`S`)가 정말 모르는 챕터와 같은 급함을
     갖는다 — 그게 이 항목이 없앤 오탐이다.
     ⚠ 백지 실패는 대개 자기 CBMS('C')를 자동 생성하므로(`setBlankResult`) ①로 흡수된다.
       즉 ②는 "CBMS 를 안 남긴 옛 기록"의 폴백이지 경쟁 경로가 아니다. */
  /* Q-4(통과 방향) — 이 **챕터**가 붙어 있으면 한 칸 미룬다. 신호가 챕터 단위라는 것이 요점이다:
     과목 단위 `failingSids` 로는 못 하던 일이고, 그 불가능이 곧 옛 비대칭의 근거였다.
     ⚠ `strong` 은 `chapterStrength` 의 3구간 중 하나일 뿐이다 — `unseen`(표본 0)은 미룸에
     참여하지 않는다. 안 재 본 챕터를 "잘한다"고 가정하면 그게 가장 나쁜 오류다.
     ⚠⚠ 판정 자체는 **`chapterShift` 한 곳**이 소유한다(A-3 시험 앵커가 같은 규칙을 쓴다). */
  const ctx = sharedCtx ?? shiftContext(state, todayDs);
  const out: ChapterReview[] = [];
  for (const e of last.values()) {
    const daysSince = dayDiff(e.ds, todayDs);
    const key = e.sid + '|' + e.chapter;
    const { failing: failingNow, strong: strongNow, coef } = chapterShift(e.sid, e.chapter, ctx);
    out.push({
      sid: e.sid,
      subject: e.subject,
      color: e.color,
      chapter: e.chapter,
      lastDs: e.ds,
      daysSince,
      risk: riskOf(daysSince, failingNow, strongNow, coef, chapterFuzz(e.sid, e.chapter)),
      ...(e.fromVault ? { fromVault: true as const } : null),
      ...(ctx.leeches.has(key) ? { leech: true as const } : null),
    });
  }
  return out.sort((a, b) => b.daysSince - a.daysSince || (a.subject < b.subject ? -1 : 1));
}

/* ── 유지(maintenance) 큐 — 끝낸 챕터가 사라지지 않게 (N-10) ─────────────────
   `chapterReviews` 의 입력은 **스케줄**이라 done 챕터를 볼 수 없다(엔진이 블록을 안 만든다).
   그래서 여기선 입력을 뒤집어 **챕터 카탈로그**(`items[].chapters`)에서 done 만 훑는다.

   설계 결정 셋:
   ① **사다리를 새로 짓지 않는다** — 본 사다리(1·3·7·16·34)가 대략 2배 성장이므로 꼬리(34)에서
      같은 성장률로 잇는다. "왜 하필 그 숫자"가 안 생기고, 본 사다리를 고치면 여기가 따라온다.
   ② **한 단 강등 — 유지는 절대 `overdue` 가 되지 않는다.** 진행 중 챕터의 overdue 가 유지에
      밀리면 그건 간격반복이 아니라 향수(鄕愁)다. 최대 `due` 라 티어 정렬만으로 불변식이 선다.
   ③ **앵커를 모르는 챕터**(이 기능 이전에 끝낸 것 · `doneDs` 없음)는 '모름'으로 두고 `due` 로만
      취급한다 — 오래됐다고 단정하지 않는다. 한 번 인출하면 `reviewTouches` 가 진짜 앵커를
      남기므로 스스로 교정된다. 수십 장이 한꺼번에 몰리는 것은 소비처의 **세션 상한**이 막는다
      (`reviewQueue.MAINTENANCE_CAP`) — 상한 없이 이걸 켜면 "끝냈는데 전부 다시"가 된다. */
export const MAINTENANCE_OFFSETS: readonly number[] = [
  REVIEW_TAIL_OFFSET,
  REVIEW_TAIL_OFFSET * 2,
  REVIEW_TAIL_OFFSET * 4,
]; // 34 · 68 · 136

export interface MaintenanceReview extends ChapterReview {
  /** 유지 큐 출신 표식 — 본 사다리 항목과 한 배열에 섞일 때의 구분자(UI 문구·정렬). */
  maintenance: true;
  /** 앵커(끝낸 날 또는 마지막 인출)를 아는가. false 면 `daysSince` 는 의미 없다. */
  anchored: boolean;
}

/** 끝낸 챕터의 유지 상태. 앵커를 아는 것 먼저(오래된 순) → 모르는 것(과목·챕터명 결정 순). */
export function maintenanceReviews(state: AppState, todayDs: string): MaintenanceReview[] {
  const touches = state.reviewTouches || {};
  const out: MaintenanceReview[] = [];
  for (const it of state.items || []) {
    for (const ch of it.chapters || []) {
      if (!ch.done) continue;
      // 앵커 = 끝낸 날과 마지막 인출 중 **최신**(미래 값은 시드·시계 어긋남 방어로 무시).
      const cands = [ch.doneDs, touches[it.id + '|' + ch.name]].filter((d): d is string => !!d && d <= todayDs);
      const lastDs = cands.length ? cands.sort()[cands.length - 1]! : '';
      const anchored = !!lastDs;
      const daysSince = anchored ? dayDiff(lastDs, todayDs) : 0;
      out.push({
        sid: it.id,
        subject: it.name,
        color: it.color,
        chapter: ch.name,
        lastDs,
        daysSince,
        // 강등된 사다리: 첫 칸(34일)을 넘겼거나 언제인지 모르면 due, 그 외 fresh. overdue 는 없다.
        risk: !anchored || daysSince >= MAINTENANCE_OFFSETS[0]! ? 'due' : 'fresh',
        maintenance: true,
        anchored,
      });
    }
  }
  return out.sort(
    (a, b) =>
      Number(b.anchored) - Number(a.anchored) ||
      b.daysSince - a.daysSince ||
      (a.subject + a.chapter < b.subject + b.chapter ? -1 : 1),
  );
}

/** 복습 위험(due/overdue) 챕터만, 위험 큰 순 상위 cap개. */
export function riskChapters(state: AppState, days: Day[], todayDs: string, cap = 8): ChapterReview[] {
  return chapterReviews(state, days, todayDs)
    .filter((c) => c.risk !== 'fresh')
    .slice(0, cap);
}

/* ── 과목 인터리빙(ID-2) ────────────────────────────────────────────────────
   위험순(daysSince desc)으로만 정렬하면 한 과목의 밀린 챕터가 큐 앞을 통째로 점유해, 같은
   과목을 연달아 인출하게 된다 — 인터리빙(끼워 학습)이 블록 학습보다 장기 파지에 유리하다는
   학습과학과 어긋난다(Rohrer&Taylor). 그래서 **위험 티어(overdue→due→fresh)는 유지**하되,
   각 티어 '안에서'만 과목 라운드로빈으로 끼운다.

   ⚠ 티어 순서를 유지하는 것이 핵심 불변식이다("위험순 완전 포기 금지=overdue 밀림"): overdue
   챕터는 어떤 인터리빙에도 due 아래로 내려가지 않는다. 티어 내부의 엄격한 daysSince 순서만
   양보한다(그게 인터리빙의 목적). 과목이 하나뿐이면 라운드로빈은 항등이라 순서가 그대로다. */
const RISK_TIERS: readonly ReviewRisk[] = ['overdue', 'due', 'fresh'];

/** 위험 티어는 보존하고 티어 내부만 과목 라운드로빈으로 인터리빙한다. 입력은 위험순 정렬을
 *  가정(chapterReviews 산출) — 과목 회전 순서 = 각 과목의 가장 급한 챕터 등장 순(결정적). */
/**
 * 과목 라운드로빈 한 겹(순수 · 티어 없음). 같은 과목이 연달아 오지 않게 섞되 **각 과목 안의
 * 순서는 보존**한다(입력 순 = 그 과목에서 가장 급한 것부터).
 *
 * ⚠ 제네릭인 이유(E25 · 2026-07-29): 이 규칙이 **복습 큐에서만** 쓰이고 있었다. 계획 쪽
 * `scheduler/layout` 은 생성 순을 그대로 배치해, 앱이 복습 12장에 대해선 인터리빙을 지키면서
 * **하루 6시간의 본 학습에서는 안 지키는** 비대칭이 있었다. 규칙을 두 벌로 만들지 않으려고
 * 키 접근자만 받는다.
 */
export function interleaveByKey<T>(items: T[], keyOf: (t: T) => string): T[] {
  if (items.length < 2) return items.slice();
  const byKey = new Map<string, T[]>();
  for (const it of items) {
    const k = keyOf(it);
    const g = byKey.get(k);
    if (g) g.push(it);
    else byKey.set(k, [it]);
  }
  const groups = [...byKey.values()];
  const out: T[] = [];
  const rounds = Math.max(...groups.map((g) => g.length));
  for (let round = 0; round < rounds; round++) {
    for (const g of groups) if (round < g.length) out.push(g[round]!);
  }
  return out;
}

export function interleaveBySubject(chapters: ChapterReview[]): ChapterReview[] {
  const out: ChapterReview[] = [];
  for (const tier of RISK_TIERS) {
    const inTier = chapters.filter((c) => c.risk === tier);
    if (inTier.length < 2) {
      if (inTier.length) out.push(inTier[0]!);
      continue;
    }
    // 라운드로빈은 `interleaveByKey` 가 소유한다 — 계획 배치와 **같은 한 겹**을 쓴다(E25).
    out.push(...interleaveByKey(inTier, (c) => c.sid));
  }
  return out;
}

/* ── 복습 부하 예보(ID-1) ──────────────────────────────────────────────────
   오늘탭이 '밀린 것'(overdue backlog)을 보여준다면, 여기선 유일하게 비어 있던 시제 —
   '다가오는 복습 파도'를 앞 horizon일 날짜별로 조망한다. 각 챕터를 '마지막 만진 날' +
   간격반복 오프셋(1·3·7·16·34)으로 미래에 투영해, 어느 날 얼마만큼의 복습이 몰릴지를
   '부하의 형태'로 그린다(정확 예측이 아니라 형태 — REVIEW_OFFSETS 는 결정적 사다리다).

   ⚠ Anki(FSRS) 는 미래 due 스케줄을 앱 상태에 두지 않는다(카드 레벨은 Anki 소유). 그래서
      이 순수함수는 **볼트 챕터만** 투영한다 — 예보의 정밀 비대칭을 UI 가 '오늘 기준 Anki due'
      라는 별도 컨텍스트로 정직하게 프레이밍한다(로드맵 ID-1 주석). */

/** 예보 지평(일) — 오늘탭 backlog 다음 2주의 파도를 본다. */
export const FORECAST_HORIZON = 14;
/* 투영에 쓰는 오프셋 = 간격반복 본 사다리 + 꼬리(34) — riskOf 와 같은 모델이라 '오늘 due' 와
   '앞으로 due' 가 같은 규칙을 공유한다(따로 놀지 않게). */
export const FORECAST_OFFSETS: readonly number[] = [...REVIEW_OFFSETS, REVIEW_TAIL_OFFSET];

export interface ForecastSubject {
  sid: string;
  subject: string;
  color?: string;
  count: number;
}
/** 그날 계상된 챕터 1건(앞당길 후보·블록 환산의 원재료). */
export interface ForecastChapter {
  sid: string;
  subject: string;
  color?: string;
  chapter: string;
  /** 그 챕터의 학습 분량(시간 · Chapter.hours). 알 수 없으면 엔진과 같은 1h 폴백. */
  hours: number;
}
export interface ForecastDay {
  ds: string;
  /** 오늘로부터 경과일(1..horizon). */
  offset: number;
  /** 요일(0=일). 주말/평일 시각 구분에 쓴다. */
  wd: number;
  /** 그날 복습 예정 볼트 챕터 총수. */
  chapters: number;
  /** 과목별 분해(내림차순). */
  subjects: ForecastSubject[];
  /** 그날 계상된 챕터 원본 — 분량 큰 순(앞당길 후보 산출용). */
  load: ForecastChapter[];
  /** 부하를 **복습 블록 수**로 환산한 값(N-9). 개수가 아니라 분량으로 재므로 30분짜리와 3시간짜리
   *  챕터가 같은 무게로 세지지 않는다. 부하가 있으면 최소 1(엔진의 복습은 블록 단위라 반올림 0이 없다). */
  blocks: number;
  /** 그날 복습에 쓸 수 있는 가용선(블록). 계획 배열에 그 날이 없으면 **null = 모름**(선을 안 그린다). */
  capBlocks: number | null;
  /** blocks > capBlocks — 그날은 복습이 물리적으로 안 들어간다. 모르면(capBlocks null) false. */
  over: boolean;
}

/* ── 가용선(N-9) ───────────────────────────────────────────────────────────
   개수 막대는 "언젠가 몰린다"까지만 말하고 "그 날은 물리적으로 안 들어간다"를 못 말한다.
   비교가 가능하려면 부하와 가용이 **같은 단위**여야 하는데, 그 단위를 새로 지어낼 필요가 없다 —
   엔진이 이미 "학습 1모듈(ML분)당 복습 1블록(reviewBlockMin)"으로 계획하고 있다. 그래서
     · 부하 = 그날 복습할 챕터들이 **원래 몇 모듈치 학습이었나**(Chapter.hours 합 ÷ ML)
     · 가용 = 그날 복습에 쓸 수 있는 분 ÷ 복습 1블록 분
   둘 다 엔진 상수에서 파생돼 **임의 계수가 0개**다(spacedReview 는 계수를 안 만든다는 규율).

   ⚠ **분이 아니라 블록으로 반올림**한다. `Chapter.hours` 는 볼트 산출에서 노트×0.5h 같은 거친
      추정이라 분 단위 비교는 가짜 정밀이고, 가용선이 틀리면 앱이 "불가능"이라 겁을 준다.
   ⚠ 가용에서 **`rev` 블록은 빼지 않는다** — 계획의 rev 가 바로 이 예보가 투영하는 그것이라,
      빼면 같은 복습을 두 번 세고 가용선이 실제보다 낮아진다(= 없는 위기를 만든다).
   ⚠ 이 예보는 **완료된 학습만** 투영하므로(chapterReviews 의 isDone 게이팅) 미래에 배울 것에서
      나올 복습은 안 들어 있다. 즉 부하는 하한이다 — 그래서 가용선을 넘으면 "정말 넘는다". */

/** `sid|챕터명` → 학습 시간. 엔진의 `Math.max(0.1, +c.hours || 1)` 폴백과 같은 규칙을 쓴다
 *  (같은 챕터가 계획에선 1h, 예보에선 0h 로 세지면 두 화면이 다른 세계를 말한다). */
function chapterHours(state: AppState): Map<string, number> {
  const m = new Map<string, number>();
  for (const it of state.items || [])
    for (const c of it.chapters || []) m.set(it.id + '|' + c.name, Math.max(0.1, +c.hours || 1));
  return m;
}

/** 그날 복습에 쓸 수 있는 분 → 블록. 계획 배열에 없는 날은 null(모름 · 선을 안 그린다). */
function capBlocksOf(day: Day | undefined, revMin: number): number | null {
  if (!day) return null;
  // 이미 계획된 **비복습** 블록(학습·Anki·백지·모의)은 그 시간을 이미 쓴다 → 가용에서 뺀다.
  const committed = day.items.reduce((t, it) => (it.type === 'rev' ? t : t + it.min), 0);
  return Math.floor(Math.max(0, day.studyMin - committed) / revMin);
}

/** 앞 horizon일 날짜별 복습 부하(볼트 챕터) 예보. 챕터 하나가 여러 오프셋 경계에 걸리면
 *  각 날에 계상된다(예: 오늘 만진 챕터 → 1·3·7일에 각각 = 실제 간격반복 파도 모양).
 *  이미 모든 오프셋을 지난(overdue) 챕터는 미래 투영이 음수라 자연히 빠진다(=오늘탭 backlog).
 *  각 날은 부하·가용을 **복습 블록** 단위로 함께 싣는다(위 가용선 주석). */
export function dueForecast(
  state: AppState,
  days: Day[],
  todayDs: string,
  horizon: number = FORECAST_HORIZON,
  /* I019 — **사다리를 인자로 뺀다**(2026-08-22 발상 축). 값을 바꾸기 위해서가 아니라
     «바꾸면 어떻게 되나»를 그리기 위해서다. 기본값은 종전 그대로라 소비처가 안 바뀐다. */
  offsets: readonly number[] = FORECAST_OFFSETS,
): ForecastDay[] {
  // dayOffset(1..horizon) → 그날 계상된 챕터들
  const buckets = new Map<number, ForecastChapter[]>();
  const hoursOf = chapterHours(state);
  const project = (ch: ChapterReview, offsets: readonly number[]): void => {
    const hours = hoursOf.get(ch.sid + '|' + ch.chapter) ?? 1;
    for (const off of offsets) {
      const d = off - ch.daysSince; // 오늘로부터 이 복습까지 남은 일수
      if (d < 1 || d > horizon) continue;
      const at = buckets.get(d);
      const entry: ForecastChapter = { sid: ch.sid, subject: ch.subject, color: ch.color, chapter: ch.chapter, hours };
      if (at) at.push(entry);
      else buckets.set(d, [entry]);
    }
  };
  for (const ch of chapterReviews(state, days, todayDs)) project(ch, offsets);
  /* 끝낸 챕터의 유지 복습도 같은 파도다(N-10) — 예보만 그것을 못 보면 "계획엔 있는데 예보엔
     없는 일"이 생긴다. ⚠ **앵커를 아는 것만** 투영한다: 언제 끝냈는지 모르는 챕터는 미래
     날짜를 특정할 수 없고, 모르는 것을 특정 날짜에 그리면 그 날의 가용선 판정까지 거짓이 된다
     (그쪽은 러너의 세션 상한이 소화한다). */
  for (const ch of maintenanceReviews(state, todayDs)) if (ch.anchored) project(ch, MAINTENANCE_OFFSETS);
  const ML = state.moduleLen || 120;
  const revMin = reviewBlockMin(ML);
  const dayOf = new Map(days.map((d) => [d.ds, d]));
  const base = parseISO(todayDs);
  const out: ForecastDay[] = [];
  for (let d = 1; d <= horizon; d++) {
    const load = (buckets.get(d) || [])
      .slice()
      .sort((a, b) => b.hours - a.hours || (a.subject + a.chapter < b.subject + b.chapter ? -1 : 1));
    const bySid = new Map<string, ForecastSubject>();
    for (const c of load) {
      const cur = bySid.get(c.sid);
      if (cur) cur.count++;
      else bySid.set(c.sid, { sid: c.sid, subject: c.subject, color: c.color, count: 1 });
    }
    const subjects = [...bySid.values()].sort((a, b) => b.count - a.count || (a.subject < b.subject ? -1 : 1));
    const date = addDays(base, d);
    const ds = iso(date);
    // 부하 블록 = 그 챕터들이 원래 몇 모듈치 학습이었나. 부하가 있으면 최소 1블록(복습은 블록 단위).
    const modules = load.reduce((t, c) => t + (c.hours * 60) / ML, 0);
    const blocks = load.length ? Math.max(1, Math.round(modules)) : 0;
    const capBlocks = capBlocksOf(dayOf.get(ds), revMin);
    out.push({
      ds,
      offset: d,
      wd: date.getDay(),
      chapters: load.length,
      subjects,
      load,
      blocks,
      capBlocks,
      over: capBlocks != null && blocks > capBlocks,
    });
  }
  return out;
}

/* ── 시험일 앵커(A-3 · 2026-08-07) ────────────────────────────────────────
   ⚠⚠ **예보가 시험을 못 본다.** `FORECAST_HORIZON` 은 14일 고정이라 시험이 20일 뒤면 예보의
   지평 밖이고, `exam.date` 의 소비처는 D-day 라벨과 엔진 배치뿐이었다. 즉 앱 전체가 **주 단위
   배분**으로 도는데 시험은 **D-day 역산**이라는 어긋남이 여기서 드러난다.

   그런데 시험 대비에서 실제로 답이 필요한 질문은 "며칠 남았나"가 아니라 **"그날 내가 이걸
   기억하고 있나"** 다. 사다리는 그 답을 이미 갖고 있다 — 각 챕터가 시험 전 마지막으로 걸리는
   칸이 언제인지 투영하면, 시험 당일의 **나이**가 나온다.

   설계 결정 둘:
   ① **투영은 공유 사다리(`FORECAST_OFFSETS`), 판정은 챕터별 이동(`chapterShift`).** 예보와 같은
      모델로 투영해야 두 화면이 다른 세계를 말하지 않고, 판정은 "이 챕터가 얼마나 붙었나"에
      달렸으니 이동을 반영해야 한다.
   ② **새 임계를 안 만든다** — `riskOf` 를 그대로 쓴다. "시험용 위험"을 따로 정의하면 그 순간
      같은 챕터가 두 개의 위험도를 갖고, 어느 쪽이 진짜인지 화면 어디에도 안 적힌다. */

export interface ExamStale extends ForecastChapter {
  /** 시험 전 이 챕터가 **마지막으로 사다리에 걸리는 날**. 시험 전에 한 칸도 안 걸리면 `lastDs`. */
  lastBefore: string;
  /** 시험 당일 기준 "마지막으로 본 지 며칠". */
  ageAtExam: number;
  /** 그 나이의 위험도(챕터별 이동 반영). `fresh` 는 목록에 안 들어온다. */
  riskAtExam: ReviewRisk;
  /** 시험 전에 사다리가 한 칸도 안 걸린다 — **지금 넣지 않으면 시험까지 다시 안 본다.** */
  untouched: boolean;
}

/**
 * 시험일에 흔들릴 챕터 — 시험 당일 나이가 큰 순.
 *
 * ⚠ 시험일이 과거면 빈 배열이다(지난 시험으로 오늘을 겁주지 않는다).
 * ⚠ `fresh` 는 제외한다 — 그날 괜찮을 챕터는 이 목록의 목적이 아니고, 넣으면 전 챕터가 나열돼
 * "무엇이 급한가"를 다시 사람이 골라야 한다(이 앱이 반복해서 고쳐 온 그 형태).
 */
export function examStaleChapters(state: AppState, days: Day[], todayDs: string, examDs: string, cap = 8): ExamStale[] {
  const toExam = dayDiff(todayDs, examDs);
  if (toExam < 0) return [];
  const ctx = shiftContext(state, todayDs);
  const hoursOf = chapterHours(state);
  const base = parseISO(todayDs);
  const out: ExamStale[] = [];
  for (const ch of chapterReviews(state, days, todayDs, ctx)) {
    // 시험 전(당일 포함)에 걸리는 칸 중 **가장 늦은 것** — 그게 시험 전 마지막 복습이다.
    let bestIn = -1;
    for (const off of FORECAST_OFFSETS) {
      const d = off - ch.daysSince; // 오늘로부터 그 복습까지 남은 일수
      if (d >= 0 && d <= toExam && d > bestIn) bestIn = d;
    }
    const untouched = bestIn < 0;
    const ageAtExam = untouched ? ch.daysSince + toExam : toExam - bestIn;
    const { failing, strong, coef } = chapterShift(ch.sid, ch.chapter, ctx);
    // I-1 — 시험 앵커도 **같은 계수**를 쓴다(두 곳이 갈리면 오늘 화면과 시험 예보가 다른 말을 한다).
    // I020 — 시험 앵커도 **같은 흔들기**를 쓴다(I-1 계수와 같은 논증: 두 곳이 갈리면 오늘
    // 화면과 시험 예보가 같은 챕터를 두고 다른 말을 한다).
    const riskAtExam = riskOf(ageAtExam, failing, strong, coef, chapterFuzz(ch.sid, ch.chapter));
    if (riskAtExam === 'fresh') continue;
    out.push({
      sid: ch.sid,
      subject: ch.subject,
      color: ch.color,
      chapter: ch.chapter,
      hours: hoursOf.get(ch.sid + '|' + ch.chapter) ?? 1,
      lastBefore: untouched ? ch.lastDs : iso(addDays(base, bestIn)),
      ageAtExam,
      riskAtExam,
      untouched,
    });
  }
  return out
    .sort((a, b) => b.ageAtExam - a.ageAtExam || (a.subject + a.chapter < b.subject + b.chapter ? -1 : 1))
    .slice(0, cap);
}

/* ── A-16 예보의 **한 줄**(W4 · 발산 6회차) ────────────────────────────────────────
   `forecast` 탭이 은퇴하면서 그 화면이 나르던 값을 리드아웃으로 옮긴다. 그 화면은 스스로
   *"Anki 미래 due 를 원리적으로 못 그린다 · 반쪽"* 이라 적었고, 실제로 나른 것은 둘이다:
   ① 앞 14일 파도의 **가장 높은 날** ② 그날이 **가용선을 넘는가**. 둘 다 한 줄에 들어간다.

   ⚠ **평균이 아니라 최대다.** 예보가 답하는 질문은 "언제 무너지나"이고, 평균은 그 질문에
   답하지 않는다(고른 부하와 하루에 몰린 부하가 같은 값이 된다).
   ⚠ 파도가 없으면 `null` — "0장"이라 적으면 *예보가 비었다*와 *앞으로 할 일이 없다*가 같은
   문자열이 된다(이 저장소가 반복해서 물린 형태). 화면은 `null` 이면 리드아웃 자체를 안 건다. */
export interface ForecastPeak {
  /** 오늘로부터 며칠 뒤. */
  offset: number;
  /** 그날 복습 예정 챕터 수. */
  chapters: number;
  /** 그날 부하가 가용선을 넘는가(모르면 false — `capBlocks` 가 null 인 날). */
  over: boolean;
}

/** 앞 14일 중 **가장 높은 날**. 같은 높이면 더 이른 날(대비할 시간이 적은 쪽이 답이다). */
export function forecastPeak(forecast: readonly ForecastDay[]): ForecastPeak | null {
  let best: ForecastDay | null = null;
  for (const d of forecast) {
    if (!d.chapters) continue;
    if (!best || d.chapters > best.chapters) best = d;
  }
  return best ? { offset: best.offset, chapters: best.chapters, over: best.over } : null;
}

/** 앞당길 후보 — 가용선을 넘는 날의 챕터를, **그 전에 여유가 있는 가장 이른 날**로 옮긴다.
 *  분량 큰 것부터(같은 수의 클릭으로 가장 많이 던다) 최대 cap개. 목적지를 못 찾으면 `toOffset:null`
 *  = "오늘 미리 보기"(복습을 앞당기는 건 언제나 가능하다 — 예보에 없는 오늘이 마지막 답).
 *  ⚠ 후보마다 목적지 여유를 1블록씩 소진한다 — 안 그러면 셋 다 같은 날을 가리켜 그 날이 새 파도가 된다. */
export interface PullForward {
  chapter: ForecastChapter;
  /** 목적지 오프셋(1..) · null 이면 오늘. */
  toOffset: number | null;
}
export function pullForwardCandidates(forecast: ForecastDay[], offset: number, cap = 3): PullForward[] {
  const target = forecast.find((f) => f.offset === offset);
  if (!target) return [];
  const slack = new Map<number, number>();
  for (const f of forecast)
    if (f.offset < offset && f.capBlocks != null) slack.set(f.offset, Math.max(0, f.capBlocks - f.blocks));
  return target.load.slice(0, cap).map((chapter) => {
    for (const [off, s] of slack)
      if (s >= 1) {
        slack.set(off, s - 1);
        return { chapter, toOffset: off };
      }
    return { chapter, toOffset: null };
  });
}

/** 위험 요약 — {overdue, due, total 위험 수} (배지·홈 넛지용). */
export function riskSummary(state: AppState, days: Day[], todayDs: string): { overdue: number; due: number } {
  let overdue = 0;
  let due = 0;
  for (const c of chapterReviews(state, days, todayDs)) {
    if (c.risk === 'overdue') overdue++;
    else if (c.risk === 'due') due++;
  }
  return { overdue, due };
}

/* ============================================================
   syllabusIntake.ts — **N-2 강의계획서 인입구**의 파서. 순수 · React 무관 · IO 0.

   ## 왜 이것이 학기 축의 뼈대인가 (발산 6회차)

   T-1 이 학기라는 **그릇**을 만들었다. 그런데 그 그릇은 지금도 거의 비어 있고, 로드맵이 세운
   가설은 그 이유가 *"값이 없어서"* 가 아니라 **입력 비용**이라는 것이다: 개강 첫 주에 사람이
   손에 쥔 것은 과목당 PDF 한 장이고, 앱이 요구하는 것은 그 PDF 를 눈으로 읽어 **날짜 · 주차
   진도 · 과제 마감 · 학사 눈금**을 네 화면에 나눠 다시 치는 일이다. 그래서 아무도 안 채운다.

   이 파일은 그 넷을 **한 번의 붙여넣기**에서 뽑는 깔때기다. N-1(과제 부하) · N-19(학사일정
   눈금) · N-18(학기 목표) · N-3(결산)이 전부 여기서 들어온 값 위에 선다 — 5회차의 T-1 이
   *그릇*이었다면 이건 **깔때기**다.

   ## ⚠ 왜 로컬 AI 가 아니라 정규식인가 (로드맵의 "붙여넣기 → 로컬 AI" 에 대한 정정)

   로드맵은 Ollama 를 적었고 이 앱엔 이미 그 배선이 있다(`src-tauri/ollama.rs`). 그런데
   ① Ollama 프롬프트 빌더를 하나 더 만드는 것은 **Rust 사이클**이고 이 웨이브의 게이트는
   `verify`+`server verify` 다(W3 이 cargo 를 한 번만 돌기로 묶어 뒀다) ② 그리고 더 중요한 것 —
   **추출 결과를 검사할 수 있어야 한다.** 강의계획서의 날짜 표기는 종류가 열 몇 개로 닫혀 있고
   (`3/2` · `3.2` · `3월 2일` · `2026-03-02` · `1주차`), 그 닫힌 집합은 테스트로 잠글 수 있다.
   LLM 추출은 같은 입력에 다른 답을 줄 수 있어 **회귀를 잠그는 방법이 없다**.

   → 그래서 파서가 뼈대이고, AI 는 *파서가 못 읽은 줄*(`unparsed`)에만 붙일 여지로 남긴다.
   그 자리를 남겨 두는 것이 이 설계의 요점이다(지금은 그 수를 화면이 정직하게 말한다).

   ## ⚠ 이웃 `syllabus.ts` 와 다른 파일인 이유

   그 파일은 **T-17 주차 싱크**(교수 진도 ↔ 교재 챕터)이고 이 파일은 **텍스트 → 초안**이다.
   한 번 같은 이름으로 쓰다 덮어쓸 뻔했는데(`lib/retrieval.ts` 와 `retrievalLatency.ts` 가 5회차에
   겪은 것과 같은 형태), 인접해 보인다고 같은 것이 아니다: 저기는 *지금 어디까지 나갔나*,
   여기는 *계획서에 뭐라고 적혀 있나*다. 적용 단계에서 이 파일의 결과가 저 파일의 뮤테이터
   (`setSyllabusMark`)를 부른다 — 그 방향이 둘의 관계다.

   ## 규율 셋

   1. **여기서 아무것도 저장하지 않는다.** 결과는 *초안*(`SyllabusDraft`)이고, 무엇을 받아들일지는
      사람이 고른다 — 강의계획서는 자주 틀리고(작년 날짜가 남아 있다) 자동 반영은 되돌리기가 비싸다.
   2. **못 읽은 것을 센다.** 파서가 조용히 절반을 버리면 화면은 "다 읽었다"고 말한다 — 이 저장소가
      반복해 물린 *조용한 축소 보고*다.
   3. **연도는 학기에서 온다.** `3/2` 에는 연도가 없다. 학기 시작일을 주면 그 해로 읽고, 시작일보다
      이르면 **다음 해**로 넘긴다(겨울 학기가 해를 넘는 형태).
============================================================ */
import { addDays, iso, parseISO } from './utils';
import type { MarkKind } from './types';

/** 눈금 종류의 표시 이름 — 화면이 문구를 새로 지으면 같은 눈금을 화면마다 다르게 부른다.
 *  ⚠ 종류 자체(`MarkKind`)는 **저장 계약**이라 `schema.ts` 가 소유한다(넷으로 닫힌 이유도 거기). */
export const MARK_LABEL: Record<MarkKind, string> = {
  fix: '수강 정정',
  drop: '수강 철회',
  off: '휴강',
  makeup: '보강',
};

/** 주차 진도 한 줄 — `week` 는 1-based(`semesterPhase().week` 와 같은 축). */
export interface SyllabusWeek {
  week: number;
  topic: string;
}

/** 강의계획서에서 읽은 시험 하나. `date` 가 없으면 주차만 알아낸 것(적용 시 개강일로 환산한다). */
export interface SyllabusExam {
  kind: 'mid' | 'final';
  date: string | null;
  week: number | null;
}

/** 과제 하나 — N-1 이 소비한다(마감이 있어야 시간 예산에 들어간다). */
export interface SyllabusTask {
  title: string;
  /** ISO `YYYY-MM-DD`. 마감을 못 읽은 과제는 **초안에 넣지 않는다**(날짜 없는 과제는 예산이 못 쓴다). */
  deadline: string;
}

/** 학사일정 눈금 하나 — N-19.
 *  ⚠ 이름이 `IntakeMark` 인 이유: 이웃 `syllabus.ts`(T-17 주차 싱크)의 `SyllabusMark` 는 **주차 한 점**
 *  이라 같은 이름이 두 뜻을 갖는다. 저기는 *교수가 어디까지 나갔나*, 여기는 *학사일정의 날짜*다. */
export interface IntakeMark {
  kind: MarkKind;
  ds: string;
  label: string;
}

export interface SyllabusDraft {
  weeks: SyllabusWeek[];
  exams: SyllabusExam[];
  tasks: SyllabusTask[];
  marks: IntakeMark[];
  /** 뜻을 못 붙인 **비어 있지 않은** 줄 수. 규율 2 — 화면이 이 수를 그대로 말한다. */
  unparsed: number;
}

export interface ParseOptions {
  /** 학기 시작일(ISO). 연도 없는 날짜(`3/2`)와 주차→날짜 환산의 기준. */
  startDs?: string;
}

/* ── 날짜 읽기 ─────────────────────────────────────────────────────────── */

/** `2026-03-02` · `2026.3.2` · `2026/03/02` — 연도가 **줄 안에** 있는 형태. */
const FULL_DATE = /(20\d{2})\s*[-./]\s*(\d{1,2})\s*[-./]\s*(\d{1,2})/;
/** `3/2` · `3.2` · `3-2` · `3월 2일` — 연도가 없는 형태(학기에서 빌린다).
 *  ⚠ 공백을 `\s?`(하나까지)로 **묶는다** — `\s*` 를 교대(`|`) 양쪽에 두면 역추적이 초선형이 되고
 *  린트(`sonarjs/super-linear-regex`)가 그 자리에서 막는다. 실제 계획서에 `3 / 2` 는 없다. */
const SHORT_DATE = /(?<![\d년])(\d{1,2})\s?(?:월\s?(\d{1,2})\s?일?|[/.-](\d{1,2}))/;
/** `1주차` · `3 주` · `Week 5`. */
const WEEK_NO = /(?:(\d{1,2})\s*주\s*차?|week\s*(\d{1,2}))/i;

function clampDate(y: number, m: number, d: number): string | null {
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;
  const iso0 = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  // 2월 30일 같은 값은 Date 가 다음 달로 굴린다 — 되읽어 대조해 조용한 이동을 막는다.
  return iso(parseISO(iso0)) === iso0 ? iso0 : null;
}

/**
 * 한 줄에서 날짜 하나를 읽는다. 없으면 null.
 *
 * ⚠ 연도 없는 날짜는 **학기 시작일의 해**로 읽고, 그 결과가 시작일보다 이르면 다음 해로 넘긴다 —
 * 겨울 계절학기·해를 넘기는 학기가 그 형태다. 시작일이 없으면 연도를 **지어내지 않는다**(null).
 */
export function readDate(line: string, startDs?: string): string | null {
  const full = FULL_DATE.exec(line);
  if (full) return clampDate(+full[1]!, +full[2]!, +full[3]!);
  if (!startDs) return null;
  const short = SHORT_DATE.exec(line);
  if (!short) return null;
  const m = +short[1]!;
  const d = +(short[2] ?? short[3])!;
  const y = +startDs.slice(0, 4);
  const same = clampDate(y, m, d);
  if (!same) return null;
  return same >= startDs ? same : clampDate(y + 1, m, d);
}

/** 주차 번호 → 그 주의 **월요일 기준 첫날**. 개강일이 없으면 null(주차만으로는 날짜가 없다). */
export function dateOfWeek(week: number, startDs?: string): string | null {
  if (!startDs || week < 1) return null;
  return iso(addDays(parseISO(startDs), (week - 1) * 7));
}

/* ── 줄 분류 ───────────────────────────────────────────────────────────── */

const MARK_WORDS: { kind: MarkKind; re: RegExp }[] = [
  { kind: 'fix', re: /수강\s*(정정|변경|신청\s*정정)/ },
  { kind: 'drop', re: /(수강\s*)?(철회|취소|드랍|드롭)/ },
  { kind: 'off', re: /휴강|공휴일|개교기념/ },
  { kind: 'makeup', re: /보강/ },
];
/** 과제로 읽는 말. ⚠ **'제출' 하나로는 안 잡는다** — 시험 답안 제출까지 과제가 된다. */
const TASK_WORD = /과제|레포트|리포트|보고서|퀴즈|발표|프로젝트/;
const MID_WORD = /중간\s*(고사|시험|평가)/;
const FINAL_WORD = /기말\s*(고사|시험|평가)/;

/**
 * 한 줄이 **무엇을 말하는가** — 시험인가 · 눈금인가 · 과제인가.
 *
 * ⚠⚠ **이 어휘의 집이 하나여야 한다**(I008 · 2026-08-22). `.ics` 인입구가 생기며 같은 판정이
 * 두 경로에 필요해졌고, 사본을 두면 **붙여넣기와 파일이 같은 줄을 다르게 읽는** 날이 온다 —
 * 이 저장소가 손으로 베낀 목록으로 반복해 물린 형태다(오버레이 §1-A). 그래서 `parseSyllabus`
 * 자신도 이 함수를 지난다.
 *
 * ⚠ 우선순위는 **시험 > 과제 > 눈금**이다(`parseSyllabus` 머리주석). 한 줄이 여러 뜻을 가질 때
 * 어느 목록에 넣을지가 여기서 한 번 정해진다 — 호출부마다 정하면 같은 줄이 두 목록에 든다.
 */
export function classifyLine(line: string): { exam: 'mid' | 'final' | null; task: boolean; mark: MarkKind | null } {
  if (MID_WORD.test(line)) return { exam: 'mid', task: false, mark: null };
  if (FINAL_WORD.test(line)) return { exam: 'final', task: false, mark: null };
  if (TASK_WORD.test(line)) return { exam: null, task: true, mark: null };
  return { exam: null, task: false, mark: MARK_WORDS.find((m) => m.re.test(line))?.kind ?? null };
}

/** 주차 줄에서 주제만 남긴다(`3주차:` · 앞의 날짜 · 구분자 제거). */
function topicOf(line: string): string {
  return line
    .replace(WEEK_NO, ' ')
    .replace(FULL_DATE, ' ')
    .replace(/^[\s:·\-—|\t]+/, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

/**
 * 강의계획서 텍스트 → 초안.
 *
 * ⚠ **한 줄이 여러 뜻을 가질 수 있다**(`7주차 3/2 중간고사`). 우선순위는 시험 > 과제 > 눈금이고
 * 주차 진도는 **그 위에 겹쳐서** 기록한다 — 시험 주에도 진도 칸에 내용이 적혀 있기 때문이다.
 * 우선순위를 안 정하면 같은 줄이 두 목록에 들어가 사용자가 지우는 일이 생긴다.
 */
export function parseSyllabus(text: string, opts: ParseOptions = {}): SyllabusDraft {
  const { startDs } = opts;
  const weeks: SyllabusWeek[] = [];
  const exams: SyllabusExam[] = [];
  const tasks: SyllabusTask[] = [];
  const marks: IntakeMark[] = [];
  let unparsed = 0;

  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line) continue;
    const wk = WEEK_NO.exec(line);
    const week = wk ? +(wk[1] ?? wk[2])! : null;
    const date = readDate(line, startDs);
    let used = false;

    if (week !== null && week >= 1 && week <= 30) {
      const topic = topicOf(line);
      if (topic) weeks.push({ week, topic });
      used = true;
    }

    const what = classifyLine(line);
    if (what.exam) {
      exams.push({ kind: what.exam, date, week });
      used = true;
    } else if (what.task && date) {
      // 제목은 날짜·주차를 걷어낸 나머지 — 없으면 '과제'로 둔다(빈 제목은 목록에서 못 고른다).
      const title = topicOf(line)
        .replace(SHORT_DATE, ' ')
        .replace(/\s{2,}/g, ' ')
        .trim();
      tasks.push({ title: title || '과제', deadline: date });
      used = true;
    } else if (what.mark && date) {
      /* ⚠ 짧은 날짜(`4/6`)를 라벨에서 걷는다 — 과제 제목은 이미 그렇게 하는데(위) 눈금만
         안 하고 있었다. 날짜는 `ds` 가 이미 들고 있으므로 라벨의 날짜는 **중복**이고, 그 중복이
         오늘 화면의 배지에서 «4/6 휴강 D-3» 처럼 두 번 읽힌다(I010 이 그 배지를 세우며 드러났다). */
      const label = topicOf(line)
        .replace(SHORT_DATE, ' ')
        .replace(/\s{2,}/g, ' ')
        .trim();
      marks.push({ kind: what.mark, ds: date, label: label.slice(0, 40) || MARK_LABEL[what.mark] });
      used = true;
    }
    if (!used) unparsed++;
  }

  return { weeks, exams, tasks, marks, unparsed };
}

/** 초안이 비었나 — 화면이 "한 줄도 못 읽었다"를 말할 수 있게(규율 2). */
export function draftIsEmpty(d: SyllabusDraft): boolean {
  return !d.weeks.length && !d.exams.length && !d.tasks.length && !d.marks.length;
}

/* ============================================================
   syncLedger.ts — 동기화 원장의 **판정**(순수 · E12 · 2026-07-29).

   이 판정이 lib 에 있는 이유: 폰 헤더와 데스크톱 레일이 **같은 조건에서** 말하고 같은 조건에서
   침묵해야 한다. 화면마다 "언제 말할까"를 다시 정하면 두 기기가 서로 다르게 침묵하게 되고,
   그 차이는 아무 데도 안 적힌다(§9-4 — 화면은 따로, 규칙은 lib).

   ⚠ 층이 갈린 이유도 적어 둔다: `components` 는 `store` 를 import 할 수 없다(레이어 경계 린트).
   그래서 셋으로 나뉜다 — **판정=lib(여기)** · **읽기=store/useSyncLedger** · **그리기=components**.
============================================================ */
import { agoLabel } from './utils';

export interface Ledger {
  online: boolean;
  /** 대기 중(아직 못 올린) 편집 수. 셀 수 없으면 null — **0 과 구분한다**(모름 ≠ 없음). */
  pending: number | null;
  /** 마지막으로 **성공한** 동기화 시각(epoch ms). 없으면 null. */
  at: number | null;
  failed: boolean;
  /**
   * 재시도가 무의미한 중단 사유. 없으면 null.
   *
   * ⚠ **출처가 둘이다(H5 · 2026-07-31 `/감사 근본`)**: push 축은 `push.status === 'blocked'`,
   * pull 축은 바깥 `SyncResult.status === 'blocked'`. 종전엔 앞의 것만 봤는데, 아웃박스가 빈
   * 상태(= push `idle`)에서 D1 일일 한도가 소진되면 중단이 pull 쪽에서만 나타나 원장이
   * `failed` 분기의 _"다음 시도에 다시 올려요"_ 를 말했다 — 자기치유를 함의하는 거짓 위로다.
   * 조립은 `store/useSyncLedger.ts` 가 한다.
   *
   * ⚠⚠ **이 축이 없어서 원장이 거짓말을 하고 있었다**(H3 · 2026-07-30 `/감사 근본`).
   * `runSyncOnce` 는 push 가 `blocked` 여도 `SyncResult.status:'ok'` 를 돌려준다 — pull 은
   * 멀쩡히 됐기 때문이다. 그런데 blocked 는 **워터마크를 전진시키지 않으므로** 대기 건수가
   * 영원히 안 줄고, 원장은 `waiting` 분기에 걸려 _"올리는 중 — N건 대기"_ 를 **무한히** 말했다.
   * "올리는 중"은 곧 끝난다는 뜻인데 실제로는 사람이 손대기 전까지 아무 일도 안 일어난다.
   *
   * ⚠ 우선순위가 **오프라인보다 위**다. 오프라인은 스스로 낫고 blocked 는 안 낫는다 —
   * 기기 폐기·D1 한도·인증 만료는 전부 사람이 무언가를 해야 풀린다. 그 조건을 "오프라인"으로
   * 덮으면 사용자는 네트워크가 돌아오기를 기다리며 계속 편집한다.
   */
  blocked: string | null;
  /**
   * **이 세션에서 아직 한 번도 동기화가 끝나지 않았다**(Q-23 · 2026-08-02).
   *
   * ⚠⚠ 이 필드가 없던 동안 부팅 직후 원장은 **완전히 침묵했다.** `at === null && pending === null
   * && !failed` 이 곧 아래 "클라우드를 안 붙였으면 침묵한다" 분기와 **구분되지 않았기** 때문이다.
   * 그런데 이 앱은 로컬이 정본이라 화면이 **즉시 그려진다** — 즉 첫 pull 이 도착하기 전에도
   * 어제 상태가 아무 유보 없이 *확정된 오늘*처럼 보였고, 다른 기기에서 한 편집은 몇 초 뒤에
   * 소리 없이 나타났다. "아직 모른다"와 "볼 것이 없다"는 다른 사실이다.
   *
   * ⚠ **연결 안 됨과 구분되어야 한다.** 클라우드를 안 붙인 사용자에게 "확인 중"은 영원히 끝나지
   * 않는 거짓말이다 — 그래서 이 값은 `store/useSyncLedger` 가 **자격증명이 있을 때만** 켠다.
   */
  checking: boolean;
}

/**
 * 원장이 지금 무슨 말을 하나. 말할 것이 없으면 null(그리지 않는다).
 *
 * ⚠⚠ **한 번도 성공한 적 없으면 아무 말도 안 한다.** 처음엔 `'방금'` 폴백을 뒀다가 실렌더에서
 * 잡혔다: 헤더에 "토큰 갱신 실패(503)"가 떠 있는데 바로 아래에서 "· 방금 동기화"라고 말했다 —
 * 이 원장이 막으려던 **바로 그 거짓말**을 원장 자신이 한 것이다. `at === null` 은 "방금"이 아니라
 * "모른다/아직 없다"이고, 그때 대기도 0이면 말할 것이 없다(0·평온은 아무것도 안 그린다).
 * ⚠ 클라우드를 안 붙였으면 통째로 침묵한다 — 이 앱은 클라우드 없이도 완결된다.
 *   "한 번도 성공한 적 없고 대기도 셀 수 없다"가 그 상태의 관측 가능한 형태다.
 */
export function ledgerLine(led: Ledger, now: number): { text: string; warn: boolean } | null {
  /* ⚠ blocked 가 **가장 먼저**다 — 유일하게 스스로 낫지 않는 상태라서다(위 필드 주석).
     "이 기기에 남아 있어요"를 함께 말하는 것이 계약이다: 중단은 곧 유실이라고 읽히기 쉬운데,
     실제로는 워터마크가 안 움직였을 뿐 편집은 전부 로컬에 있다. */
  if (led.blocked) {
    return { text: `동기화 중단 — ${led.blocked} (편집 ${led.pending ?? 0}건은 이 기기에 남아 있어요)`, warn: true };
  }
  /* ⚠ **첫 확인은 오프라인보다 아래, blocked 보다 위가 아니다** — 중단은 스스로 안 낫지만 첫
     확인은 몇 초 뒤 스스로 끝난다. 그래서 blocked 다음, 나머지보다 앞이다. 오프라인이면 확인이
     시작조차 못 하므로 그쪽 문구가 더 정확하다. */
  if (led.checking && led.online) return { text: '확인 중 — 다른 기기의 편집을 받아오는 중이에요', warn: false };
  if (led.at === null && led.pending === null && !led.failed) return null;
  const waiting = led.pending != null && led.pending > 0;
  const warn = !led.online || led.failed || waiting;
  const text = !led.online
    ? `오프라인 — 편집 ${led.pending ?? 0}건은 이 기기에 저장돼 있어요`
    : led.failed
      ? /* ⚠ 대기가 없으면 **건수를 말하지 않는다**(H3). 종전엔 늘 "편집 0건이 대기 중이에요"라
           적었는데, 0건 대기는 사실이 아니라 잡음이다 — 그리고 이 원장의 존재 이유가 "숫자가
           있으면 말하고 없으면 침묵한다"이다. 실제로 폰 헤더에서 그 문구가 보이기 시작하며
           드러났다(H3 의 구독이 붙기 전까지는 이 분기가 화면에 도달한 적이 없었다). */
        waiting
        ? `동기화 실패 — 편집 ${led.pending}건이 대기 중이에요`
        : '동기화 실패 — 다음 시도에 다시 올려요'
      : waiting
        ? `올리는 중 — ${led.pending}건 대기`
        : led.at != null
          ? `· ${agoLabel(led.at, now)} 동기화`
          : null;
  return text === null ? null : { text, warn };
}

/* ============================================================
   vault.ts — 옵시디언 볼트 현황(File System Access API) — 서버/외부 데이터.
   정본 _meta/cache/_index.json(검사.sh --index 산출)을 우선 소비하고, 없으면 .md 직접 스캔.
   순수 계산 + FS 읽기만(앱 상태에 복제 X). TanStack Query가 스캔 결과를 캐시(설계도 §1-B).
============================================================ */
import { SKIP, rid } from './utils';
import { dirEntries, pickDirectory, queryPermission, requestPermission } from './fsAccess';
import { vaultScan } from './tauri';
import { parseArtifact } from './artifacts';
import type { Chapter } from './types';

export interface VaultChapter {
  name: string;
  notes: number;
  verified: number;
  exported: number;
  legacy: number;
  wip: number;
  /** 이 챕터 노트들의 `reviewed:` 중 **가장 최근**(없으면 ''). 볼트가 아는 유일한 망각 시계다(W2). */
  reviewedRecent: string;
  /** `anki_state === 'stale'` 인 노트 수 — 노트는 고쳤는데 카드가 안 따라온 것. */
  ankiStale: number;
  /** 이 챕터에서 `prereq_in`(이걸 알면 몇 개가 풀리나) 최댓값. */
  prereqIn: number;
}
export interface VaultSubject extends VaultChapter {
  chapters: VaultChapter[];
}
export interface VaultScan {
  at: string;
  src: string;
  subjects: VaultSubject[];
  /** I006 — 원본 노트(파일 이름 포함). 집계는 «몇 개»를, 이것은 «어느 파일»을 답한다.
   *  ⚠ 옵셔널이다 — 브라우저 폴백 경로(FSA)는 아직 안 싣는다(셸이 배포 진입점이다). */
  notes?: IndexNote[];
}

/** 정본 인덱스(_meta/cache/_index.json) 로드 — 없으면 null(호출부가 파일스캔 폴백). */
export async function loadVaultIndex(
  handle: FileSystemDirectoryHandle,
): Promise<{ notes?: unknown[]; anki?: unknown[] } | null> {
  try {
    const meta = await handle.getDirectoryHandle('_meta');
    const aud = await meta.getDirectoryHandle('cache'); // P7 Phase 3: 감사→cache(파생)
    const fh = await aud.getFileHandle('_index.json');
    const idx = JSON.parse(await (await fh.getFile()).text());
    parseArtifact('index', idx); // parent↔hub 버전 + 모양 드리프트 경고(비차단)
    return idx;
  } catch {
    return null;
  }
}

/* ⚠⚠ **경계에서 필드를 버리지 말 것(W2 · 2026-07-31).** 종전엔 17키 중 5키만 뽑았고, 증발하는
   것 중에 **`reviewed`(468건에 날짜가 있다)** 와 **`anki_state`** 가 있었다 — 앱은 "복습 0/0"이라
   말하면서 그 답을 아는 파일을 매번 읽고 있었다. 인덱스 스키마(`artifacts.gen.ts` `indexArtifactSchema`)
   는 이 필드를 **이미 전부** 알고 있었으므로, 여기 좁은 인터페이스가 유일한 병목이었다.
   ⚠ 필드를 늘려도 **집계는 여전히 이 파일 하나**가 소유한다(Rust 는 레코드까지만 · 3단계-B 규율). */
export interface IndexNote {
  kind?: string;
  subject?: string;
  folder?: string;
  /** I006 — 노트 파일 이름. 경계에서 **버리던 필드**였고, 그래서 앱은 노트가 있다는 것을 알면서
   *  그것을 열 수 없었다(`src-tauri/src/vault.rs` 의 `Note.file` 주석이 근거의 SSOT). */
  file?: string | null;
  status?: string;
  anki_exported?: boolean;
  /** 검증 통과일(파이프라인). ⚠ **인출일이 아니다** — 위험을 올리는 방향으로만 쓴다(vaultAnchors). */
  reviewed?: string | null;
  /** 'ok' | 'none' | 'stale' — 노트↔카드 동기 상태. */
  anki_state?: string | null;
  /** 이 노트를 선행으로 삼는 노트 수(링크 인입). */
  prereq_in?: number;
  tier_hint?: string | null;
  role?: string | null;
  type?: string | null;
  flags?: unknown[];
}

/** _index.json.notes → 과목→챕터 집계. status=null=구버전(verified와 구분 · A-2). */
export function subjectsFromIndex(idx: { notes?: IndexNote[] }): VaultSubject[] {
  const bySubj: Record<string, VaultSubject & { _ch: Record<string, VaultChapter> }> = {};
  const zero = { notes: 0, verified: 0, exported: 0, legacy: 0, wip: 0, reviewedRecent: '', ankiStale: 0, prereqIn: 0 };
  for (const n of idx.notes || []) {
    if (n.kind === '실전문제') continue; // 실전문제는 검증%·노트수 분모에서 제외(대시보드 isProb와 정합)
    const sj = n.subject || '?';
    const parts = (n.folder || sj).split('/');
    const ch = parts.length > 1 ? parts.slice(1).join('/') : '(과목 루트)';
    const S = bySubj[sj] || (bySubj[sj] = { name: sj, _ch: {}, ...zero, chapters: [] });
    const C = S._ch[ch] || (S._ch[ch] = { name: ch, ...zero });
    // `reviewed` 는 **최댓값**(가장 최근) — 챕터 안에서 한 노트라도 최근에 검증됐으면 그게 앵커다.
    const rv = n.reviewed || '';
    if (rv > C.reviewedRecent) C.reviewedRecent = rv;
    if (rv > S.reviewedRecent) S.reviewedRecent = rv;
    if (n.anki_state === 'stale') {
      C.ankiStale++;
      S.ankiStale++;
    }
    const pin = +(n.prereq_in || 0);
    if (pin > C.prereqIn) C.prereqIn = pin;
    if (pin > S.prereqIn) S.prereqIn = pin;
    const st = n.status || '';
    const ver = st === 'verified';
    const leg = !st;
    const wip = !!st && !ver; // raw/drafted(파이프라인 진행중)
    const exp = !!n.anki_exported;
    C.notes++;
    S.notes++;
    if (ver) {
      C.verified++;
      S.verified++;
    }
    if (exp) {
      C.exported++;
      S.exported++;
    }
    if (leg) {
      C.legacy++;
      S.legacy++;
    }
    if (wip) {
      C.wip++;
      S.wip++;
    }
  }
  return Object.values(bySubj).map((s) => {
    const chapters = Object.values(s._ch);
    const { _ch, ...rest } = s;
    void _ch;
    return { ...rest, chapters };
  });
}

/** 프론트매터를 찾기 위해 읽는 선두 길이(**바이트** — `Blob.slice` 는 바이트 단위다).
 *  ⚠ `src-tauri/src/vault.rs` 의 `FM_HEAD_BYTES` 와 **같은 값·같은 단위**여야 한다. 종전에 저쪽이
 *  `chars().take(1600)`(문자)였고 주석은 "동형"이라 적어, 한글 노트에서 최대 3배를 읽었다. */
const FM_HEAD_BYTES = 1600;

async function readFM(fh: FileSystemFileHandle): Promise<Record<string, string>> {
  try {
    const f = await fh.getFile();
    const t = (await f.slice(0, FM_HEAD_BYTES).text()) as string;
    // `\s*\n`이 아니라 `[ \t]*\r?\n` — `\s`가 개행을 포함해 `\s*\n`과 뒤따르는 lazy `[\s\S]*?`가
    // 같은 문자를 두고 겹치면서 백트래킹이 초선형이 된다(sonarjs/super-linear-regex).
    // 문자 클래스를 겹치지 않게 가르면 모호성이 사라지고, 덤으로 CRLF 볼트도 인식한다.
    const m = t.match(/^---[ \t]*\r?\n([\s\S]*?)\r?\n---/);
    if (!m) return {};
    const o: Record<string, string> = {};
    m[1]!.split('\n').forEach((l) => {
      const i = l.indexOf(':');
      if (i > 0) o[l.slice(0, i).trim()] = l.slice(i + 1).trim();
    });
    return o;
  } catch {
    return {};
  }
}

/** 순회에서 통째로 건너뛸 폴더인가 — `_`/`.` 접두(파생·시스템)와 SKIP 목록.
    ⚠ **모든 깊이에서** 적용해야 한다. 실제 볼트에 `기초 수학/미적분/.trash`·`.../_리포트` 처럼
    깊은 곳에도 있어서, 최상위에서만 거르면 휴지통 노트가 집계에 섞인다. */
function skipDir(name: string): boolean {
  return name.startsWith('_') || name.startsWith('.') || SKIP.has(name);
}
/** 집계에서 뺄 노트 파일인가(파일명 기준). 정본 인덱스는 파이프라인이 생성 시점에 걸러 주므로
    이 필터는 **폴백 경로가 인덱스의 분모를 흉내내는** 장치다.
    ⚠ 흉내에는 원리적 한계가 있다 — 인덱스는 `kind`(개념노트·집합체·실전문제)로 분류하는데
    폴백엔 그 정보가 없어 파일명으로만 유추한다. 실측(실제 볼트): 이 차이로 남는 오차는
    **노트 1개**(`기초 수학/🏠 수학노트 홈.md` — 이름에 MOC 가 없지만 파이프라인은 제외).
    깊이 결함을 고치기 전엔 오차가 **239개**였으니, 남은 1개는 감수한다. */
function skipNote(fn: string): boolean {
  return !fn.endsWith('.md') || fn.includes('MOC') || fn.includes('실전문제');
}

/** 볼트 트리를 **임의 깊이**로 순회해 정본 인덱스와 같은 모양의 노트 레코드를 만든다.
 *
 *  ⚠ **깊이 2단 고정이 실제로 46%를 버리고 있었다.** 예전 구현은 `과목/챕터/` 안에서 파일만
 *  집계하고 디렉터리는 조용히 `continue` 했다 — 실측(2026-07-19, 실제 볼트): 전체 519개 중
 *  폴백이 보는 건 280개, **239개(46%)가 누락**. `기초 수학/미적분/01 극한과 연속/*.md` 처럼
 *  3단 구조가 실재하는데, 사용자에겐 "노트 수가 좀 적네"로만 보여 진단이 불가능했다.
 *
 *  인덱스 경로(`subjectsFromIndex`)는 `folder` 문자열을 쪼개 임의 깊이를 이미 지원했다 —
 *  즉 두 경로가 **서로 다른 볼트 구조를 지원**하고 있었고 그게 문서화된 적도 없었다.
 *  이제 폴백도 같은 레코드를 만들어 **같은 집계 함수**에 넣는다(분기 자체를 없앤다). */
async function notesFromFiles(handle: FileSystemDirectoryHandle): Promise<IndexNote[]> {
  const out: IndexNote[] = [];
  const walk = async (dir: FileSystemDirectoryHandle, subject: string, folder: string): Promise<void> => {
    for await (const [name, h] of dirEntries(dir)) {
      if (h.kind === 'directory') {
        if (skipDir(name)) continue;
        await walk(h as FileSystemDirectoryHandle, subject, `${folder}/${name}`);
      } else if (h.kind === 'file' && !skipNote(name)) {
        const fm = await readFM(h as FileSystemFileHandle);
        out.push({
          subject,
          folder,
          status: fm.status,
          // ⚠ 값은 boolean 이 아니라 **날짜 문자열**이다(실측: `anki_exported: 2026-07-11`).
          //    존재 자체가 "내보냄"이므로 truthy 판정이 맞다 — boolean 으로 파싱하려 들면 안 된다.
          anki_exported: !!fm.anki_exported,
          // W2 — 폴백도 같은 레코드를 만든다(인덱스 경로와 모양이 갈리면 같은 볼트에서 숫자가 갈린다).
          // ⚠ `anki_state`·`prereq_in` 은 프론트매터에 없다(파이프라인 파생) — 폴백에선 원리적으로 모른다.
          reviewed: fm.reviewed || '',
        });
      }
    }
  };
  for await (const [name, h] of dirEntries(handle)) {
    if (h.kind !== 'directory' || skipDir(name)) continue;
    await walk(h as FileSystemDirectoryHandle, name, name);
  }
  return out;
}

/** 폴백: 정본 인덱스가 없을 때 .md 직접 스캔(구버전 status 없음도 집계).
    집계는 **인덱스 경로와 같은 함수**를 쓴다 — 예전엔 별도 구현이라 깊이·verified 판정이
    서로 달랐다(같은 볼트에서 숫자가 갈렸다). */
export async function scanVaultFromFiles(handle: FileSystemDirectoryHandle): Promise<VaultSubject[]> {
  return subjectsFromIndex({ notes: await notesFromFiles(handle) });
}

/** 폴더 선택 → 스캔(정본 인덱스 우선·.md 폴백). 사용자가 취소하면 null.
 *  handle도 함께 반환 — Anki 패널이 같은 볼트 폴더를 재선택 없이 재사용(레거시 vaultHandle 공유). */
export async function pickAndScanVault(
  existing?: FileSystemDirectoryHandle,
): Promise<{ scan: VaultScan; handle: FileSystemDirectoryHandle } | null> {
  let handle = existing;
  if (!handle) {
    const picked = await pickDirectory(); // 미지원이면 FsUnsupportedError, 취소면 null
    if (!picked) return null;
    handle = picked;
  }
  const idx = await loadVaultIndex(handle);
  let subjects: VaultSubject[];
  let src: string;
  if (idx && Array.isArray(idx.notes)) {
    subjects = subjectsFromIndex(idx as { notes: IndexNote[] });
    src = '정본 _index.json';
  } else {
    subjects = await scanVaultFromFiles(handle);
    src = '파일 스캔(.md)';
  }
  return { scan: { at: new Date().toLocaleString('ko'), src, subjects }, handle };
}

/** 셸(Tauri)에서 볼트를 읽는다 — **폴더 선택도 권한도 없다.**
 *  `workspace.rs` 가 이미 워크스페이스를 알고 볼트는 `<workspace>/knowledge` 라, 사용자에게
 *  폴더를 물을 이유가 자체가 없다. 브라우저에선 null → 호출부가 기존 FSA 경로로 간다.
 *
 *  ⚠ Rust 는 **노트 레코드까지만** 만든다. 집계는 여기 `subjectsFromIndex` 하나가 소유한다 —
 *  3단계-B 에서 집계가 두 벌이라 같은 볼트에서 숫자가 갈리던 결함을 고쳤으니, 언어를 바꿔
 *  세 번째 구현을 만들지 않는다. */
/** 볼트 스캔 실패의 **쿼리 캐시 자리**(U006). `null` = 지금 문제 없음. */
export const VAULT_ERROR_KEY = ['vaultError'] as const;

/**
 * 이 실패가 **"아직 설정 안 됨"** 인가(= 실패가 아니다).
 *
 * ⚠ `vault.rs` 의 `vault_scan` 은 폴더 미설정도 `Err("볼트 폴더를 찾지 못했습니다…")` 로 답한다.
 * 그 갈래를 에러 배너로 올리면 **워크스페이스를 아직 안 정한 신규 사용자에게 장애를 보고**하게
 * 되고, 그건 `classifyArtifact` 가 SSOT 로 잠근 오분류(미생성을 장애로) 그 자체다. 문자열
 * 계약인 것이 마음에 안 들지만 `isNotYetError` 가 이미 같은 형태를 쓴다 — 두 벌로 갈리지
 * 않게 판정을 여기 하나에 둔다.
 */
export function isVaultUnset(e: unknown): boolean {
  return (e instanceof Error ? e.message : String(e ?? '')).includes('볼트 폴더를 찾지 못했');
}

export async function scanVaultViaShell(): Promise<VaultScan | null> {
  const res = await vaultScan();
  if (!res) return null;
  return {
    at: new Date().toLocaleString('ko'),
    src: res.src,
    subjects: subjectsFromIndex({ notes: res.notes as IndexNote[] }),
    /* I006 — **원본 노트도 함께 싣는다**(2026-08-22). 집계(`subjects`)는 «몇 개인가»를 답하고
       원본은 «어느 파일인가»를 답한다 — 노트를 열려면 후자가 필요한데, 종전엔 이 경계에서
       버려졌다. 별도 질의 키를 파지 않는 이유: 두 값의 신선도가 갈리면 «집계는 새 것인데
       파일 목록은 옛 것» 이 되고 그때 여는 것은 없는 파일이다. */
    notes: res.notes as IndexNote[],
  };
}

/* ── 저장된 핸들 재사용(FS 권한) — IDB에 영속한 폴더 핸들로 재선택 없이 재연결.
   권한은 재시작 뒤 'prompt'로 돌아갈 수 있어(브라우저 정책), 조회→요청 2단계로 다룬다. */
/** 저장된 핸들의 읽기 권한 상태 — 'granted'면 제스처 없이 스캔 가능. */
export async function queryVaultPermission(handle: FileSystemDirectoryHandle): Promise<PermissionState> {
  return queryPermission(handle, 'read');
}
/** 저장된 핸들에 읽기 권한 요청(사용자 제스처 안에서 호출). */
export async function requestVaultPermission(handle: FileSystemDirectoryHandle): Promise<PermissionState> {
  return requestPermission(handle, 'read');
}

/** 노트 수 → 예상시간(h). */
export function estH(notes: number): number {
  return Math.max(1, Math.round(notes * 0.5));
}

/** 볼트 챕터 → 학습 항목 챕터(예상시간 추정). */
export function chaptersFromVault(chs: VaultChapter[]): Chapter[] {
  return chs.map((c) => ({ id: rid(), name: c.name, hours: estH(c.notes), done: false }));
}

/* ── I006 **챕터 → 노트 파일 해석**(2026-08-22 발상 축) ─────────────────────────────────

   앱은 «이 챕터를 공부하라»고 말할 수 있지만 그 일을 **시작시킬 수는 없었다** — 노트를 여는
   경로가 0이었다. 그 첫 조각이 이 함수다: 블록이 가리키는 챕터가 **어느 파일 하나**인가.

   ⚠⚠ **유일해야 연다.** 여럿이면 `null` 이다 — 어느 것을 여는지 사용자가 모르는 채로 파일이
   열리면, 그건 «대상을 연다»가 아니라 «아무거나 연다»다. 그 회차의 최싼검증이 정확히
   *"유일 노트 파일로 해석되는 비율"* 인 것도 그래서다(<60%면 매칭이 먼저다).
   ⚠ 매칭은 **폴더 경로의 마지막 조각**으로 한다 — `subjectsFromIndex` 가 챕터 이름을 만드는
   방식(`folder.split('/').slice(1)`)과 **같은 규칙**이어야 한다. 갈리면 화면이 아는 챕터와
   여기서 찾는 챕터가 다른 것이 되고, 그건 조용하다. */

/** 그 과목·챕터의 노트가 **정확히 하나**면 볼트 상대경로, 아니면 `null`. */
export function noteRelFor(notes: readonly IndexNote[], subject: string, chapter: string): string | null {
  const hits = notes.filter((n) => {
    if (!n.file || (n.subject || '') !== subject) return false;
    const parts = (n.folder || n.subject || '').split('/');
    const ch = parts.length > 1 ? parts.slice(1).join('/') : '(과목 루트)';
    return ch === chapter;
  });
  const only = hits.length === 1 ? hits[0] : undefined;
  return only?.file ? `${only.folder || only.subject || ''}/${only.file}` : null;
}

